INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20067, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有劳动能力的人失去工作，没有收入。", "primary_collocate": null, "pronunciation": "shī yè", "ipa": "ʂʅ˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "有些人认为，应该给失业的人提供更多的职业培训。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他上个月失业了，现在正在找新工作。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司关门以后，很多工人都失业了。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怕自己失业，交不起房租。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失业以后，他每天都在家看书。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈去年失业了，家里的钱少了很多。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想帮助失业的人找到新工作。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失业过一次，所以特别想保住现在的工作。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为生意不好，很多人担心会失业。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失业的那段时间，他很难过。", "target_word": "失业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "失业了", "label": "体标"}, {"form": "失业过", "label": "体标"}], "register": "中性", "sense_fingerprint": "有劳动能力的人失去工作、没有收入", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31610bca-58b2-44ff-ad3a-29a665b138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20067, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "失业", "is_correct": true, "explanation": "正确：失业（shī yè），指有劳动能力的人失去工作、没有收入。"}, {"text": "事业", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是事业。"}, {"text": "视野", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，yě（第三声）与 yè（第四声）声调也不同，意思是视野。"}, {"text": "诗意", "is_correct": false, "explanation": "shī 相同，yì（第四声）与 yè（第四声）韵母不同，意思是诗意。"}], "explanations": {"失业": "正确：失业（shī yè），指有劳动能力的人失去工作、没有收入。", "事业": "shì（第四声）与 shī（第一声）声调不同，意思是事业。", "视野": "shì（第四声）与 shī（第一声）声调不同，yě（第三声）与 yè（第四声）声调也不同，意思是视野。", "诗意": "shī 相同，yì（第四声）与 yè（第四声）韵母不同，意思是诗意。"}, "sentence_index": null, "correct_answer": "失业"}, "level_3": {"options": [{"text": "失业", "is_correct": true, "explanation": "正确：“失业”指失去工作，与“给失业的人”的语境一致。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指刚来到世上，不能指需要职业培训的人，与“职业培训”的语境矛盾。"}, {"text": "去世", "is_correct": false, "explanation": "语义：“去世”指人已经死亡，不能再接受职业培训。"}, {"text": "解决", "is_correct": false, "explanation": "配价：“解决”是及物动词，必须带宾语，“解决的人”结构不完整。"}], "explanations": {"失业": "正确：“失业”指失去工作，与“给失业的人”的语境一致。", "出生": "语义：“出生”指刚来到世上，不能指需要职业培训的人，与“职业培训”的语境矛盾。", "去世": "语义：“去世”指人已经死亡，不能再接受职业培训。", "解决": "配价：“解决”是及物动词，必须带宾语，“解决的人”结构不完整。"}, "sentence_index": 0, "correct_answer": "失业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我决定明年失业，去读研究生。", "explanation": "这里应该用〈辞职〉。失业是非自愿地失去工作；自己主动离开工作要用辞职。"}, {"text": "他年纪大了，今年失业，可以在家休息了。", "explanation": "这里应该用〈退休〉。到了年龄按规定离开工作要用退休，失业指没有工作、没有收入。"}, {"text": "为了抗议加班，工人们今天集体失业，坐在厂门口不肯进去。", "explanation": "这里应该用〈罢工〉。罢工是员工自愿停止工作以表达不满，员工仍有工作，不能说失业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20067, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "失业", "is_correct": true, "explanation": "正确：失业（shī yè），指有劳动能力的人失去工作、没有收入。"}, {"text": "实业", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是实业。"}, {"text": "书页", "is_correct": false, "explanation": "shū 与 shī 韵母不同（u 与 i），yè 相同，意思是书页。"}, {"text": "枝叶", "is_correct": false, "explanation": "zhī 与 shī 声母不同（zh 与 sh），yè 相同，意思是枝叶。"}], "explanations": {"失业": "正确：失业（shī yè），指有劳动能力的人失去工作、没有收入。", "实业": "shí（第二声）与 shī（第一声）声调不同，意思是实业。", "书页": "shū 与 shī 韵母不同（u 与 i），yè 相同，意思是书页。", "枝叶": "zhī 与 shī 声母不同（zh 与 sh），yè 相同，意思是枝叶。"}, "sentence_index": null, "correct_answer": "失业"}, "level_3": {"options": [{"text": "失业", "is_correct": true, "explanation": "正确：“失业”指失去工作，与“帮助……找到新工作”的语境一致。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉的人不会去找工作，与“找到新工作”矛盾。"}, {"text": "出差", "is_correct": false, "explanation": "语义：出差的人已经有工作、正在外出办事，与“找到新工作”矛盾。"}, {"text": "拥有", "is_correct": false, "explanation": "配价：“拥有”是及物动词，必须带宾语，“拥有的人”结构不完整。"}], "explanations": {"失业": "正确：“失业”指失去工作，与“帮助……找到新工作”的语境一致。", "睡觉": "语义：睡觉的人不会去找工作，与“找到新工作”矛盾。", "出差": "语义：出差的人已经有工作、正在外出办事，与“找到新工作”矛盾。", "拥有": "配价：“拥有”是及物动词，必须带宾语，“拥有的人”结构不完整。"}, "sentence_index": 6, "correct_answer": "失业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家小店上个月失业了，老板很着急。", "explanation": "这里说的是小店停止经营，失业只指人没有工作，不能用来描述店铺。"}, {"text": "这门手艺已经失业了，现在没有人学。", "explanation": "这里说的是手艺不再有人传承、逐渐消失，失业只指人没有工作，不能用来描述手艺。"}, {"text": "那台电脑昨天失业了，所以不能用。", "explanation": "这里说的是电脑坏了、无法使用，失业只指人没有工作，不能用来描述电脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20067, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表哥去年失业着，现在正在学做饭。", "corrected_sentence": "我表哥去年失业了，现在正在学做饭。", "error_description": "体标错误：“去年”指已经完成的事件，应用“了”表示完成；“着”表示持续状态，与“去年”不搭。应写作“去年失业了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20067, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟上个月很失业了，到现在还没有找到工作。", "corrected_sentence": "我弟弟上个月失业了，到现在还没有找到工作。", "error_description": "副词误用：“失业”是表示动作的动词，不能受程度副词“很”修饰。应去掉“很”，写作“上个月失业了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20068, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "更少", "is_correct": true, "explanation": "更少：数量比原来或别处少，与“更多”意义相反。"}, {"text": "快", "is_correct": false, "explanation": "快：形容速度，与“更多”没有反义关系。"}, {"text": "好", "is_correct": false, "explanation": "好：形容品质，与“更多”没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "高：形容高度，与“更多”没有反义关系。"}], "correct_answer": "更少", "explanations": {"更少": "更少：数量比原来或别处少，与“更多”意义相反。", "快": "快：形容速度，与“更多”没有反义关系。", "好": "好：形容品质，与“更多”没有反义关系。", "高": "高：形容高度，与“更多”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20068, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "更少", "is_correct": true, "explanation": "更少：数量比原来或别处少，与“更多”意义相反。"}, {"text": "远", "is_correct": false, "explanation": "远：形容距离，与“更多”没有反义关系。"}, {"text": "贵", "is_correct": false, "explanation": "贵：形容价格，与“更多”没有反义关系。"}, {"text": "新", "is_correct": false, "explanation": "新：形容时间或状态，与“更多”没有反义关系。"}], "correct_answer": "更少", "explanations": {"更少": "更少：数量比原来或别处少，与“更多”意义相反。", "远": "远：形容距离，与“更多”没有反义关系。", "贵": "贵：形容价格，与“更多”没有反义关系。", "新": "新：形容时间或状态，与“更多”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20068, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容数量或程度上的增加。", "primary_collocate": null, "pronunciation": "gèng duō", "ipa": "kɤŋ˥˩ tuɔ˥", "syllable_count": 2, "sentences": [{"text": "有些人认为，应该给失业的人提供更多的职业培训。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "同时，也有讨论认为，政府可能需要向使用人工智能的企业收更多的税，再用这些钱帮助受影响的工人。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们必须思考：在人工智能时代，如何让更多人受益？", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我想花更多的时间陪家人。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市需要更多的公园。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年来中国学习的学生更多了。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想要进步，就要做更多的练习。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末商场里的人比平时更多。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读了很多书，但是还想读更多。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我更多的水，我很渴。", "target_word": "更多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更多的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "数量或程度比原来或别处增加", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31610bca-58b2-44ff-ad3a-29a665b138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20068, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更多", "is_correct": true, "explanation": "正确：“更多”表示数量增加，与“提供……的职业培训”搭配。"}, {"text": "更胖", "is_correct": false, "explanation": "搭配：“胖”形容人或动物的身体，不能修饰“职业培训”。"}, {"text": "更甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能修饰“职业培训”。"}, {"text": "更白", "is_correct": false, "explanation": "搭配：“白”形容颜色，不能修饰“职业培训”。"}], "explanations": {"更多": "正确：“更多”表示数量增加，与“提供……的职业培训”搭配。", "更胖": "搭配：“胖”形容人或动物的身体，不能修饰“职业培训”。", "更甜": "搭配：“甜”形容味道，不能修饰“职业培训”。", "更白": "搭配：“白”形容颜色，不能修饰“职业培训”。"}, "sentence_index": 0, "correct_answer": "更多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想在北京待更多，不想那么快回家。", "explanation": "这里应该用〈更久〉。“更多”说的是数量，停留时间的长短要用“更久”。"}, {"text": "这条路的长度比那条更多。", "explanation": "这里应该用〈更长〉。“更多”说的是数量，路的长短要用“更长”。"}, {"text": "这个问题的难度比上次更多了。", "explanation": "这里应该用〈更大〉。难度是程度，不是数量，要用更大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更多", "is_correct": true, "explanation": "正确：“更多”表示数量增加，与“想要进步，就要做……的练习”的语境一致。"}, {"text": "更便宜", "is_correct": false, "explanation": "语义：“便宜”说价格，不能用来修饰练习，且与“想要进步”的语境不符。"}, {"text": "更旧", "is_correct": false, "explanation": "语义：“旧”说时间久远，与“想要进步”的语境矛盾。"}, {"text": "更冷", "is_correct": false, "explanation": "搭配：“冷”形容温度，不能修饰“练习”，与“进步”的语境不符。"}], "explanations": {"更多": "正确：“更多”表示数量增加，与“想要进步，就要做……的练习”的语境一致。", "更便宜": "语义：“便宜”说价格，不能用来修饰练习，且与“想要进步”的语境不符。", "更旧": "语义：“旧”说时间久远，与“想要进步”的语境矛盾。", "更冷": "搭配：“冷”形容温度，不能修饰“练习”，与“进步”的语境不符。"}, "sentence_index": 6, "correct_answer": "更多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的声音比我更多。", "explanation": "这里应该用〈更响〉。“更多”说的是数量，声音的大小要用“更响”。"}, {"text": "这件衣服的价格比那件更多。", "explanation": "这里应该用〈更贵〉。“更多”说的是数量，价格的高低要用“更贵”。"}, {"text": "他的个子比我更多。", "explanation": "这里应该用〈更高〉。“更多”说的是数量，个子的高矮要用“更高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个学校需要更多了老师。", "corrected_sentence": "这个学校需要更多的老师。", "error_description": "助词错误：“更多”修饰名词时要用结构助词“的”，写作“更多的老师”。“了”是动态助词，不能放在“更多”和名词之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议室里的人比昨天更多着。", "corrected_sentence": "会议室里的人比昨天更多了。", "error_description": "体貌错误：“更多”表示数量变化已经发生，应用体标“了”，写作“比昨天更多了”。“着”表示状态的持续，不能用于这种比较变化。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
