INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20069, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为帮助人们获得或提升工作所需技能而提供的系统学习和训练。", "primary_collocate": null, "pronunciation": "zhí yè péi xùn", "ipa": "ʈʂʅ˧˥ jɛ˥˩ pʰei̯˧˥ ɕyn˥˩", "syllable_count": 4, "sentences": [{"text": "有些人认为，应该给失业的人提供更多的职业培训。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他参加了一个免费的职业培训。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司给新员工提供职业培训。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的职业培训对找工作很有帮助。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她完成职业培训以后，找到了新工作。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想报名参加周末的职业培训。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "职业培训让很多失业的人有了新技能。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在职业培训中学会了修电脑。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府免费为农民工提供职业培训。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次职业培训一共有三十个人参加。", "target_word": "职业培训", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "职业培训班", "label": "复合词"}, {"form": "职业培训学校", "label": "复合词"}], "register": "中性", "sense_fingerprint": "为获得或提升工作技能而进行的系统学习和训练", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31610bca-58b2-44ff-ad3a-29a665b138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20069, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "职业培训", "is_correct": true, "explanation": "正确：“提供”的对象应是系统的学习和训练，符合句意。"}, {"text": "产假", "is_correct": false, "explanation": "语义：产假是为生育的女员工设立的假期，不是可以提供给失业者的帮助。"}, {"text": "婚礼", "is_correct": false, "explanation": "搭配：“提供婚礼”不成立，婚礼是一次活动，与失业者需要的帮助无关。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是个人病情的记录，与失业者的就业需要无关。"}], "explanations": {"职业培训": "正确：“提供”的对象应是系统的学习和训练，符合句意。", "产假": "语义：产假是为生育的女员工设立的假期，不是可以提供给失业者的帮助。", "婚礼": "搭配：“提供婚礼”不成立，婚礼是一次活动，与失业者需要的帮助无关。", "病历": "语义：病历是个人病情的记录，与失业者的就业需要无关。"}, "sentence_index": 0, "correct_answer": "职业培训"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他参加了一只职业培训。", "explanation": "这里应该用〈次〉或〈项〉。“只”用于动物或成对的东西，培训要用“次”或“项”。"}, {"text": "她的职业培训很清楚，三十岁前要当经理。", "explanation": "这里应该用〈规划〉。“清楚”说计划、想法，“职业培训”是学习活动，不能这样形容。"}, {"text": "他的职业培训很可爱。", "explanation": "这里应该用〈学员〉。“可爱”形容人，“职业培训”是活动，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20069, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职业培训", "is_correct": true, "explanation": "正确：句中主语应是能帮助失业者获得新技能的活动，职业培训符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能让人学会新技能，句意不通。"}, {"text": "养老金", "is_correct": false, "explanation": "语义：养老金是退休后领取的钱，与学习新技能无关。"}, {"text": "体温", "is_correct": false, "explanation": "配价：“让……有了新技能”的主语应是人或活动，体温不能作这类主语。"}], "explanations": {"职业培训": "正确：句中主语应是能帮助失业者获得新技能的活动，职业培训符合句意。", "天气": "语义：天气不能让人学会新技能，句意不通。", "养老金": "语义：养老金是退休后领取的钱，与学习新技能无关。", "体温": "配价：“让……有了新技能”的主语应是人或活动，体温不能作这类主语。"}, "sentence_index": 6, "correct_answer": "职业培训"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的电脑职业培训很强。", "explanation": "这里应该用〈技能〉。“强”形容能力或技术本身，“职业培训”是一项活动，不能说“强”。"}, {"text": "我每天早上去公园职业培训。", "explanation": "这里应该用〈锻炼〉。“职业培训”是名词，指学习工作技能，不是在公园活动身体。"}, {"text": "这家餐馆的职业培训很好吃。", "explanation": "这里应该用〈菜〉。“好吃”形容食物，“职业培训”是学习活动，不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府为失业者免费提供一座职业培训。", "corrected_sentence": "政府为失业者免费提供一次职业培训。", "error_description": "错误：“一座职业培训”，应为“一次职业培训”。“座”用于建筑、山等大型固定的东西，培训是一次活动，要用“次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20069, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂为新员工安排了一台职业培训。", "corrected_sentence": "这家工厂为新员工安排了一次职业培训。", "error_description": "错误：“一台职业培训”，应为“一次职业培训”。“台”用于机器，培训活动要用“次”或“项”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
