INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20072, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20072, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为客户提供解答和帮助的服务人员或岗位。", "primary_collocate": null, "pronunciation": "kè fú", "ipa": "kʰɤ˥˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "例如，一些公司的客服工作现在由电脑程序完成，不需要那么多人工客服了。", "target_word": "客服", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我在一家网店做客服。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客服告诉我，明天可以退货。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行的客服态度很好。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西有问题，可以找客服。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想应聘公司的客服工作。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客服小姐耐心地回答了我的问题。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上十点，客服还在上班。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当了三年客服，很会和人说话。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的客服回复得很快。", "target_word": "客服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人工客服", "label": "复合"}, {"form": "在线客服", "label": "复合"}], "register": "中性", "sense_fingerprint": "公司里为客户解答问题的服务人员或这类岗位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31610bca-58b2-44ff-ad3a-29a665b138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客服", "is_correct": true, "explanation": "这里指公司里的客服工作，与后文“人工客服”相呼应。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以由电脑程序完成的工作领域，句中指客户服务。"}, {"text": "消防", "is_correct": false, "explanation": "语义：消防工作不能由电脑程序取代，句意不通。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“早餐”一般不与“工作”组成职业领域的说法，句中要的是客服工作。"}], "explanations": {"客服": "这里指公司里的客服工作，与后文“人工客服”相呼应。", "天气": "语义：天气不是可以由电脑程序完成的工作领域，句中指客户服务。", "消防": "语义：消防工作不能由电脑程序取代，句意不通。", "早餐": "搭配：“早餐”一般不与“工作”组成职业领域的说法，句中要的是客服工作。"}, "sentence_index": 0, "correct_answer": "客服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "客服每天早上在田里种菜。", "explanation": "这里应该用〈农民〉。客服是为客户解答问题的岗位，在田里种菜的是农民。"}, {"text": "客服带我们参观古城。", "explanation": "这里应该用〈导游〉。客服是解答咨询的人员，不带团参观。"}, {"text": "客服做了一桌好菜。", "explanation": "这里应该用〈厨师〉。客服不做菜，做菜的是厨师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客服", "is_correct": true, "explanation": "这里指客服人员，与“小姐”构成称呼，并与“耐心地回答问题”相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能耐心地回答问题，与句中的人物不符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会回答问题，句中的主语应是一个人。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“窗户”不能与“小姐”组成称呼，句中要的是服务人员。"}], "explanations": {"客服": "这里指客服人员，与“小姐”构成称呼，并与“耐心地回答问题”相符。", "冰箱": "语义：冰箱不能耐心地回答问题，与句中的人物不符。", "石头": "语义：石头不会回答问题，句中的主语应是一个人。", "窗户": "搭配：“窗户”不能与“小姐”组成称呼，句中要的是服务人员。"}, "sentence_index": 6, "correct_answer": "客服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客服每天负责给病人打针。", "explanation": "这里应该用〈护士〉。客服负责解答客户的问题，给病人打针的是护士。"}, {"text": "客服开车送我们去机场。", "explanation": "这里应该用〈司机〉。客服负责解答问题，开车送人的是司机。"}, {"text": "客服在工地上搬砖。", "explanation": "这里应该用〈工人〉。客服是解答咨询的岗位，搬砖的是工人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐在银行当一棵客服。", "corrected_sentence": "我姐姐在银行当一名客服。", "error_description": "量词错误：“客服”指人，应用“名”或“位”计量，“棵”用于树木，不能计量人。正确说法是“一名客服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天对客服打了电话。", "corrected_sentence": "我昨天给客服打了电话。", "error_description": "介词错误：“打电话”的对象要用“给”引出，应说“给客服打了电话”，不能说“对客服打了电话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
