INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20073, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指已经发育成熟的人，通常指年满18岁的人。", "primary_collocate": null, "pronunciation": "chéng nián rén", "ipa": "ʈʂʰɤŋ˧˥ njɛn˧˥ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "他们投资教育项目，帮助成年人学习新技术。", "target_word": "成年人", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他今年十八岁，已经是成年人了。", "target_word": "成年人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "成年人要为自己的决定负责。", "target_word": "成年人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在我们国家，成年人可以投票。", "target_word": "成年人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影只让成年人看。", "target_word": "成年人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "成年人每天需要睡七八个小时。", "target_word": "成年人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八岁以后，他就是法律上的成年人。", "target_word": "成年人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买酒的时候，成年人要带身份证。", "target_word": "成年人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院有给成年人看病的医生。", "target_word": "成年人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成年人和孩子的身体不一样。", "target_word": "成年人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "未成年人", "label": "复合"}], "register": "中性", "sense_fingerprint": "年满十八岁、身心发育成熟的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35cea5a1-2658-4833-b0af-5dcd0e705238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20073, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "树", "is_correct": false, "explanation": "语义：树不能学习新技术，与“帮助…学习新技术”的对象不符。"}, {"text": "成年人", "is_correct": true, "explanation": "正确。“帮助”的对象是能学习新技术的人，成年人符合句意。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是物品，不能接受“帮助”去“学习新技术”。"}, {"text": "工具", "is_correct": false, "explanation": "搭配：“帮助…学习”要求能学习的对象，“工具”不能与“学习新技术”搭配。"}], "explanations": {"树": "语义：树不能学习新技术，与“帮助…学习新技术”的对象不符。", "成年人": "正确。“帮助”的对象是能学习新技术的人，成年人符合句意。", "课本": "语义：课本是物品，不能接受“帮助”去“学习新技术”。", "工具": "搭配：“帮助…学习”要求能学习的对象，“工具”不能与“学习新技术”搭配。"}, "sentence_index": 0, "correct_answer": "成年人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个刚满一岁的宝宝已经是成年人了。", "explanation": "这里不能用〈成年人〉。它指年满十八岁的人，一岁的宝宝应说〈婴儿〉。"}, {"text": "这棵树已经是成年人了。", "explanation": "这里不能用〈成年人〉。它只指已发育成熟的人，树应说〈长大〉。"}, {"text": "这个五岁的孩子是成年人。", "explanation": "这里不能用〈成年人〉。成年人指年满十八岁的人，与“五岁”矛盾，这里应指〈儿童〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20073, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老人", "is_correct": false, "explanation": "语义：十八岁以后的人不能称“老人”，与“十八岁以后”矛盾。"}, {"text": "成年人", "is_correct": true, "explanation": "正确。“法律上的”后接法律身份，成年人符合“十八岁以后”的句意。"}, {"text": "未成年人", "is_correct": false, "explanation": "语义：“十八岁以后”之后就不再是未成年人，与句意矛盾。"}, {"text": "儿童", "is_correct": false, "explanation": "语义：“儿童”在法律上指未满十八岁的人，与“十八岁以后”矛盾。"}], "explanations": {"老人": "语义：十八岁以后的人不能称“老人”，与“十八岁以后”矛盾。", "成年人": "正确。“法律上的”后接法律身份，成年人符合“十八岁以后”的句意。", "未成年人": "语义：“十八岁以后”之后就不再是未成年人，与句意矛盾。", "儿童": "语义：“儿童”在法律上指未满十八岁的人，与“十八岁以后”矛盾。"}, "sentence_index": 6, "correct_answer": "成年人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的成年人都是小学生。", "explanation": "这里不能用〈成年人〉。成年人指年满十八岁的人，小学生还未成年，这里应指〈未成年人〉。"}, {"text": "这只小狗已经是成年人了。", "explanation": "这里不能用〈成年人〉。它只指人，小狗应说〈长大〉。"}, {"text": "这盆花两年后就成为成年人。", "explanation": "这里不能用〈成年人〉。它只指人，植物应说〈长成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家里有一只成年人，负责做饭。", "corrected_sentence": "他家里有一个成年人，负责做饭。", "error_description": "量词错误：“成年人”指人，量词应用“个”（或“位”），不能用“只”（“只”多用于动物）。正确形式是“一个成年人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店有三成年人。", "corrected_sentence": "这家店有三个成年人。", "error_description": "量词缺失：数词“三”与“成年人”之间漏掉量词，应说“三个成年人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
