INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20074, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "编写计算机程序代码。", "primary_collocate": null, "pronunciation": "biān chéng", "ipa": "pjɛn˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "比如，有人去学怎么使用人工智能工具，有人去学编程或数据分析。", "target_word": "编程", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我哥哥在公司每天编程。", "target_word": "编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从十岁起就喜欢编程。", "target_word": "编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "编程需要有耐心，也需要细心。", "target_word": "编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学编程，将来做软件工程师。", "target_word": "编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上他坐在电脑前编程，一直到十二点。", "target_word": "编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多小学生也开始学编程了。", "target_word": "编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编程的时候，他不喜欢别人说话。", "target_word": "编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不会编程，但她会用电脑。", "target_word": "编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天花四个小时编程。", "target_word": "编程", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "编了一天程", "label": "体标"}, {"form": "编程语言", "label": "复合"}, {"form": "編程", "label": "繁体"}], "register": "中性", "sense_fingerprint": "编写计算机程序代码", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35cea5a1-2658-4833-b0af-5dcd0e705238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "搭配：“学”的对象应是可以学会的技能，“睡觉”是本能，不能作为要学的内容。"}, {"text": "编程", "is_correct": true, "explanation": "正确。“编程”与“数据分析”同属计算机相关技能，与前文“人工智能工具”一致。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以学习的知识或技能，与“学”的对象不符。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，不是可以学习的技能，不能作“学”的对象。"}], "explanations": {"睡觉": "搭配：“学”的对象应是可以学会的技能，“睡觉”是本能，不能作为要学的内容。", "编程": "正确。“编程”与“数据分析”同属计算机相关技能，与前文“人工智能工具”一致。", "空气": "语义：空气不是可以学习的知识或技能，与“学”的对象不符。", "下雨": "语义：下雨是天气现象，不是可以学习的技能，不能作“学”的对象。"}, "sentence_index": 0, "correct_answer": "编程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌是他编程的。", "explanation": "这里应该用〈作曲〉。“编程”指编写计算机代码，谱写歌曲要用“作曲”。"}, {"text": "他负责编程这篇稿子。", "explanation": "这里应该用〈编辑〉。编辑指修改、整理稿件，“编程”指编写计算机代码，不能用于稿件。"}, {"text": "这首诗是他编程的。", "explanation": "这里应该用〈写〉。“编程”指编写代码，写诗不能用它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汽油", "is_correct": false, "explanation": "搭配：“学”的对象应是可以学会的技能或知识，“汽油”不是可以学的内容。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“学”的对象应是可以学会的技能或知识，“石头”不是可以学的内容。"}, {"text": "编程", "is_correct": true, "explanation": "正确。“学编程”是小学生可以学习的内容，与句意相符。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“出差”是工作活动，不能作为“学”的内容。"}], "explanations": {"汽油": "搭配：“学”的对象应是可以学会的技能或知识，“汽油”不是可以学的内容。", "石头": "搭配：“学”的对象应是可以学会的技能或知识，“石头”不是可以学的内容。", "编程": "正确。“学编程”是小学生可以学习的内容，与句意相符。", "出差": "搭配：“出差”是工作活动，不能作为“学”的内容。"}, "sentence_index": 6, "correct_answer": "编程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天编程院子里的花。", "explanation": "这里应该用〈照顾〉。〈编程〉指编写计算机代码，照顾花草不能用它。"}, {"text": "这座桥是他编程的。", "explanation": "这里应该用〈建造〉。桥是建造出来的，“编程”指编写代码，不能用于此。"}, {"text": "这本书是他编程的。", "explanation": "这里应该用〈编写〉。“编程”指编写计算机代码，编写书籍应说〈编写〉或〈编著〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在编程了，没听见电话。", "corrected_sentence": "他正在编程，没听见电话。", "error_description": "体标错误：“正在编程”表示动作正在进行，不能再加表示完成或变化的“了”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他编程编很快。", "corrected_sentence": "他编程编得很快。", "error_description": "补语错误：动词后接表示程度的补语时要用“得”，“他编程编很快”漏掉“得”，应说“他编程编得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
