INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20075, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对收集到的数字信息进行整理和计算，从中找出有用的结果或规律。", "primary_collocate": null, "pronunciation": "shù jù fēn xī", "ipa": "ʂu˥˩ tɕy˥˩ fən˥ ɕi˥", "syllable_count": 4, "sentences": [{"text": "比如，有人去学怎么使用人工智能工具，有人去学编程或数据分析。", "target_word": "数据分析", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "数据分析可以帮公司找到问题。", "target_word": "数据分析", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在公司做数据分析，每天看很多数字。", "target_word": "数据分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做数据分析时，要先把数据整理好。", "target_word": "数据分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据分析的结果显示，今年卖得更好。", "target_word": "数据分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好数据分析，找工作会更容易。", "target_word": "数据分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能帮你做数据分析。", "target_word": "数据分析", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用数据分析发现了客人的购物习惯。", "target_word": "数据分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据分析需要耐心，也需要懂数学。", "target_word": "数据分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请了一位专家来讲数据分析。", "target_word": "数据分析", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "数据分析师", "label": "复合"}, {"form": "數據分析", "label": "繁体"}], "register": "中性", "sense_fingerprint": "整理、计算数字信息，找出有用结果或规律", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35cea5a1-2658-4833-b0af-5dcd0e705238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20075, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数据分析", "is_correct": true, "explanation": "数据分析：对数字信息整理计算、找规律，与“学编程或数据分析”的语境相符。"}, {"text": "手机", "is_correct": false, "explanation": "配价：“学”的宾语应是知识或技能，“手机”是物品，不能说“学手机”。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是可以学习的知识或技能，与“学”的对象不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以学习的知识或技能，句子读起来不通。"}], "explanations": {"数据分析": "数据分析：对数字信息整理计算、找规律，与“学编程或数据分析”的语境相符。", "手机": "配价：“学”的宾语应是知识或技能，“手机”是物品，不能说“学手机”。", "花园": "语义：花园不是可以学习的知识或技能，与“学”的对象不符。", "空气": "语义：空气不是可以学习的知识或技能，句子读起来不通。"}, "sentence_index": 0, "correct_answer": "数据分析"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用数据分析把三百张表格输进了电脑。", "explanation": "这里应该用〈数据录入〉。把表格输进电脑是数据录入，数据分析是从数字中找出规律。"}, {"text": "他负责保护公司的数据，每天做数据分析，防止别人偷走。", "explanation": "这里应该用〈数据加密〉。防止数据被偷走要用数据加密，数据分析是找规律，不能起保护作用。"}, {"text": "他用数据分析把电脑里的文件复制到另一块硬盘上。", "explanation": "这里应该用〈数据备份〉。复制文件到另一块硬盘是数据备份，数据分析是找规律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20075, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数据分析", "is_correct": true, "explanation": "数据分析：对数字信息的整理和计算，与“这个软件能帮你做数据分析”相符。"}, {"text": "梦", "is_correct": false, "explanation": "语义：软件不能帮人做梦，与“软件能帮你”的语境不符。"}, {"text": "错误", "is_correct": false, "explanation": "搭配：“做”不与“错误”搭配，应说“犯错误”。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“做”不与“眼泪”搭配，句子读起来不通。"}], "explanations": {"数据分析": "数据分析：对数字信息的整理和计算，与“这个软件能帮你做数据分析”相符。", "梦": "语义：软件不能帮人做梦，与“软件能帮你”的语境不符。", "错误": "搭配：“做”不与“错误”搭配，应说“犯错误”。", "眼泪": "搭配：“做”不与“眼泪”搭配，句子读起来不通。"}, "sentence_index": 6, "correct_answer": "数据分析"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用数据分析炒了一盘菜。", "explanation": "这里不能用〈数据分析〉。它指对数字的整理与计算，不能用来炒菜。"}, {"text": "他每天在院子里用数据分析浇花。", "explanation": "这里不能用〈数据分析〉。它指对数字的整理与计算，不能用来浇花。"}, {"text": "这位医生用数据分析给病人打针。", "explanation": "这里不能用〈数据分析〉。它指对数字的整理与计算，打针应使用针具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20075, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告的数据分析做很仔细。", "corrected_sentence": "这份报告的数据分析做得很仔细。", "error_description": "错误在于“做很仔细”缺少补语标记“得”。正确说法是“做得很仔细”，“得”连接动词和补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20075, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前没做了数据分析。", "corrected_sentence": "我以前没做过数据分析。", "error_description": "体标错误：“没”与“了”不搭配，否定经历要用“没……过”，“没做了”不能说，应为“没做过数据分析”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
