INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20078, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指在工厂、企业等单位中从事体力或技术劳动、以工资收入为主要生活来源的人。", "primary_collocate": null, "pronunciation": "gōng rén", "ipa": "kʊŋ˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "同时，也有讨论认为，政府可能需要向使用人工智能的企业收更多的税，再用这些钱帮助受影响的工人。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "工人们每天早上七点上班。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂有三百多个工人。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在工地上修新路。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸是工厂的工人。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人拿到工资，很高兴。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们戴着帽子干活。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给工人买了新衣服。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老工人已经工作了三十年。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们昨天加了一个晚上的班。", "target_word": "工人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工人们", "label": "复数"}, {"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "在工厂企业靠劳动拿工资的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35cea5a1-2658-4833-b0af-5dcd0e705238') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20078, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "工人", "is_correct": true, "explanation": "正确。指在工厂、企业里从事劳动、以工资为主要收入的人。"}, {"text": "公认", "is_correct": false, "explanation": "rèn（第四声）与 rén（第二声）声调不同，意思是大家都承认，与“工人”不同。"}, {"text": "公然", "is_correct": false, "explanation": "rán 与 rén 的韵母不同（a 与 e），意思是公开地、毫不掩饰地。"}, {"text": "公文", "is_correct": false, "explanation": "wén 与 rén 的声母不同（w 与 r），意思是公文、正式文件。"}], "explanations": {"工人": "正确。指在工厂、企业里从事劳动、以工资为主要收入的人。", "公认": "rèn（第四声）与 rén（第二声）声调不同，意思是大家都承认，与“工人”不同。", "公然": "rán 与 rén 的韵母不同（a 与 e），意思是公开地、毫不掩饰地。", "公文": "wén 与 rén 的声母不同（w 与 r），意思是公文、正式文件。"}, "sentence_index": null, "correct_answer": "工人"}, "level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不需要政府帮助，句中“受影响的”后面应是需要帮助的人。"}, {"text": "工人", "is_correct": true, "explanation": "正确。句中说的是受人工智能影响、需要政府帮助的劳动者，只有“工人”符合。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“帮助”的对象是人，不能说帮助考试。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不是需要政府帮助的对象，句意不通。"}], "explanations": {"石头": "语义：石头不需要政府帮助，句中“受影响的”后面应是需要帮助的人。", "工人": "正确。句中说的是受人工智能影响、需要政府帮助的劳动者，只有“工人”符合。", "考试": "搭配：“帮助”的对象是人，不能说帮助考试。", "雨伞": "语义：雨伞不是需要政府帮助的对象，句意不通。"}, "sentence_index": 0, "correct_answer": "工人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爸爸是一名工人，每天在大学里教数学。", "explanation": "这里应该用〈教师〉。在大学教数学的是教师，“工人”指在工厂、企业里做体力或技术劳动的人，不用于教书。"}, {"text": "我爸爸是一名工人，在医院里给病人看病。", "explanation": "这里应该用〈医生〉。给病人看病的是医生，“工人”指在工厂、企业里做体力或技术劳动的人。"}, {"text": "我爸爸是一名工人，每天在路口指挥交通。", "explanation": "这里应该用〈交警〉。在路口指挥交通的是交警，“工人”指在工厂、企业里做体力或技术劳动的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语法：“工资”是抽象名词，不能与“们”连用，也不能戴着帽子干活。"}, {"text": "工人", "is_correct": true, "explanation": "正确。句中的人戴着帽子干活，指从事体力劳动的工人。"}, {"text": "道理", "is_correct": false, "explanation": "语义：“道理”是抽象概念，不能戴着帽子干活。"}, {"text": "年代", "is_correct": false, "explanation": "语义：“年代”是时间概念，不能戴着帽子干活。"}], "explanations": {"工资": "语法：“工资”是抽象名词，不能与“们”连用，也不能戴着帽子干活。", "工人": "正确。句中的人戴着帽子干活，指从事体力劳动的工人。", "道理": "语义：“道理”是抽象概念，不能戴着帽子干活。", "年代": "语义：“年代”是时间概念，不能戴着帽子干活。"}, "sentence_index": 6, "correct_answer": "工人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人每天在办公室里处理文件。", "explanation": "这里应该用〈职员〉。坐在办公室处理文件的人要说职员，“工人”指从事体力或技术劳动的人。"}, {"text": "工人每天在法庭上为人辩护。", "explanation": "这里应该用〈律师〉。在法庭上为人辩护的是律师，“工人”指在工厂、企业里做体力或技术劳动的人。"}, {"text": "工人在医院里给病人打针。", "explanation": "这里应该用〈护士〉。给病人打针的是护士，“工人”指在工厂、企业里做体力或技术劳动的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我舅舅是一只工人。", "corrected_sentence": "我舅舅是一名工人。", "error_description": "量词错误：“工人”前应用“名”或“个”，“只”用于动物，不能用来数人。正确说法是“一名工人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我哥哥当过一只工人。", "corrected_sentence": "我哥哥当过一名工人。", "error_description": "量词错误：“工人”指人，前面应用“名”或“个”，“只”用于动物等，不能用来数人。正确说法是“当过一名工人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af4e2e5b-5f6c-4077-96ea-7d4a6731d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20079, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缓慢", "is_correct": true, "explanation": "正确。「缓慢」指速度低、用时长，与「快速」（速度高、时间短）相对。"}, {"text": "安静", "is_correct": false, "explanation": "「安静」的反义词是「吵闹」，与速度无关，不是「快速」的反义词。"}, {"text": "宽阔", "is_correct": false, "explanation": "「宽阔」形容空间或面积大，与速度无关，不构成反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "「清晰」形容看或听得分明，与速度无关，不构成反义关系。"}], "correct_answer": "缓慢", "explanations": {"缓慢": "正确。「缓慢」指速度低、用时长，与「快速」（速度高、时间短）相对。", "安静": "「安静」的反义词是「吵闹」，与速度无关，不是「快速」的反义词。", "宽阔": "「宽阔」形容空间或面积大，与速度无关，不构成反义关系。", "清晰": "「清晰」形容看或听得分明，与速度无关，不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20079, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缓慢", "is_correct": true, "explanation": "正确。「缓慢」指速度低、用时长，与「快速」相对。"}, {"text": "温柔", "is_correct": false, "explanation": "「温柔」形容性情或态度柔和，与速度无关，不是「快速」的反义词。"}, {"text": "高大", "is_correct": false, "explanation": "「高大」形容身材或事物的体积，与速度无关，不构成反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "「明亮」形容光线充足或颜色鲜明，与速度无关，不构成反义关系。"}], "correct_answer": "缓慢", "explanations": {"缓慢": "正确。「缓慢」指速度低、用时长，与「快速」相对。", "温柔": "「温柔」形容性情或态度柔和，与速度无关，不是「快速」的反义词。", "高大": "「高大」形容身材或事物的体积，与速度无关，不构成反义关系。", "明亮": "「明亮」形容光线充足或颜色鲜明，与速度无关，不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20079, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容速度很高，在短时间内完成或移动。", "primary_collocate": null, "pronunciation": "kuài sù", "ipa": "kʰwaɪ˥˩ su˥˩", "syllable_count": 2, "sentences": [{"text": "不是每个人都能快速学会新技能。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "他快速地跑到终点，只用了十秒。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的经济正在快速发展。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到孩子掉进水里，他快速跳了下去。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在比赛中，快速的反应非常重要。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请快速填好这张表，后面还有很多人在排队。", "target_word": "快速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他快速吃完早饭，就跑去赶公共汽车。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络让信息可以快速传到世界各地。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生快速检查了病人，然后马上准备手术。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她做事动作快速，十分钟就收拾好了房间。", "target_word": "快速", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "快速地", "label": "状语形式"}, {"form": "快速的", "label": "定语形式"}, {"form": "快速列车", "label": "复合"}], "register": "中性", "sense_fingerprint": "快速：形容速度很高，在短时间内完成或移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df62efa0-2dbe-46fc-9d7d-40fafa899bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20079, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明显", "is_correct": false, "explanation": "语义：「明显」指显而易见，不描述学习的方式，放在这里句意不通。"}, {"text": "快速", "is_correct": true, "explanation": "正确。「快速」作状语修饰「学会」，说明学得快，符合「不是每个人都能快速学会」的语境。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：「吵闹」形容声音或环境嘈杂，不能用来形容学习的方式。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：「大声」多修饰说、喊等发声动作，不修饰「学会」。"}], "explanations": {"明显": "语义：「明显」指显而易见，不描述学习的方式，放在这里句意不通。", "快速": "正确。「快速」作状语修饰「学会」，说明学得快，符合「不是每个人都能快速学会」的语境。", "吵闹": "语义：「吵闹」形容声音或环境嘈杂，不能用来形容学习的方式。", "大声": "搭配：「大声」多修饰说、喊等发声动作，不修饰「学会」。"}, "sentence_index": 0, "correct_answer": "快速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块布很快速，穿在身上特别舒服。", "explanation": "这里应该用〈柔软〉。「快速」只说速度，不能用来形容布料的质地。"}, {"text": "期末考试快速到了，我还没复习。", "explanation": "这里应该用〈快要〉。「快要到了」表示即将发生，「快速到了」说的是速度，句意变成考试已经很快来了。"}, {"text": "这把刀很快速，切菜特别方便。", "explanation": "这里应该用〈快〉。「快」形容刀刃锋利时指的是刀的性能，与速度无关；「快速」只表示速度，不能用来形容刀的锋利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20079, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "慢", "is_correct": false, "explanation": "语义：「慢」与后文「跑去赶公共汽车」的急促相矛盾，句意不通。"}, {"text": "快速", "is_correct": true, "explanation": "正确。「快速」作状语修饰「吃完」，说明早饭吃得快，与后文赶车呼应。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：「懒散」形容做事松懈，与「跑去赶公共汽车」的急切相矛盾。"}, {"text": "笔直", "is_correct": false, "explanation": "搭配：「笔直」多形容线条或站姿，不修饰「吃完」这样的动作。"}], "explanations": {"慢": "语义：「慢」与后文「跑去赶公共汽车」的急促相矛盾，句意不通。", "快速": "正确。「快速」作状语修饰「吃完」，说明早饭吃得快，与后文赶车呼应。", "懒散": "语义：「懒散」形容做事松懈，与「跑去赶公共汽车」的急切相矛盾。", "笔直": "搭配：「笔直」多形容线条或站姿，不修饰「吃完」这样的动作。"}, "sentence_index": 6, "correct_answer": "快速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的身材很快速，穿什么衣服都好看。", "explanation": "这里应该用〈苗条〉或〈匀称〉。「快速」只说动作或变化的速度，不能用来描述身材的样子。"}, {"text": "他的脾气很快速，一点小事就会生气。", "explanation": "这里应该用〈急〉。「脾气急」指性子急、容易生气；「快速」只形容动作或变化的速度，不能用来说脾气。"}, {"text": "这座山很快速，我一看就喜欢。", "explanation": "这里应该用〈雄伟〉或〈秀丽〉。「快速」只说速度，不能用来形容山的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她快速的完成了作业，十分钟就交上去了。", "corrected_sentence": "她快速地完成了作业，十分钟就交上去了。", "error_description": "错误在「快速」与动词之间：作状语修饰动词「完成」时应用「地」，写成「的」是结构助词误用，应说「快速地完成」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他快速的跑到了终点，只用了十秒。", "corrected_sentence": "他快速地跑到了终点，只用了十秒。", "error_description": "错误在「快速」与动词之间：作状语修饰动词「跑」时应用「地」，写成「的」是结构助词误用，应说「快速地跑到」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
