INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20080, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在生活、学习或工作中遇到的麻烦、阻碍或不容易解决的问题。", "primary_collocate": null, "pronunciation": "kùn nan", "ipa": "kʰwən˥˩ nan", "syllable_count": 2, "sentences": [{"text": "有些人年纪大了，学习上会遇到更多困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在生活中遇到了很多困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有困难的时候，可以给我打电话。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一起努力，终于克服了这个困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚到国外的时候，语言是最大的困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师常常帮助学生解决学习上的困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司现在遇到了资金方面的困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要怕困难，只要不放弃，总会有办法。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家里有困难，所以没有去旅行。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对困难，我们不能只是等别人来帮忙。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词（一个困难）"}, {"form": "困难户", "label": "复合"}, {"form": "困難", "label": "繁体"}], "register": "中性", "sense_fingerprint": "困难：生活、学习、工作中遇到的麻烦与阻碍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df62efa0-2dbe-46fc-9d7d-40fafa899bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20080, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "容易", "is_correct": false, "explanation": "词性：「容易」是形容词，不能作「遇到更多」的宾语，句子不通。"}, {"text": "困难", "is_correct": true, "explanation": "正确。「遇到更多困难」指学习时会碰到更多阻碍，与「年纪大了」的语境一致。"}, {"text": "机会", "is_correct": false, "explanation": "语义：「机会」是有利的时机，与「年纪大了、学习更费力」的语境相反。"}, {"text": "好处", "is_correct": false, "explanation": "语义：「好处」指有利的方面，与「遇到更多」的困境语境不符，句意不通。"}], "explanations": {"容易": "词性：「容易」是形容词，不能作「遇到更多」的宾语，句子不通。", "困难": "正确。「遇到更多困难」指学习时会碰到更多阻碍，与「年纪大了」的语境一致。", "机会": "语义：「机会」是有利的时机，与「年纪大了、学习更费力」的语境相反。", "好处": "语义：「好处」指有利的方面，与「遇到更多」的困境语境不符，句意不通。"}, "sentence_index": 0, "correct_answer": "困难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总是找我的困难，真让人烦。", "explanation": "这里应该用〈毛病〉。「找毛病」指挑别人的缺点，「困难」不能这样用。"}, {"text": "这台电脑有困难，经常死机。", "explanation": "这里应该用〈故障〉。「困难」指人遇到的麻烦或阻碍，机器出问题应说「有故障」，不能说机器有困难。"}, {"text": "这道数学题的困难很高，我做不出来。", "explanation": "这里应该用〈难度〉。「难度」指事情难的程度，可以说高低；「困难」指遇到的麻烦或阻碍，不说「困难很高」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好处", "is_correct": false, "explanation": "语义：「好处」指有利的方面，与「遇到」的负面处境相反，句意不通。"}, {"text": "困难", "is_correct": true, "explanation": "正确。「遇到……的困难」指资金上遇到的不容易之处，与句意一致。"}, {"text": "成功", "is_correct": false, "explanation": "搭配：「成功」一般说「取得成功」，不说「遇到……的成功」。"}, {"text": "成就", "is_correct": false, "explanation": "语义：「成就」指取得的成绩，与「遇到」的情境不符。"}], "explanations": {"好处": "语义：「好处」指有利的方面，与「遇到」的负面处境相反，句意不通。", "困难": "正确。「遇到……的困难」指资金上遇到的不容易之处，与句意一致。", "成功": "搭配：「成功」一般说「取得成功」，不说「遇到……的成功」。", "成就": "语义：「成就」指取得的成绩，与「遇到」的情境不符。"}, "sentence_index": 6, "correct_answer": "困难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他又惹了一大堆困难，大家都很头疼。", "explanation": "这里应该用〈麻烦〉。「惹麻烦」是常用说法，「惹困难」不通顺。"}, {"text": "他在考试中犯了一个困难。", "explanation": "这里应该用〈错误〉。「犯错误」是固定搭配，「犯困难」不通。"}, {"text": "这次他吃了不少困难。", "explanation": "这里应该用〈苦头〉。「吃苦头」是固定说法，「吃困难」不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他遇到了一只困难，但很快就解决了。", "corrected_sentence": "他遇到了一个困难，但很快就解决了。", "error_description": "量词错误：「困难」应搭配「个」，「只」多用于动物，不能用于困难。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司今年遇到了一条很大的困难，但大家没有放弃。", "corrected_sentence": "公司今年遇到了一个很大的困难，但大家没有放弃。", "error_description": "量词错误：「困难」应搭配量词「个」，「条」多用于长条形的东西，不能用于困难。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
