INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20081, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把家搬到别处去居住。", "primary_collocate": null, "pronunciation": "bān jiā", "ipa": "pan˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "而且，新工作可能在别的城市，搬家也不容易。", "target_word": "搬家", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们下个月要搬家，现在正在收拾东西。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友今天搬家，我去帮他拿箱子。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为工作太远，他们决定搬家。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家以后，我离学校近多了。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们一家刚搬家，邻居还不认识。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子要上新学校，所以我们打算搬家。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家的时候，他的旧书差点丢了。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套房子太小了，我想搬家。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家前，妈妈把不用的衣服都送人了。", "target_word": "搬家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搬了家", "label": "体标：了"}, {"form": "搬过家", "label": "体标：过"}, {"form": "搬个家", "label": "离合：插入量词"}], "register": "中性", "sense_fingerprint": "搬家：把家搬到别处去居住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df62efa0-2dbe-46fc-9d7d-40fafa899bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20081, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搬家", "is_correct": true, "explanation": "正确：“搬家”指整个家迁到别的城市居住，与“新工作在别的城市”相呼应。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”与句中的“新工作”矛盾，句意不通。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”意味着不再工作，与“新工作”矛盾，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：「游泳」与「新工作在别的城市」毫无关系，句意不通。"}], "explanations": {"搬家": "正确：“搬家”指整个家迁到别的城市居住，与“新工作在别的城市”相呼应。", "失业": "语义：“失业”与句中的“新工作”矛盾，句意不通。", "退休": "语义：“退休”意味着不再工作，与“新工作”矛盾，句意不通。", "游泳": "语义：「游泳」与「新工作在别的城市」毫无关系，句意不通。"}, "sentence_index": 0, "correct_answer": "搬家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上搬家去公司上班。", "explanation": "这里应该用〈通勤〉。搬家指长期迁居住所，每天往返公司上班不叫搬家。"}, {"text": "我们春节搬家回老家过节。", "explanation": "这里应该用〈回老家〉。搬家指长期迁居，春节回老家探亲不叫搬家。"}, {"text": "他从书房搬家到了卧室。", "explanation": "这里不能用“搬家”。搬家指全家迁入另一处住所，同一套房子里换房间不说搬家，要说“搬到卧室”之类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20081, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搬家", "is_correct": true, "explanation": "正确：“搬家”指全家迁居，与“新学校”和“打算”相呼应。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”指去学校读书，“我们”（家长）打算上学，句意不通。"}, {"text": "离婚", "is_correct": false, "explanation": "语义：“离婚”与“孩子要上新学校”的安排无关，句意不通。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：“搬运”需要带搬运的对象，单用“我们打算搬运”不完整。"}], "explanations": {"搬家": "正确：“搬家”指全家迁居，与“新学校”和“打算”相呼应。", "上学": "语义：“上学”指去学校读书，“我们”（家长）打算上学，句意不通。", "离婚": "语义：“离婚”与“孩子要上新学校”的安排无关，句意不通。", "搬运": "配价：“搬运”需要带搬运的对象，单用“我们打算搬运”不完整。"}, "sentence_index": 6, "correct_answer": "搬家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批货物今天搬家了。", "explanation": "这里应该用〈搬运〉。搬家的主语必须是人或家庭，货物不能搬家，要说“搬运”。"}, {"text": "他从这所学校搬家到另一所学校。", "explanation": "这里应该用〈转学〉。学生换学校要用转学，搬家只指家庭住所的迁移。"}, {"text": "病人昨天搬家到了市中心医院。", "explanation": "这里应该用〈转院〉。搬家只指家庭住所的迁移，病人换医院要用转院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20081, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们下个月搬家北京。", "corrected_sentence": "我们下个月搬家到北京。", "error_description": "“搬家”后面接表示去向的地点时，要用介词“到”或“去”引出；这里漏了“到”，应说“搬家到北京”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把搬家以后，还没买新沙发。", "corrected_sentence": "我们搬家以后，还没买新沙发。", "error_description": "“搬家”是不及物的离合词，前面不能加“把”。“把”字句要求“把+宾语+动词”，这里的结构不成立，应去掉“把”，说“搬家以后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20083, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20083, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20083, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指社会中不同人群在财富、收入、生活水平等方面的差异。", "primary_collocate": null, "pronunciation": "pín fù chā jù", "ipa": "pʰin˧˥ fu˥˩ ʈʂʰa˥ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "专家提醒，社会必须提前准备，否则贫富差距可能会变得更大。", "target_word": "贫富差距", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这个国家的贫富差距越来越大。", "target_word": "贫富差距", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府想办法减少贫富差距。", "target_word": "贫富差距", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "城市和农村之间有很大的贫富差距。", "target_word": "贫富差距", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "贫富差距太大，社会就不容易安定。", "target_word": "贫富差距", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸上常常谈到贫富差距的问题。", "target_word": "贫富差距", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们写一篇关于贫富差距的文章。", "target_word": "贫富差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人担心贫富差距会影响孩子的教育。", "target_word": "贫富差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，这里的贫富差距变小了。", "target_word": "贫富差距", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要缩小贫富差距，需要更多好工作。", "target_word": "贫富差距", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "社会不同人群在财富、收入、生活水平上的差异", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df62efa0-2dbe-46fc-9d7d-40fafa899bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20083, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贫富差距", "is_correct": true, "explanation": "正确：“贫富差距”指社会上不同人群在财富上的差别，与句中“社会”的范围相符。"}, {"text": "个人爱好", "is_correct": false, "explanation": "语义：“个人爱好”属于个人层面，与句中强调的社会问题不相干，也不会“变得更大”。"}, {"text": "天气状况", "is_correct": false, "explanation": "搭配：“状况”一般说变好或变坏，不能说“变得更大”。"}, {"text": "交通工具", "is_correct": false, "explanation": "语义：“交通工具”是具体的东西，不能作为“变得更大”的对象，句子不通。"}], "explanations": {"贫富差距": "正确：“贫富差距”指社会上不同人群在财富上的差别，与句中“社会”的范围相符。", "个人爱好": "语义：“个人爱好”属于个人层面，与句中强调的社会问题不相干，也不会“变得更大”。", "天气状况": "搭配：“状况”一般说变好或变坏，不能说“变得更大”。", "交通工具": "语义：“交通工具”是具体的东西，不能作为“变得更大”的对象，句子不通。"}, "sentence_index": 0, "correct_answer": "贫富差距"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哥哥和我的贫富差距是五岁。", "explanation": "这里应该用〈年龄差距〉。贫富差距指财富、收入上的差别，不能用来表示年龄相差多少。"}, {"text": "这两块地的贫富差距很大。", "explanation": "这里应该用〈面积差距〉。贫富差距指人群在财富、收入上的差别，不能用来比较土地的大小。"}, {"text": "这两款手机的贫富差距很大。", "explanation": "这里应该用〈价格差距〉。贫富差距指人群在财富、收入上的差别，不能用来比较商品的价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20083, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贫富差距", "is_correct": true, "explanation": "正确：“关于贫富差距的文章”是常见的作文题目，话题合理。"}, {"text": "旁边", "is_correct": false, "explanation": "语义：“旁边”是方位词，不能作为文章的话题。"}, {"text": "上面", "is_correct": false, "explanation": "语义：“上面”是方位词，不能作为文章的话题。"}, {"text": "非常", "is_correct": false, "explanation": "语法：「非常」是副词，不能作为「关于……的文章」中的话题，句子不通。"}], "explanations": {"贫富差距": "正确：“关于贫富差距的文章”是常见的作文题目，话题合理。", "旁边": "语义：“旁边”是方位词，不能作为文章的话题。", "上面": "语义：“上面”是方位词，不能作为文章的话题。", "非常": "语法：「非常」是副词，不能作为「关于……的文章」中的话题，句子不通。"}, "sentence_index": 6, "correct_answer": "贫富差距"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个孩子的贫富差距有十厘米。", "explanation": "这里应该用〈身高差距〉。贫富差距指财富上的差别，不能用厘米来衡量。"}, {"text": "我的汉语水平和他的贫富差距很大。", "explanation": "这里应该用〈水平差距〉。贫富差距指人群在财富、收入上的差别，不能用来比较语言水平的高低。"}, {"text": "这两杯咖啡的贫富差距很大。", "explanation": "这里应该用〈味道差距〉。贫富差距指人群在财富、收入上的差别，不能用来比较饮品的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个地区的贫富差距越来越很大。", "corrected_sentence": "那个地区的贫富差距越来越大。", "error_description": "错误形式：「越来越很大」。正确形式：「越来越大」。「越来越」已经表示程度在变化，后面的形容词前不能再加「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要缩小把贫富差距。", "corrected_sentence": "我们要缩小贫富差距。", "error_description": "错误形式：“缩小把贫富差距”。正确形式：“缩小贫富差距”。“把”字句只用于把宾语提到动词前面，这里宾语已经在动词“缩小”之后，不需要“把”，应去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20084, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坏事", "is_correct": true, "explanation": "反义：「坏事」与「好事」相对，指不好的、有害的事情，词典有此反义关系。"}, {"text": "烦恼", "is_correct": false, "explanation": "「烦恼」指心里的忧虑，与「好事」没有反义关系。"}, {"text": "道理", "is_correct": false, "explanation": "「道理」指事物的规律或理由，与「好事」没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "「天气」是自然现象，与「好事」不构成反义关系。"}], "correct_answer": "坏事", "explanations": {"坏事": "反义：「坏事」与「好事」相对，指不好的、有害的事情，词典有此反义关系。", "烦恼": "「烦恼」指心里的忧虑，与「好事」没有反义关系。", "道理": "「道理」指事物的规律或理由，与「好事」没有反义关系。", "天气": "「天气」是自然现象，与「好事」不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20084, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坏事", "is_correct": true, "explanation": "反义：「坏事」与「好事」相对，指不好的、有害的事情，词典有此反义关系。"}, {"text": "书本", "is_correct": false, "explanation": "「书本」指书籍，与「好事」没有反义关系。"}, {"text": "房间", "is_correct": false, "explanation": "「房间」指空间，与「好事」没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "「花园」指种花草的场所，与「好事」没有反义关系。"}], "correct_answer": "坏事", "explanations": {"坏事": "反义：「坏事」与「好事」相对，指不好的、有害的事情，词典有此反义关系。", "书本": "「书本」指书籍，与「好事」没有反义关系。", "房间": "「房间」指空间，与「好事」没有反义关系。", "花园": "「花园」指种花草的场所，与「好事」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指好的、有益的事情或善事。", "primary_collocate": null, "pronunciation": "hǎo shì", "ipa": "xɑʊ̯˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "技术进步是好事，但如果管理不好，也可能带来新的社会问题。", "target_word": "好事", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "他在路上捡到钱包，还给了失主，做了一件好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个周末都去帮助老人，做了很多好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少吃糖对身体是好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书对孩子来说是一件好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直做好事，大家都很喜欢他。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会自己做饭是好事，也能省钱。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常说，帮助别人是好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校组织大家捐书，这是一件好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人批评你不一定是坏事，也可能是好事。", "target_word": "好事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件好事", "label": "量词"}, {"form": "好事多磨", "label": "复合"}], "register": "中性", "sense_fingerprint": "好事：好的、有益的事情，也指善事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d483ca1-93ac-4b0e-b4cc-1888a4e9895c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好事", "is_correct": true, "explanation": "正确：好事，指好的、有益的事情。"}, {"text": "好似", "is_correct": false, "explanation": "声母不同：「好似」的第二音节是 sì，「好事」是 shì（s 与 sh 声母不同），意思是好像。"}, {"text": "好使", "is_correct": false, "explanation": "声调不同：「好使」的第二音节是第三声，「好事」是第四声，意思是好用、管用。"}, {"text": "海事", "is_correct": false, "explanation": "韵母不同：「海事」的第一音节韵母是 ai，「好事」是 ao，意思是海上的事务。"}, {"text": "考试", "is_correct": false, "explanation": "声母不同：「考试」以 k 开头，「好事」以 h 开头，意思是测验。"}], "explanations": {"好事": "正确：好事，指好的、有益的事情。", "好似": "声母不同：「好似」的第二音节是 sì，「好事」是 shì（s 与 sh 声母不同），意思是好像。", "好使": "声调不同：「好使」的第二音节是第三声，「好事」是第四声，意思是好用、管用。", "海事": "韵母不同：「海事」的第一音节韵母是 ai，「好事」是 ao，意思是海上的事务。", "考试": "声母不同：「考试」以 k 开头，「好事」以 h 开头，意思是测验。"}, "sentence_index": null, "correct_answer": "好事"}, "level_3": {"options": [{"text": "好事", "is_correct": true, "explanation": "正确：句子先说「技术进步是好事」，后面用「但」转折，前半句须是正面评价，只有「好事」合适。"}, {"text": "坏事", "is_correct": false, "explanation": "语义：「但」后转折说明前半句是正面评价，换成「坏事」前后矛盾。"}, {"text": "好人", "is_correct": false, "explanation": "语义：「技术进步」是事物，不能说是「好人」，句子说不通。"}, {"text": "好书", "is_correct": false, "explanation": "搭配：「好书」指书籍，不能用来评价「技术进步」这类抽象事物，搭配不当。"}], "explanations": {"好事": "正确：句子先说「技术进步是好事」，后面用「但」转折，前半句须是正面评价，只有「好事」合适。", "坏事": "语义：「但」后转折说明前半句是正面评价，换成「坏事」前后矛盾。", "好人": "语义：「技术进步」是事物，不能说是「好人」，句子说不通。", "好书": "搭配：「好书」指书籍，不能用来评价「技术进步」这类抽象事物，搭配不当。"}, "sentence_index": 0, "correct_answer": "好事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早睡对身体有好事。", "explanation": "这里应该用〈好处〉。说对身体的益处要用「好处」，「好事」指具体发生的事情，不能用来说身体的益处。"}, {"text": "诚实是他的好事。", "explanation": "这里应该用〈优点〉。说人的长处要用「优点」，「好事」指具体的好事情，不能用来说人的品质。"}, {"text": "他买到了一件好事，花的钱不多。", "explanation": "这里应该用〈好东西〉。「好事」指事情，不能用来指买到的物品，买来的东西要用「好东西」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20084, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "好事", "is_correct": true, "explanation": "正确：好事，指好的、有益的事情。"}, {"text": "老是", "is_correct": false, "explanation": "声母不同：「老是」以 l 开头，「好事」以 h 开头，意思是总是。"}, {"text": "保释", "is_correct": false, "explanation": "声母不同：「保释」以 b 开头，「好事」以 h 开头，意思是交保后释放。"}, {"text": "早市", "is_correct": false, "explanation": "声母不同：「早市」以 z 开头，意思是早上的集市。"}, {"text": "好戏", "is_correct": false, "explanation": "声母不同：「好戏」的第二音节是 xì，「好事」是 shì，意思是精彩的演出。"}], "explanations": {"好事": "正确：好事，指好的、有益的事情。", "老是": "声母不同：「老是」以 l 开头，「好事」以 h 开头，意思是总是。", "保释": "声母不同：「保释」以 b 开头，「好事」以 h 开头，意思是交保后释放。", "早市": "声母不同：「早市」以 z 开头，意思是早上的集市。", "好戏": "声母不同：「好戏」的第二音节是 xì，「好事」是 shì，意思是精彩的演出。"}, "sentence_index": null, "correct_answer": "好事"}, "level_3": {"options": [{"text": "好事", "is_correct": true, "explanation": "正确：「学会自己做饭」是好事，后面「也能省钱」是并列的好处，只有「好事」合适。"}, {"text": "坏人", "is_correct": false, "explanation": "语义：「学会做饭」是一件事，不能说是人，且与「也能省钱」的好处矛盾。"}, {"text": "好茶", "is_correct": false, "explanation": "语义：「学会做饭」不是茶，句子说不通。"}, {"text": "好画", "is_correct": false, "explanation": "搭配：「画」是作品，不能用来评价「学会做饭」这种能力，搭配不当。"}], "explanations": {"好事": "正确：「学会自己做饭」是好事，后面「也能省钱」是并列的好处，只有「好事」合适。", "坏人": "语义：「学会做饭」是一件事，不能说是人，且与「也能省钱」的好处矛盾。", "好茶": "语义：「学会做饭」不是茶，句子说不通。", "好画": "搭配：「画」是作品，不能用来评价「学会做饭」这种能力，搭配不当。"}, "sentence_index": 6, "correct_answer": "好事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这笔投资的好事很高，我们很满意。", "explanation": "这里应该用〈收益〉。说钱赚得多要用「收益」，「好事」是事情，不能说「好事很高」。"}, {"text": "他这次比赛取得了很大的好事，大家都很佩服。", "explanation": "这里应该用〈成就〉。「取得」后面接成就、成绩，要说「取得很大的成就」；「好事」指发生的事情，不能说「取得很大的好事」。"}, {"text": "这个手机有很多好事，比如电池很耐用。", "explanation": "这里应该用〈好处〉。说东西的优点、益处要用「好处」，「好事」指好的事情，不能说手机「有很多好事」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事对大家是一只好事。", "corrected_sentence": "这件事对大家是一件好事。", "error_description": "量词错误：「好事」的量词应为「件」，不能用「只」。「只」多用于动物或单个的小东西，不用于事情。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年做了一条好事。", "corrected_sentence": "他去年做了一件好事。", "error_description": "量词错误：「好事」的量词应为「件」，不能用「条」。「条」多用于细长的东西，如鱼、河、路，不用于事情。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a1d4253-60c4-4d49-bc24-1372accc4694') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
