INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20085, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对问题进行深入、细致的思维活动。", "primary_collocate": null, "pronunciation": "sī kǎo", "ipa": "sɹ̩˥ kʰɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们必须思考：在人工智能时代，如何让更多人受益？", "target_word": "思考", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "做决定以前，你要好好思考。", "target_word": "思考", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师请大家思考这个问题。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐在窗边，安静地思考着未来。", "target_word": "思考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到困难时，先停下来思考。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书让我思考了很多事情。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习不只是记住，还要学会思考。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他思考了很久，还是不知道怎么回答。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哲学家喜欢思考人生的意义。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子需要时间独立思考。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "思考了", "label": "体标"}, {"form": "思考着", "label": "体标"}, {"form": "思考过", "label": "体标"}, {"form": "思考思考", "label": "重叠"}], "register": "中性", "sense_fingerprint": "对问题进行深入、细致的思维活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df62efa0-2dbe-46fc-9d7d-40fafa899bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20085, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "思考", "is_correct": true, "explanation": "正确：“思考”表示对问题进行深入的思维活动，与“如何让更多人受益”的提问相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，不能带“：”后的问句作宾语。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”要求具体的物品作宾语，不能接一个问句。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与人工智能和受益的讨论无关，句意不通。"}], "explanations": {"思考": "正确：“思考”表示对问题进行深入的思维活动，与“如何让更多人受益”的提问相符。", "睡觉": "配价：“睡觉”是不及物动词，不能带“：”后的问句作宾语。", "购买": "配价：“购买”要求具体的物品作宾语，不能接一个问句。", "唱歌": "语义：“唱歌”与人工智能和受益的讨论无关，句意不通。"}, "sentence_index": 0, "correct_answer": "思考"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都思考远方的父母。", "explanation": "这里应该用〈思念〉。思考是动脑子分析问题；对亲人的牵挂应说「思念」。"}, {"text": "我思考喝一杯水。", "explanation": "这里应该用〈想〉。思考指动脑子想问题，不能表示想要做某事。"}, {"text": "他思考房间里的灰尘。", "explanation": "这里应该用〈打扫〉。思考是动脑子想问题，不能表示清扫灰尘这个动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20085, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思考", "is_correct": true, "explanation": "正确：“学会思考”与前句“不只是记住”形成对比，句意通顺。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是自然现象，人不能学会下雨。"}, {"text": "发生", "is_correct": false, "explanation": "配价：“发生”表示事情出现，不能作为人主动学会的动作，不能接“学会”。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是生病，不是可以学会的技能。"}], "explanations": {"思考": "正确：“学会思考”与前句“不只是记住”形成对比，句意通顺。", "下雨": "语义：“下雨”是自然现象，人不能学会下雨。", "发生": "配价：“发生”表示事情出现，不能作为人主动学会的动作，不能接“学会”。", "感冒": "语义：“感冒”是生病，不是可以学会的技能。"}, "sentence_index": 6, "correct_answer": "思考"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用钥匙思考了房门。", "explanation": "这里应该用〈打开〉。思考是动脑子想问题，不能表示用钥匙开门的动作。"}, {"text": "他思考了一双新鞋。", "explanation": "这里应该用〈穿〉。思考是动脑子想问题，不能表示穿鞋这个动作。"}, {"text": "他每天思考两顿饭。", "explanation": "这里应该用〈吃〉。思考不能表示吃饭的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20085, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "做决定以前，我们要好好思考了一下。", "corrected_sentence": "做决定以前，我们要好好思考一下。", "error_description": "错误在「了」：「要好好思考」指尚未发生的动作，与表示完成的「了」相矛盾；应去掉「了」，说「思考一下」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20085, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要认真得思考这个问题。", "corrected_sentence": "我们要认真思考这个问题。", "error_description": "错误形式：“认真得思考”。正确形式：“认真思考”。“得”是补语标记，不能放在动词前作状语，此处应直接说“认真思考”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5130e15f-d8d7-488d-bde2-1feee74671e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
