INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20086, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受损", "is_correct": true, "explanation": "受损：与“受益”相反，指遭受损失或伤害"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：与“受益”没有反义关系"}, {"text": "讨论", "is_correct": false, "explanation": "讨论：与“受益”没有反义关系"}, {"text": "启程", "is_correct": false, "explanation": "启程：与“受益”没有反义关系"}], "correct_answer": "受损", "explanations": {"受损": "受损：与“受益”相反，指遭受损失或伤害", "唱歌": "唱歌：与“受益”没有反义关系", "讨论": "讨论：与“受益”没有反义关系", "启程": "启程：与“受益”没有反义关系"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20086, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得到好处；获得利益。", "primary_collocate": null, "pronunciation": "shòu yì", "ipa": "ʂoʊ⁵¹ i⁵¹", "syllable_count": 2, "sentences": [{"text": "我们必须思考：在人工智能时代，如何让更多人受益？", "target_word": "受益", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "多读书的人，一辈子都会受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个新政策让很多农民受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的建议让我受益很多。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从这次谈话中受益不少。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新路修好后，附近的居民都受益了。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经常运动，身体会受益。", "target_word": "受益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们从免费午餐中受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从朋友的经验里受益过。", "target_word": "受益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好英语，你以后会受益的。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "受益人", "label": "复合"}, {"form": "受益者", "label": "复合"}, {"form": "受益了", "label": "体标"}], "register": "中性", "sense_fingerprint": "从某事或某人那里得到好处、获得利益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '346c9218-cb43-4e91-8a90-710077c45e12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20086, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "受益", "is_correct": true, "explanation": "受益（shòu yì）：得到好处，与听到的读音一致"}, {"text": "收益", "is_correct": false, "explanation": "shōu（第一声）与 shòu（第四声）声调不同，收益指所得的利润或收入"}, {"text": "手艺", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，手艺指手工技能"}, {"text": "寿衣", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，寿衣指为去世者准备的衣服"}, {"text": "兽医", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，兽医指给动物看病的人"}], "explanations": {"受益": "受益（shòu yì）：得到好处，与听到的读音一致", "收益": "shōu（第一声）与 shòu（第四声）声调不同，收益指所得的利润或收入", "手艺": "shǒu（第三声）与 shòu（第四声）声调不同，手艺指手工技能", "寿衣": "yī（第一声）与 yì（第四声）声调不同，寿衣指为去世者准备的衣服", "兽医": "yī（第一声）与 yì（第四声）声调不同，兽医指给动物看病的人"}, "sentence_index": null, "correct_answer": "受益"}, "level_3": {"options": [{"text": "受益", "is_correct": true, "explanation": "受益：得到好处，符合“让更多人……”的语境"}, {"text": "受伤", "is_correct": false, "explanation": "语义：“受伤”指遭受伤害，与这里要表达的好处相反"}, {"text": "吃亏", "is_correct": false, "explanation": "语义：“吃亏”指遭受损失，与“受益”的意思相反"}, {"text": "挨骂", "is_correct": false, "explanation": "语义：“挨骂”指受到责备，与“让更多人……”所指的好处不符，句意不通。"}], "explanations": {"受益": "受益：得到好处，符合“让更多人……”的语境", "受伤": "语义：“受伤”指遭受伤害，与这里要表达的好处相反", "吃亏": "语义：“吃亏”指遭受损失，与“受益”的意思相反", "挨骂": "语义：“挨骂”指受到责备，与“让更多人……”所指的好处不符，句意不通。"}, "sentence_index": 0, "correct_answer": "受益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次培训让我受益了很多经验。", "explanation": "这里应该用〈获得〉。受益是不及物动词，后面不能直接带“经验”作宾语；获得可以带宾语"}, {"text": "这家公司今年的受益增加了很多。", "explanation": "这里应该用〈收益〉。收益是名词，指所得的利润；受益是动词，不能作名词用"}, {"text": "他因为长期熬夜，身体受益了很多。", "explanation": "这里应该用〈受损〉。受益表示得到好处，长期熬夜带来的是伤害，应说“受损”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受益", "is_correct": true, "explanation": "受益：得到好处，符合“经常运动”的健康效果"}, {"text": "衰老", "is_correct": false, "explanation": "语义：经常运动有助于延缓衰老，“衰老”与好处相反"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是坏结果，与“经常运动”的好处相反"}, {"text": "变丑", "is_correct": false, "explanation": "体貌：“变丑”说的是外貌，与“身体会……”的健康语境不合"}], "explanations": {"受益": "受益：得到好处，符合“经常运动”的健康效果", "衰老": "语义：经常运动有助于延缓衰老，“衰老”与好处相反", "生病": "语义：“生病”是坏结果，与“经常运动”的好处相反", "变丑": "体貌：“变丑”说的是外貌，与“身体会……”的健康语境不合"}, "sentence_index": 6, "correct_answer": "受益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动对身体受益。", "explanation": "这里应该用〈有益〉。“对身体”之后要接形容词“有益”；受益是动词，表示得到好处，不能这样用"}, {"text": "这个月我的体重受益了三公斤。", "explanation": "这里应该用〈增加〉。受益指人得到好处，体重增加是数量变化，不能说受益；数量变化要用增加"}, {"text": "这个假期我们受益了很多乐趣。", "explanation": "这里应该用〈享受〉。受益是不及物动词，不能直接带“乐趣”作宾语；享受可以带宾语"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次培训被我受益很多。", "corrected_sentence": "这次培训让我受益很多。", "error_description": "错误：用“被”字句。“受益”是不及物动词，不能用于被动结构，应说“这次培训让我受益很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们从这次活动中受益着不少。", "corrected_sentence": "学生们从这次活动中受益了不少。", "error_description": "错误：体标用错。表示已经得到的好处要用“了”，应说“从这次活动中受益了不少”，不说“受益着不少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20094, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独享", "is_correct": true, "explanation": "独享：独自享有，不给别人用，与“分享”相对。"}, {"text": "修改", "is_correct": false, "explanation": "“修改”指改动内容，与“分享”没有相对关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看，与“分享”不构成反义。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”指使有条理，与“分享”不构成反义。"}], "correct_answer": "独享", "explanations": {"独享": "独享：独自享有，不给别人用，与“分享”相对。", "修改": "“修改”指改动内容，与“分享”没有相对关系。", "观察": "“观察”指仔细看，与“分享”不构成反义。", "整理": "“整理”指使有条理，与“分享”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20094, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独享", "is_correct": true, "explanation": "独享：独自享有，不给别人用，与“分享”相对。"}, {"text": "搬运", "is_correct": false, "explanation": "“搬运”指把东西从一处移到另一处，与“分享”不构成反义。"}, {"text": "邀请", "is_correct": false, "explanation": "“邀请”指请人来或参加，与“分享”不构成反义。"}, {"text": "打印", "is_correct": false, "explanation": "“打印”指把文件印在纸上，与“分享”不构成反义。"}], "correct_answer": "独享", "explanations": {"独享": "独享：独自享有，不给别人用，与“分享”相对。", "搬运": "“搬运”指把东西从一处移到另一处，与“分享”不构成反义。", "邀请": "“邀请”指请人来或参加，与“分享”不构成反义。", "打印": "“打印”指把文件印在纸上，与“分享”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20094, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将信息或资源提供给他人使用", "primary_collocate": null, "pronunciation": "fēn xiǎng", "ipa": "fən˥ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "比如，系统需要说明哪些数据用来改进产品，哪些可能分享给合作伙伴。", "target_word": "分享", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "老师把这份学习资料分享给了全班同学。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以把这个视频分享给朋友看。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要求员工不要随便分享客户的信息。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在网上分享了很多学习方法。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个文件分享给我，我也想看看。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他愿意分享自己的旅行照片和路线。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件可以和别人分享电脑里的文件。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李分享了一个很有用的网站。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家把有用的资料分享到群里。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分享了", "label": "体标"}, {"form": "分享过", "label": "体标"}, {"form": "分享着", "label": "体标"}, {"form": "分享会", "label": "复合"}, {"form": "分享者", "label": "复合"}], "register": "中性", "sense_fingerprint": "分享：把信息、资料等资源提供给他人使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a50759fb-3f82-4d2e-b11e-78657eb50899') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20094, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分享", "is_correct": true, "explanation": "分享 fēn xiǎng：把信息、资源提供给他人使用，正确答案。"}, {"text": "分晓", "is_correct": false, "explanation": "分晓 fēn xiǎo 与 分享 fēn xiǎng 第二个音节韵母不同（iao 与 iang），意思是事情的结果。"}, {"text": "风向", "is_correct": false, "explanation": "风向 fēng xiàng 与 分享 fēn xiǎng 韵母和声调略有不同（eng/en，第四声/第三声），意思是风吹来的方向。"}, {"text": "分项", "is_correct": false, "explanation": "分项 fēn xiàng（第四声）与 分享 fēn xiǎng（第三声）第二个音节声调不同，意思是按项目分开。"}], "explanations": {"分享": "分享 fēn xiǎng：把信息、资源提供给他人使用，正确答案。", "分晓": "分晓 fēn xiǎo 与 分享 fēn xiǎng 第二个音节韵母不同（iao 与 iang），意思是事情的结果。", "风向": "风向 fēng xiàng 与 分享 fēn xiǎng 韵母和声调略有不同（eng/en，第四声/第三声），意思是风吹来的方向。", "分项": "分项 fēn xiàng（第四声）与 分享 fēn xiǎng（第三声）第二个音节声调不同，意思是按项目分开。"}, "sentence_index": null, "correct_answer": "分享"}, "level_3": {"options": [{"text": "分享", "is_correct": true, "explanation": "分享：把数据提供给合作伙伴使用，与句中“可能……给合作伙伴”相符。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”与“分享”意思相反，句意变成不让合作伙伴知道，与“说明”的语境不符。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是护着、不受侵害，与把数据交给伙伴的意思不合。"}, {"text": "收集", "is_correct": false, "explanation": "语义：“收集”是聚拢起来，不是提供给别人，与“给合作伙伴”的意思不合。"}], "explanations": {"分享": "分享：把数据提供给合作伙伴使用，与句中“可能……给合作伙伴”相符。", "隐瞒": "语义：“隐瞒”与“分享”意思相反，句意变成不让合作伙伴知道，与“说明”的语境不符。", "保护": "语义：“保护”是护着、不受侵害，与把数据交给伙伴的意思不合。", "收集": "语义：“收集”是聚拢起来，不是提供给别人，与“给合作伙伴”的意思不合。"}, "sentence_index": 0, "correct_answer": "分享"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸和妈妈一起分享家务。", "explanation": "这里应该用〈分担〉。分享指把信息、资源提供给他人使用，家务要用分担。"}, {"text": "警察分享了这批货。", "explanation": "这里应该用〈没收〉。没收是把物品强行收归公有，分享是把东西提供给他人使用，警察不会把货分享给别人。"}, {"text": "老师分享了那个学生。", "explanation": "这里应该用〈表扬〉。分享的对象是信息、资料等东西，不能是人；称赞学生要说表扬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分享", "is_correct": true, "explanation": "分享：把自己的照片和路线提供给别人看，与句意相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”只接食物，不能接“照片和路线”。"}, {"text": "咀嚼", "is_correct": false, "explanation": "语义：“咀嚼”指嚼碎食物，与照片、路线的意思不合。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：“吞下”指咽进口中的东西，与照片、路线不相容。"}], "explanations": {"分享": "分享：把自己的照片和路线提供给别人看，与句意相符。", "煮": "搭配：“煮”只接食物，不能接“照片和路线”。", "咀嚼": "语义：“咀嚼”指嚼碎食物，与照片、路线的意思不合。", "吞下": "语义：“吞下”指咽进口中的东西，与照片、路线不相容。"}, "sentence_index": 6, "correct_answer": "分享"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这首歌分享在手机里。", "explanation": "这里应该用〈收藏〉。收藏是自己留着保存，分享要提供给他人使用。"}, {"text": "大火分享了整座房子。", "explanation": "这里应该用〈摧毁〉。摧毁是毁坏东西，分享是把东西提供给他人使用，大火不会把房子分享给谁。"}, {"text": "他按时把书分享给了那张桌子。", "explanation": "这里应该用〈放在〉。分享的对象应是能使用东西的人，桌子不能接受分享，书应放在桌上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这份报告分享了给同事。", "corrected_sentence": "我把这份报告分享给了同事。", "error_description": "错误：“分享了给”；正确：“分享给了”。“给”是分享的补充成分，“了”应放在“给”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不分享过这个网站。", "corrected_sentence": "他没分享过这个网站。", "error_description": "错误：“不分享过”；正确：“没分享过”。表示没有过某种经历要用“没……过”，“不”不能与体标“过”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
