INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20103, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20103, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用户与服务方之间规定权利和义务的条款文件", "primary_collocate": null, "pronunciation": "xié yì", "ipa": "ɕjɛ˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "协议", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "注册以前，请先读一读协议。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没看协议就点了同意。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协议里写着公司怎么用你的信息。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份协议太长，我看不完。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点击同意，就是接受协议。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件的协议说明了你可以做什么。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把协议里的小字读了一遍。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同意协议，就不能用这个应用。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协议里说，公司不会卖你的电话号码。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "用户协议", "label": "复合"}, {"form": "協議", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用户与服务方约定权利义务的条款文件，如使用软件前要同意的协议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1be5a6e3-5db9-4be7-88db-c287895b77cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20103, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "协议", "is_correct": true, "explanation": "协议（xié yì，第二声、第四声）指用户与服务方之间规定权利和义务的条款文件，是正确答案。"}, {"text": "谢意", "is_correct": false, "explanation": "谢意（xiè yì）的第一个音节是第四声，与 xié（第二声）声调不同，意思是感谢。"}, {"text": "写意", "is_correct": false, "explanation": "写意（xiě yì）的第一个音节是第三声，与 xié（第二声）声调不同，意思是绘画时着重表现神韵、不求细致。"}, {"text": "洗衣", "is_correct": false, "explanation": "洗衣（xǐ yī）两个音节的声调都与协议（xié yì）不同，意思是洗衣服。"}, {"text": "西医", "is_correct": false, "explanation": "西医（xī yī）两个音节的声调都与协议（xié yì）不同，意思是西方医学。"}], "explanations": {"协议": "协议（xié yì，第二声、第四声）指用户与服务方之间规定权利和义务的条款文件，是正确答案。", "谢意": "谢意（xiè yì）的第一个音节是第四声，与 xié（第二声）声调不同，意思是感谢。", "写意": "写意（xiě yì）的第一个音节是第三声，与 xié（第二声）声调不同，意思是绘画时着重表现神韵、不求细致。", "洗衣": "洗衣（xǐ yī）两个音节的声调都与协议（xié yì）不同，意思是洗衣服。", "西医": "西医（xī yī）两个音节的声调都与协议（xié yì）不同，意思是西方医学。"}, "sentence_index": null, "correct_answer": "协议"}, "level_3": {"options": [{"text": "协议", "is_correct": true, "explanation": "“用户协议”指用户与服务方之间的条款文件，“依赖用户协议中的概括性条款”符合句意。"}, {"text": "用户名", "is_correct": false, "explanation": "语义：“概括性条款”写在协议这类文件中，不能写在用户名里，句子不通。"}, {"text": "用户头像", "is_correct": false, "explanation": "语义：头像是图片，不包含“概括性条款”，“依赖用户头像中的概括性条款”无法成立。"}, {"text": "用户体验", "is_correct": false, "explanation": "搭配：“用户体验”不作为条款的载体，“依赖用户体验中的概括性条款”搭配不通。"}], "explanations": {"协议": "“用户协议”指用户与服务方之间的条款文件，“依赖用户协议中的概括性条款”符合句意。", "用户名": "语义：“概括性条款”写在协议这类文件中，不能写在用户名里，句子不通。", "用户头像": "语义：头像是图片，不包含“概括性条款”，“依赖用户头像中的概括性条款”无法成立。", "用户体验": "搭配：“用户体验”不作为条款的载体，“依赖用户体验中的概括性条款”搭配不通。"}, "sentence_index": 0, "correct_answer": "协议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用这份协议包了饺子。", "explanation": "这里应该用〈饺子皮〉。协议是双方约定权利义务的条款文件，不能用来包饺子。"}, {"text": "他每天睡前都喝一杯协议。", "explanation": "这里应该用〈牛奶〉。协议是条款文件，不能用来喝。"}, {"text": "这份协议写着怎么安装这台机器。", "explanation": "这里应该用〈说明书〉。协议规定双方的权利和义务，安装步骤要用说明书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20103, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "协议", "is_correct": true, "explanation": "“软件的协议”指软件的使用条款，可以说明你可以做什么，符合句意。"}, {"text": "密码", "is_correct": false, "explanation": "语义：密码是登录凭据，不能说明你可以做什么。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格说明的是花费，不是你可以做什么。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能作为说明功能的主体，“软件的颜色说明了……”搭配不通。"}], "explanations": {"协议": "“软件的协议”指软件的使用条款，可以说明你可以做什么，符合句意。", "密码": "语义：密码是登录凭据，不能说明你可以做什么。", "价格": "语义：价格说明的是花费，不是你可以做什么。", "颜色": "搭配：“颜色”不能作为说明功能的主体，“软件的颜色说明了……”搭配不通。"}, "sentence_index": 6, "correct_answer": "协议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上都吃协议。", "explanation": "这里应该用〈面包〉。协议是双方约定权利义务的条款文件，不能拿来吃。"}, {"text": "买完东西，店员给了我一张协议，我用它包了点心。", "explanation": "这里应该用〈包装纸〉。协议是双方约定权利义务的条款文件，不能用来包东西。"}, {"text": "他考过了，拿到了教师资格协议。", "explanation": "这里应该用〈证书〉。协议是双方订立的约定，证明资格要用证书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把协议签。", "corrected_sentence": "请把协议签好。", "error_description": "“把”字句中动词后要有结果补语或其他成分，不能只说“签”。应说“签好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看完一协议才签字。", "corrected_sentence": "我看完一份协议才签字。", "error_description": "“协议”前有数量词“一”时需要量词，应说“一份协议”，不能说“一协议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
