INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20105, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "信息或控制的等级层次，表示公开程度的高低", "primary_collocate": null, "pronunciation": "céng jí", "ipa": "tsʰɤŋ˧˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "代理在调用敏感数据前，必须先确认该权限所属的层级，再对自身决策过程进行反思性建模。", "target_word": "层级", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "公司把文件分成不同的保密层级。", "target_word": "层级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同层级的员工能看到不同的信息。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份文件的保密层级很高，不能公开。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "系统按层级管理权限，普通用户只能看到公开内容。", "target_word": "层级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最高层级的信息只有经理才能打开。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们给每份资料设置了不同的层级。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "低层级的资料，所有人都可以看。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网站把用户信息分为三个层级。", "target_word": "层级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先确认这份报告的公开层级，再发给客户。", "target_word": "层级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "层级结构", "label": "复合"}, {"form": "层级关系", "label": "复合"}], "register": "书面", "sense_fingerprint": "信息、权限按保密或公开程度划分的等级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98f4a8b1-54f9-4af0-bf82-5bf023832828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20105, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "层级", "is_correct": true, "explanation": "正确。“权限所属的层级”指权限按保密程度划分的等级，搭配自然。"}, {"text": "距离", "is_correct": false, "explanation": "语义：权限不能“所属”某种距离，“所属的距离”不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：权限没有颜色，“所属的颜色”句子无法成立。"}, {"text": "体重", "is_correct": false, "explanation": "语义：权限没有体重，“所属的体重”句子无法成立。"}], "explanations": {"层级": "正确。“权限所属的层级”指权限按保密程度划分的等级，搭配自然。", "距离": "语义：权限不能“所属”某种距离，“所属的距离”不通。", "颜色": "语义：权限没有颜色，“所属的颜色”句子无法成立。", "体重": "语义：权限没有体重，“所属的体重”句子无法成立。"}, "sentence_index": 0, "correct_answer": "层级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "从技术层级看，这个方案没有问题。", "explanation": "这里应该用〈层面〉。“层级”指等级的高低次序，从某个方面看问题要用“层面”。"}, {"text": "他在医疗层级很有名。", "explanation": "这里应该用〈领域〉。“层级”不表示专业范围，说某个专业范围要用“领域”。"}, {"text": "我们正处于发展层级。", "explanation": "这里应该用〈阶段〉。“层级”指上下等级，说事情进行到哪一步要用“阶段”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20105, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "层级", "is_correct": true, "explanation": "正确。“设置不同的层级”指按公开程度划分的等级，搭配自然。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：资料没有年龄，不能设置年龄。"}, {"text": "味道", "is_correct": false, "explanation": "语义：资料不是食物，没有味道可以设置。"}, {"text": "性格", "is_correct": false, "explanation": "语义：资料本身没有性格可以设定，句中“资料”不能有性格。"}], "explanations": {"层级": "正确。“设置不同的层级”指按公开程度划分的等级，搭配自然。", "年龄": "语义：资料没有年龄，不能设置年龄。", "味道": "语义：资料不是食物，没有味道可以设置。", "性格": "语义：资料本身没有性格可以设定，句中“资料”不能有性格。"}, "sentence_index": 6, "correct_answer": "层级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在电脑方面的层级很高，什么问题都能解决。", "explanation": "这里应该用〈水平〉。“层级”指信息或权限的等级划分，个人能力的高低要用“水平”。"}, {"text": "这次考试的层级很大，很多人没及格。", "explanation": "这里应该用〈难度〉。“层级”不表示难易，考试难不难要用“难度”。"}, {"text": "我们按时间层级把照片排好了。", "explanation": "这里应该用〈顺序〉。“层级”指高低等级，按先后排列要用“顺序”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20105, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套系统一共设了三本保密层级。", "corrected_sentence": "这套系统一共设了三个保密层级。", "error_description": "“层级”的量词应用“个”，不能用“本”（“本”用于书籍）。写作：这套系统一共设了三个保密层级。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20105, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些资料按公开程度分成了几个层级们。", "corrected_sentence": "这些资料按公开程度分成了几个层级。", "error_description": "“层级”是无生命名词，不能加后缀“们”表示复数；“们”只用于指人的名词。写作：这些资料按公开程度分成了几个层级。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
