INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "试图破坏或侵入系统的行为", "primary_collocate": null, "pronunciation": "gōng jī", "ipa": "kʊŋ˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "公司的网站遭到了一次攻击。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次攻击让很多人的网站打不开。", "target_word": "攻击", "complexity_tier": "T3", "furigana": "gōng jī", "sentence_source": "generated"}, {"text": "黑客的攻击持续了三个小时。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要做好防止攻击的准备。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能发现来自外面的攻击。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行每天都会遇到很多次攻击。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次攻击让公司的电脑全部坏了。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，这种攻击很难发现。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了挡住攻击，他们换了新的系统。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站在攻击中丢失了很多资料。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次攻击", "label": "量词：次"}, {"form": "网络攻击", "label": "复合词"}, {"form": "黑客攻击", "label": "复合词"}, {"form": "攻击者", "label": "复合词"}, {"form": "攻擊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "攻击：对电脑、网络等系统的破坏或入侵行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c5aa7d-598b-40b2-9bba-04033b920a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20106, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "攻击", "is_correct": true, "explanation": "攻击：试图破坏或侵入系统的行为。"}, {"text": "功绩", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是功劳和业绩。"}, {"text": "供给", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，意思是供应、提供。"}, {"text": "公斤", "is_correct": false, "explanation": "jīn 与 jī 的韵母不同（多了韵尾 n），意思是重量单位“公斤”。"}], "explanations": {"攻击": "攻击：试图破坏或侵入系统的行为。", "功绩": "jì（第四声）与 jī（第一声）声调不同，意思是功劳和业绩。", "供给": "jǐ（第三声）与 jī（第一声）声调不同，意思是供应、提供。", "公斤": "jīn 与 jī 的韵母不同（多了韵尾 n），意思是重量单位“公斤”。"}, "sentence_index": null, "correct_answer": "攻击"}, "level_3": {"options": [{"text": "攻击", "is_correct": true, "explanation": "攻击：指对系统的破坏或入侵行为，与“遭到了一次”相合。"}, {"text": "访问", "is_correct": false, "explanation": "语义：“访问”是中性的浏览行为，不是“遭到”的负面事件。"}, {"text": "备份", "is_correct": false, "explanation": "搭配：“备份”是主动做的保存工作，不能说“遭到了一次备份”。"}, {"text": "升级", "is_correct": false, "explanation": "语义：“升级”指系统版本提升，不是使网站遭受的事件，与“遭到”不符。"}], "explanations": {"攻击": "攻击：指对系统的破坏或入侵行为，与“遭到了一次”相合。", "访问": "语义：“访问”是中性的浏览行为，不是“遭到”的负面事件。", "备份": "搭配：“备份”是主动做的保存工作，不能说“遭到了一次备份”。", "升级": "语义：“升级”指系统版本提升，不是使网站遭受的事件，与“遭到”不符。"}, "sentence_index": 0, "correct_answer": "攻击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次攻击让我们学到了很多新知识。", "explanation": "这里应用〈讲座〉。“攻击”指对系统的破坏或入侵，不会让人学到知识。"}, {"text": "我们给电脑安装了攻击。", "explanation": "这里应用〈防火墙〉。“攻击”是一种入侵行为，不是可以安装的东西。"}, {"text": "我们给重要文件加了攻击，防止别人偷看。", "explanation": "这里应用〈加密〉。“攻击”是破坏或入侵，不是保护资料的做法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "攻击", "is_correct": true, "explanation": "攻击：指对系统的破坏或入侵行为，与“让公司的电脑全部坏了”的结果相合。"}, {"text": "讲座", "is_correct": false, "explanation": "语义：“讲座”是知识交流活动，不会造成电脑损坏，句意不通。"}, {"text": "会议", "is_correct": false, "explanation": "语义：“会议”是开会的活动，与电脑损坏没有因果关系。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是对人的赞许，不会造成电脑损坏，句意不通。"}], "explanations": {"攻击": "攻击：指对系统的破坏或入侵行为，与“让公司的电脑全部坏了”的结果相合。", "讲座": "语义：“讲座”是知识交流活动，不会造成电脑损坏，句意不通。", "会议": "语义：“会议”是开会的活动，与电脑损坏没有因果关系。", "表扬": "语义：“表扬”是对人的赞许，不会造成电脑损坏，句意不通。"}, "sentence_index": 6, "correct_answer": "攻击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我给朋友寄了一份攻击当生日礼物。", "explanation": "这里应用〈礼物〉。“攻击”指对系统的破坏或入侵行为，不能寄给别人。"}, {"text": "他在餐厅点了一份攻击。", "explanation": "这里应用〈菜〉。“攻击”指对系统的破坏或入侵行为，不是可以点的菜。"}, {"text": "他把攻击放进了冰箱。", "explanation": "这里应用〈牛奶〉。“攻击”指对系统的破坏或入侵行为，不是可以放进冰箱的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "服务器昨晚遭到了一把攻击。", "corrected_sentence": "服务器昨晚遭到了一次攻击。", "error_description": "“攻击”作名词时量词应用“次”，“把”用于有柄的器具，不能用于攻击，应为“一次攻击”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "服务器每天都会受到很多张攻击。", "corrected_sentence": "服务器每天都会受到很多次攻击。", "error_description": "错误：“张”用于纸、桌子等平面的东西，不能计量“攻击”。“攻击”作名词时量词用“次”。正确：“服务器每天都会受到很多次攻击。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
