INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20109, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "说出来的能够表达思想的声音，或记录这种声音的文字。", "primary_collocate": null, "pronunciation": "huà", "ipa": "xwa˥˩", "syllable_count": 1, "sentences": [{"text": "小明教它说话、写字。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "它们能听懂话，也能做事情。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这本书里的话，孩子们都能读懂。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国人说的话，我听不太懂。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把老师的话写在了本子上。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "录音里的话，我听了三遍。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话用中文怎么写？", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟学会了人说的话。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上写着一句话：欢迎你来。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还小，说不出完整的话。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一句话", "label": "量词"}, {"form": "话语", "label": "复合"}, {"form": "对话", "label": "复合"}], "register": "中性", "sense_fingerprint": "表达思想的声音或其文字记录", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b44a80eb-78df-43d2-b3b5-0ae745060986') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20109, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "话", "is_correct": true, "explanation": "正确答案。话（huà）指说出来能表达思想的声音，或记录这种声音的文字。"}, {"text": "花", "is_correct": false, "explanation": "huā（第一声）与 huà（第四声）声调不同，意思是花朵。"}, {"text": "活", "is_correct": false, "explanation": "huó（第二声）与 huà（第四声）声调不同，意思是活动、生存。"}, {"text": "货", "is_correct": false, "explanation": "huò 与 huà 韵母不同（-o 与 -a），声调相同，意思是货物。"}, {"text": "坏", "is_correct": false, "explanation": "huài 与 huà 韵母不同（-ai 与 -a），意思是坏、不好。"}], "explanations": {"话": "正确答案。话（huà）指说出来能表达思想的声音，或记录这种声音的文字。", "花": "huā（第一声）与 huà（第四声）声调不同，意思是花朵。", "活": "huó（第二声）与 huà（第四声）声调不同，意思是活动、生存。", "货": "huò 与 huà 韵母不同（-o 与 -a），声调相同，意思是货物。", "坏": "huài 与 huà 韵母不同（-ai 与 -a），意思是坏、不好。"}, "sentence_index": null, "correct_answer": "话"}, "level_3": {"options": [{"text": "话", "is_correct": true, "explanation": "正确。“说话”指说出能表达思想的声音，与“教它说”相符。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“说”不搭配“歌”，应说“唱歌”。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“说”不搭配“饭”，应说“吃饭”。"}, {"text": "钱", "is_correct": false, "explanation": "语义：“教它说钱”不表示学习说话，句意不通。"}], "explanations": {"话": "正确。“说话”指说出能表达思想的声音，与“教它说”相符。", "歌": "搭配：“说”不搭配“歌”，应说“唱歌”。", "饭": "搭配：“说”不搭配“饭”，应说“吃饭”。", "钱": "语义：“教它说钱”不表示学习说话，句意不通。"}, "sentence_index": 0, "correct_answer": "话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我听不太懂外国人吃的话。", "explanation": "这里应该用〈说〉。吃的是食物，话不能吃。"}, {"text": "外国人写的一个话，我听不太懂。", "explanation": "量词错误：话用〈句〉计量，这里不能用〈个〉。"}, {"text": "我听不太懂外国人穿的话。", "explanation": "这里应该用〈说〉。穿的是衣服，话不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20109, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "话", "is_correct": true, "explanation": "正确答案。话（huà）指说出来能表达思想的声音，或记录这种声音的文字。"}, {"text": "货", "is_correct": false, "explanation": "huò 与 huà 韵母不同（-o 与 -a），声调相同，意思是货物。"}, {"text": "晃", "is_correct": false, "explanation": "huàng 与 huà 韵母不同（-ang 与 -a），意思是晃动、闪光。"}, {"text": "华", "is_correct": false, "explanation": "huá（第二声）与 huà（第四声）声调不同，意思是中华、华丽。"}, {"text": "坏", "is_correct": false, "explanation": "huài 与 huà 韵母不同（-ai 与 -a），意思是坏、不好。"}], "explanations": {"话": "正确答案。话（huà）指说出来能表达思想的声音，或记录这种声音的文字。", "货": "huò 与 huà 韵母不同（-o 与 -a），声调相同，意思是货物。", "晃": "huàng 与 huà 韵母不同（-ang 与 -a），意思是晃动、闪光。", "华": "huá（第二声）与 huà（第四声）声调不同，意思是中华、华丽。", "坏": "huài 与 huà 韵母不同（-ai 与 -a），意思是坏、不好。"}, "sentence_index": null, "correct_answer": "话"}, "level_3": {"options": [{"text": "话", "is_correct": true, "explanation": "正确。“这句话”指一句言语或文字，“怎么写”说明它是文字记录。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是句子，“这句颜色”无法用中文书写。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：量词“句”不能计量价格，“这句价格”不成立。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：量词“句”只计量言语，不能说“这句礼物”。"}], "explanations": {"话": "正确。“这句话”指一句言语或文字，“怎么写”说明它是文字记录。", "颜色": "语义：颜色不是句子，“这句颜色”无法用中文书写。", "价格": "搭配：量词“句”不能计量价格，“这句价格”不成立。", "礼物": "搭配：量词“句”只计量言语，不能说“这句礼物”。"}, "sentence_index": 6, "correct_answer": "话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子还小，弹不出完整的话。", "explanation": "这里应该用〈曲子〉。弹的是乐曲，话不能弹。"}, {"text": "孩子还小，说不出完整的一首话。", "explanation": "量词错误：“首”用于诗歌、歌曲，话应用“句”计量。"}, {"text": "孩子还小，穿不上完整的话。", "explanation": "这里应该用〈衣服〉。穿的是衣服，话不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他给我写了一个话。", "corrected_sentence": "他给我写了一段话。", "error_description": "量词错误：“话”应用量词“段”或“句”计量，不能用“个”，应说“一段话”，不能说“一个话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师写的一个话我都抄下来了。", "corrected_sentence": "老师写的一句话我都抄下来了。", "error_description": "量词错误：话应用“句”计量，这里不能用“个”，应说“一句话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
