INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20110, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为实现共同目标而采取的特定行动或策略", "primary_collocate": null, "pronunciation": "zuò fǎ", "ipa": "tswo˥˩ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种做法可以让更多人参与改进技术，也能加快创新的速度。", "target_word": "做法", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "大家一起打扫公园，是个好做法。", "target_word": "做法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了省电，全家一起少开灯的做法很有用。", "target_word": "做法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社区让邻居互相帮忙，这种做法很受欢迎。", "target_word": "做法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一起存钱买书，这个做法不错。", "target_word": "做法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了提高成绩，我们采取了新的做法。", "target_word": "做法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司和学校一起办活动，这样的做法让双方都满意。", "target_word": "做法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得大家轮流工作是最公平的做法。", "target_word": "做法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护河水，两个城市用了同样的做法。", "target_word": "做法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的做法是让全班一起讨论。", "target_word": "做法", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "为达到共同目标而采取的行动或策略", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd295e12-7231-4a6a-a8ef-075f24fccda5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20110, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "做法", "is_correct": true, "explanation": "正确。做法指为实现共同目标而采取的特定行动或策略，读作 zuò fǎ。"}, {"text": "做饭", "is_correct": false, "explanation": "fàn（第四声，带 -n）与 fǎ（第三声）读音相近但不同，做饭指烧菜煮饭。"}, {"text": "作废", "is_correct": false, "explanation": "fèi（第四声）与 fǎ（第三声）韵母不同，作废指失去效力。"}, {"text": "走法", "is_correct": false, "explanation": "zǒu fǎ 与 zuò fǎ 首字韵母和声调都不同，走法指走路或下棋的走的方式。"}], "explanations": {"做法": "正确。做法指为实现共同目标而采取的特定行动或策略，读作 zuò fǎ。", "做饭": "fàn（第四声，带 -n）与 fǎ（第三声）读音相近但不同，做饭指烧菜煮饭。", "作废": "fèi（第四声）与 fǎ（第三声）韵母不同，作废指失去效力。", "走法": "zǒu fǎ 与 zuò fǎ 首字韵母和声调都不同，走法指走路或下棋的走的方式。"}, "sentence_index": null, "correct_answer": "做法"}, "level_3": {"options": [{"text": "做法", "is_correct": true, "explanation": "正确。“这种做法”指让更多人参与并加快创新的行动方式，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不能让更多人参与改进技术，句子语义不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”无法“让更多人参与改进技术”，句子语义不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“这种颜色”不能作主语，与“让更多人参与”搭配不当。"}], "explanations": {"做法": "正确。“这种做法”指让更多人参与并加快创新的行动方式，符合语境。", "石头": "语义：“石头”不能让更多人参与改进技术，句子语义不通。", "空气": "语义：“空气”无法“让更多人参与改进技术”，句子语义不通。", "颜色": "搭配：“这种颜色”不能作主语，与“让更多人参与”搭配不当。"}, "sentence_index": 0, "correct_answer": "做法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校让同学互相帮忙，这张做法很受欢迎。", "explanation": "量词用错。〈张〉用于纸、桌子等平面物，不用于“做法”，应用〈种〉或〈个〉。"}, {"text": "老师用一台做法组织了这次活动。", "explanation": "量词用错。〈台〉用于机器、仪器等，不用于“做法”，应用〈种〉或〈个〉。"}, {"text": "我们用一只做法解决了这个问题。", "explanation": "量词用错。〈只〉用于动物、器物等，不用于“做法”，应用〈种〉或〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做法", "is_correct": true, "explanation": "正确。“这样的做法”指双方合作的行动方式，能让双方满意，符合语境。"}, {"text": "灾难", "is_correct": false, "explanation": "语义：“灾难”是坏事，不能让双方满意，句子语义不通。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：“疾病”不能让双方都满意，句子语义不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“这样的味道”不能作“让双方都满意”的主语，搭配不当。"}], "explanations": {"做法": "正确。“这样的做法”指双方合作的行动方式，能让双方满意，符合语境。", "灾难": "语义：“灾难”是坏事，不能让双方满意，句子语义不通。", "疾病": "语义：“疾病”不能让双方都满意，句子语义不通。", "味道": "搭配：“这样的味道”不能作“让双方都满意”的主语，搭配不当。"}, "sentence_index": 6, "correct_answer": "做法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们用一辆做法完成了这个任务。", "explanation": "量词用错。〈辆〉用于车辆，不用于“做法”，应用〈种〉或〈个〉。"}, {"text": "他用一颗做法赢得了比赛。", "explanation": "量词用错。〈颗〉用于颗粒状或球形的东西，不用于“做法”，应用〈种〉或〈个〉。"}, {"text": "校长用一把做法管理这所学校。", "explanation": "量词用错。〈把〉用于有柄的工具等，不用于“做法”，应用〈种〉或〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家决定采用一台共同的做法。", "corrected_sentence": "大家决定采用一种共同的做法。", "error_description": "“做法”的量词应用“种”或“个”，不能用“台”（“台”用于机器、仪器等）。应说“一种共同的做法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一起想出了一本新的做法。", "corrected_sentence": "他们一起想出了一种新的做法。", "error_description": "“做法”的量词应用“种”或“个”，不能用“本”（“本”用于书等）。应说“一种新的做法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20111, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "专用", "is_correct": true, "explanation": "反义：通用指适用于多种用途，专用指只用于特定用途，两者意义相对。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：漂亮形容外貌，与用途范围无关。"}, {"text": "迅速", "is_correct": false, "explanation": "无关：迅速形容速度，与用途范围无关。"}, {"text": "复杂", "is_correct": false, "explanation": "无关：复杂形容结构或难度，与用途范围无关。"}], "correct_answer": "专用", "explanations": {"专用": "反义：通用指适用于多种用途，专用指只用于特定用途，两者意义相对。", "漂亮": "无关：漂亮形容外貌，与用途范围无关。", "迅速": "无关：迅速形容速度，与用途范围无关。", "复杂": "无关：复杂形容结构或难度，与用途范围无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
