INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20111, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "适用于各种不同任务或用途的", "primary_collocate": null, "pronunciation": "tōng yòng", "ipa": "tʰʊŋ˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "OpenClaw 就是一个开源的通用人工智能代理项目。", "target_word": "通用", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这是一种通用的工具，什么活都能做。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个通用零件可以装在很多机器上。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了一个通用的充电器。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们需要一个通用的软件来处理文件。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个机器人是通用的，可以做很多种工作。", "target_word": "通用", "complexity_tier": "T3", "furigana": "zhè gè jī qì rén shì tōng yòng de, kě yǐ zuò hěn duō zhǒng gōng zuò.", "sentence_source": "generated"}, {"text": "这种接口是通用的，很多手机和电脑都能用。", "target_word": "通用", "complexity_tier": "T3", "furigana": "zhè zhǒng jiē kǒu shì tōng yòng de, hěn duō shǒu jī hé diàn nǎo dōu néng yòng.", "sentence_source": "generated"}, {"text": "这种通用模型不只会写文章，还会翻译。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想做一个通用的平台，让各行各业都能用。", "target_word": "通用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个通用的设计适合不同的用途。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "通用型", "label": "复合"}, {"form": "通用性", "label": "复合"}], "register": "中性", "sense_fingerprint": "通用·适合多种任务或用途、功能不单一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c932acf-f05f-4d8d-ad7f-aaeceee4f32a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通用", "is_correct": true, "explanation": "通用：指适用于多种用途，修饰“人工智能代理项目”，意思是通用型。"}, {"text": "木制", "is_correct": false, "explanation": "语义：木制指由木材做成，不能用来修饰人工智能项目。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻指低温保存，不适用于人工智能代理项目。"}, {"text": "易碎", "is_correct": false, "explanation": "搭配：易碎多用于玻璃、瓷器等物品，不能用来形容人工智能项目。"}], "explanations": {"通用": "通用：指适用于多种用途，修饰“人工智能代理项目”，意思是通用型。", "木制": "语义：木制指由木材做成，不能用来修饰人工智能项目。", "冷冻": "语义：冷冻指低温保存，不适用于人工智能代理项目。", "易碎": "搭配：易碎多用于玻璃、瓷器等物品，不能用来形容人工智能项目。"}, "sentence_index": 0, "correct_answer": "通用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器是通用的，只能用来印刷。", "explanation": "这里应该用〈专用〉。通用指适用于多种用途，只能做一种用途时要说专用。"}, {"text": "这把钥匙是通用的，只能开我家的门。", "explanation": "这里应该用〈专属〉。通用指适用于多种场合，只开一扇门的钥匙要说专属。"}, {"text": "这位运动员是通用的，什么项目都能拿奖牌。", "explanation": "这里应该用〈全能〉。通用指适用于各种用途的物品或方法，形容人的多方面本领要说全能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通用", "is_correct": true, "explanation": "通用：说接口适用于很多手机和电脑，与“都能用”一致。"}, {"text": "定制", "is_correct": false, "explanation": "语义：定制指按特定需求制作，与“很多手机和电脑都能用”相矛盾。"}, {"text": "时尚", "is_correct": false, "explanation": "搭配：时尚多形容外观或款式，不用来说明接口的适用范围。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：柔软形容质地，不能用来说明接口能与很多设备兼容。"}], "explanations": {"通用": "通用：说接口适用于很多手机和电脑，与“都能用”一致。", "定制": "语义：定制指按特定需求制作，与“很多手机和电脑都能用”相矛盾。", "时尚": "搭配：时尚多形容外观或款式，不用来说明接口的适用范围。", "柔软": "搭配：柔软形容质地，不能用来说明接口能与很多设备兼容。"}, "sentence_index": 6, "correct_answer": "通用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套西装是通用的，只适合我一个人穿。", "explanation": "这里应该用〈定制〉。通用指不针对特定对象，只为一个人做的要说定制。"}, {"text": "这个接口是通用的，只有我们公司能用。", "explanation": "这里应该用〈独家〉。通用指各方都能使用，只允许一家使用要说独家。"}, {"text": "这件衣服是通用的，专为我的身材做的。", "explanation": "这里应该用〈量身定做〉。通用指不针对特定对象，专为某人身材制作要说量身定做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个转换头是通用地，各种设备都能接。", "corrected_sentence": "这个转换头是通用的，各种设备都能接。", "error_description": "“通用”作形容词，后面要用“的”，不能用“地”。正确：是通用的；错误：是通用地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套软件不通用，各行各业都能用。", "corrected_sentence": "这套软件很通用，各行各业都能用。", "error_description": "错误：“不通用”与后面的“各行各业都能用”自相矛盾（既说不通用，又说各行各业都能用）；应改为“很通用”，表示适用范围广。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
