INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20113, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家独立自主地处理对内对外事务的最高权力；也泛指对某事物的自主支配权。", "primary_collocate": null, "pronunciation": "zhǔ quán", "ipa": "ʈʂu˨˩˦ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这个国家很重视保护自己的主权。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国都在讨论网络空间的主权。", "target_word": "主权", "complexity_tier": "T3", "furigana": "Gèguó dōu zài tǎolùn wǎngluò kōngjiān de zhǔquán.", "sentence_source": "generated"}, {"text": "国家管理本国数据的权力，就是数据方面的主权。", "target_word": "主权", "complexity_tier": "T3", "furigana": "Guójiā guǎnlǐ běnguó shùjù de quánlì, jiù shì shùjù fāngmiàn de zhǔquán.", "sentence_source": "generated"}, {"text": "国家要独立处理内外事务，就要有主权。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用户应该拥有自己个人信息的主权。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了保护主权，拒绝了这个条件。", "target_word": "主权", "complexity_tier": "T3", "furigana": "Tāmen wèile bǎohù zhǔquán, jùjué le zhège tiáojiàn.", "sentence_source": "generated"}, {"text": "法律规定，我国对领海拥有主权。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国军队进入，侵犯了这个国家的主权。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里说，两国对小岛的主权有争议。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家的主权不能被别人随便拿走。", "target_word": "主权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主权国家", "label": "复合"}, {"form": "数据主权", "label": "复合"}, {"form": "主權", "label": "繁体"}], "register": "正式", "sense_fingerprint": "主权：国家独立处理内外事务的最高权力，也泛指自主支配权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871aef36-6f52-465a-aab9-0f77eb16f723') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20113, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主权", "is_correct": true, "explanation": "正确：“保护自己的主权”指保护国家处理内外事务的最高权力，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是国家需要保护的权力，“保护自己的天气”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：国家没有身高，“保护自己的身高”说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是人的性格特点，“国家保护自己的脾气”说不通。"}], "explanations": {"主权": "正确：“保护自己的主权”指保护国家处理内外事务的最高权力，符合语境。", "天气": "语义：天气不是国家需要保护的权力，“保护自己的天气”说不通。", "身高": "语义：国家没有身高，“保护自己的身高”说不通。", "脾气": "语义：脾气是人的性格特点，“国家保护自己的脾气”说不通。"}, "sentence_index": 0, "correct_answer": "主权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身份是老师，他的主权也是老师。", "explanation": "这里应该用〈职业〉。主权指对事务的自主支配权，不能用来说明一个人的工作。"}, {"text": "今天天气很好，主权也很好。", "explanation": "这里应该用〈状态〉。主权指对事务的支配权，不能用来说事物的好坏状态。"}, {"text": "这个政府是选举产生的主权。", "explanation": "这里应该用〈政权〉。政权指政府掌握的统治体制，主权是对事务的支配权，不能用来指政府。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主权", "is_correct": true, "explanation": "正确：“我国对领海拥有主权”是常见的说法，「主权」符合语境。"}, {"text": "视力", "is_correct": false, "explanation": "语义：领海不能拥有视力，“对领海拥有视力”说不通。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：领海不能拥有宠物，“对领海拥有宠物”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：领海没有体重，体重是人或物的体貌特征，不能用于领海。"}], "explanations": {"主权": "正确：“我国对领海拥有主权”是常见的说法，「主权」符合语境。", "视力": "语义：领海不能拥有视力，“对领海拥有视力”说不通。", "宠物": "语义：领海不能拥有宠物，“对领海拥有宠物”不成立。", "体重": "体貌：领海没有体重，体重是人或物的体貌特征，不能用于领海。"}, "sentence_index": 6, "correct_answer": "主权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的主权是两百页。", "explanation": "这里应该用〈页数〉。主权指国家处理事务的最高权力，书有多少页要说页数。"}, {"text": "这件衣服的主权是一百块。", "explanation": "这里应该用〈价格〉。主权指国家处理事务的最高权力，东西卖多少钱要说价格。"}, {"text": "他今天主权很好，一直在笑。", "explanation": "这里应该用〈心情〉。主权指国家处理事务的最高权力，不能用来说人高兴不高兴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "各国都在积极维护网络空间地主权。", "corrected_sentence": "各国都在积极维护网络空间的主权。", "error_description": "助词错误：修饰名词“主权”应用“的”，不能用“地”；“网络空间地主权”应为“网络空间的主权”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要坚决保护了个人信息的主权。", "corrected_sentence": "我们要坚决保护个人信息的主权。", "error_description": "体标错误：“要……”表示将来，动词后不能加“了”；应说“我们要坚决保护个人信息的主权”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
