INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20117, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事先设定好、默认遵循的规则或运作方式", "primary_collocate": null, "pronunciation": "yù shè", "ipa": "y˥˩ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "用户不再是被动接受预设行为逻辑的终端使用者，而成为代理演化方向的主导者，其价值观、偏好与伦理准则可被持续嵌入代理的认知循环。", "target_word": "预设", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个软件的预设是自动保存文件。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以改掉手机里的预设。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏的预设难度对新手来说太高了。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打印机的预设是双面打印，可以省纸。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不喜欢预设的话，可以自己调整。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站的预设语言是中文。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新电脑的预设很简单，一开机就能用。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相机的预设有好几种拍照模式。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的预设铃声我不太喜欢，就换了。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预设值", "label": "复合"}, {"form": "预设行为", "label": "复合"}, {"form": "預設", "label": "繁体"}], "register": "书面", "sense_fingerprint": "系统或软件默认遵循的既定规则、运作方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f917e74-ef1d-49a8-a590-87211bbc2e31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20117, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预设", "is_correct": true, "explanation": "正确。预设 yù shè，指系统默认遵循的既定规则或运作方式。"}, {"text": "预热", "is_correct": false, "explanation": "rè（第四声）与 shè（第四声）声母不同（r 与 sh），意思是预先加热。"}, {"text": "预示", "is_correct": false, "explanation": "shì（第四声）与 shè（第四声）韵母不同（i 与 ê），意思是预先显示迹象。"}, {"text": "预测", "is_correct": false, "explanation": "cè（第四声）与 shè（第四声）声母不同（c 与 sh），意思是预先推断。"}], "explanations": {"预设": "正确。预设 yù shè，指系统默认遵循的既定规则或运作方式。", "预热": "rè（第四声）与 shè（第四声）声母不同（r 与 sh），意思是预先加热。", "预示": "shì（第四声）与 shè（第四声）韵母不同（i 与 ê），意思是预先显示迹象。", "预测": "cè（第四声）与 shè（第四声）声母不同（c 与 sh），意思是预先推断。"}, "sentence_index": null, "correct_answer": "预设"}, "level_3": {"options": [{"text": "预设", "is_correct": true, "explanation": "正确。此处指代理系统默认遵循的既定规则。"}, {"text": "气候", "is_correct": false, "explanation": "搭配：“气候”指自然环境，不能修饰“行为逻辑”，句意不通。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：“饮食”指吃喝，与代理系统的“行为逻辑”无关，句意不通。"}, {"text": "菜单", "is_correct": false, "explanation": "搭配：“菜单”不能用来修饰“行为逻辑”，这里应指规则或运作方式。"}], "explanations": {"预设": "正确。此处指代理系统默认遵循的既定规则。", "气候": "搭配：“气候”指自然环境，不能修饰“行为逻辑”，句意不通。", "饮食": "语义：“饮食”指吃喝，与代理系统的“行为逻辑”无关，句意不通。", "菜单": "搭配：“菜单”不能用来修饰“行为逻辑”，这里应指规则或运作方式。"}, "sentence_index": 0, "correct_answer": "预设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的预设很紧。", "explanation": "这里应该用〈预算〉。预设指默认的设置或运作方式，不指费用的安排，预算才用于此。"}, {"text": "这个电视台的天气预设很准。", "explanation": "这里应该用〈预报〉。预设指默认的设置，不指对天气的预报，预报才用于此。"}, {"text": "这本书的预设很火。", "explanation": "这里应该用〈预售〉。预设指默认的设置，不指商品的提前销售，预售才用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '527a28a0-59a1-4cd4-9f8a-164ddafb1fbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20117, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "预设", "is_correct": true, "explanation": "正确。预设 yù shè，指系统默认遵循的既定规则或运作方式。"}, {"text": "遇事", "is_correct": false, "explanation": "shì 与 shè 韵母不同（i 与 ê），意思是遇到事情。"}, {"text": "预售", "is_correct": false, "explanation": "shòu（第四声）与 shè（第四声）韵母不同（ou 与 ê），意思是提前销售。"}, {"text": "预测", "is_correct": false, "explanation": "cè（第四声）与 shè（第四声）声母不同（c 与 sh），意思是预先推断。"}], "explanations": {"预设": "正确。预设 yù shè，指系统默认遵循的既定规则或运作方式。", "遇事": "shì 与 shè 韵母不同（i 与 ê），意思是遇到事情。", "预售": "shòu（第四声）与 shè（第四声）韵母不同（ou 与 ê），意思是提前销售。", "预测": "cè（第四声）与 shè（第四声）声母不同（c 与 sh），意思是预先推断。"}, "sentence_index": null, "correct_answer": "预设"}, "level_3": {"options": [{"text": "预设", "is_correct": true, "explanation": "正确。此处指网站默认使用的语言。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体是文字的样式，与网站默认使用哪种语言无关。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器与网站使用的语言无关，句意不通。"}, {"text": "气候", "is_correct": false, "explanation": "搭配：“气候”不能与“语言”组合，说语言时不用“气候”。"}], "explanations": {"预设": "正确。此处指网站默认使用的语言。", "字体": "语义：字体是文字的样式，与网站默认使用哪种语言无关。", "乐器": "语义：乐器与网站使用的语言无关，句意不通。", "气候": "搭配：“气候”不能与“语言”组合，说语言时不用“气候”。"}, "sentence_index": 6, "correct_answer": "预设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生要提前预设课文。", "explanation": "这里应该用〈预习〉。预设指事先设定的做法或参数，不用于学习课文。"}, {"text": "我已经预设了周五的美容院。", "explanation": "这里应该用〈预约〉。预设不用于为场所或时间做预订，预约才用于此。"}, {"text": "这部电影的预设很精彩。", "explanation": "这里应该用〈预告〉。预设指默认的设置或运作方式，不指电影提前放出的片段，预告才用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '527a28a0-59a1-4cd4-9f8a-164ddafb1fbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把预设很好用，不用改。", "corrected_sentence": "这个预设很好用，不用改。", "error_description": "错误在于量词。“预设”作名词时用“个”而非“把”，“把”多用于有柄的器具。应说“这个预设”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '527a28a0-59a1-4cd4-9f8a-164ddafb1fbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑的预设中文。", "corrected_sentence": "这台电脑的预设是中文。", "error_description": "错误在于缺少系动词“是”。“……的预设”作主语后，句子还需要谓语，应说“这台电脑的预设是中文”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '527a28a0-59a1-4cd4-9f8a-164ddafb1fbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
