INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20118, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "网络中供用户直接使用的设备。", "primary_collocate": null, "pronunciation": "zhōng duān", "ipa": "ʈʂʊŋ˥ twan˥", "syllable_count": 2, "sentences": [{"text": "用户不再是被动接受预设行为逻辑的终端使用者，而成为代理演化方向的主导者，其价值观、偏好与伦理准则可被持续嵌入代理的认知循环。", "target_word": "终端", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种终端可以在家里上网。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机是最常见的终端。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一台新终端。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用户的终端要先连上网络。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个终端能看视频，也能打电话。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用学习终端做作业。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的终端可以买票。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的终端没电了。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给每个人发了一个终端。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "终端机", "label": "复合"}], "register": "中性", "sense_fingerprint": "网络中用户直接使用的设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8eb6ea89-b4e2-487f-9034-a8829d8e7345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20118, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气使用者”不成立，“使用者”指使用设备或服务的人。"}, {"text": "终端", "is_correct": true, "explanation": "终端指供用户直接使用的设备，“终端使用者”指使用这类设备的人。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能说“桌子使用者”。"}, {"text": "饮食", "is_correct": false, "explanation": "搭配：“使用者”不与“饮食”搭配，不说“饮食使用者”。"}], "explanations": {"天气": "语义：“天气使用者”不成立，“使用者”指使用设备或服务的人。", "终端": "终端指供用户直接使用的设备，“终端使用者”指使用这类设备的人。", "桌子": "语义：桌子是家具，不能说“桌子使用者”。", "饮食": "搭配：“使用者”不与“饮食”搭配，不说“饮食使用者”。"}, "sentence_index": 0, "correct_answer": "终端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家客厅里摆着一张终端。", "explanation": "这里应该用〈台〉。“张”用于桌子、床等平展的物件，终端是机器，应说“一台终端”。"}, {"text": "他买了一本新终端。", "explanation": "这里应该用〈台〉。“本”用于书籍、册子，终端是机器，量词用“台”。"}, {"text": "他买了一把新终端。", "explanation": "这里应该用〈台〉。“把”用于有柄或可握持的物件，终端是机器，应说“一台终端”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不能用来学习，与“做作业”也不搭。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“学习”不修饰食品，不说“学习饼干”。"}, {"text": "终端", "is_correct": true, "explanation": "终端指供用户直接使用的电子设备，这里是孩子学习时用来做作业的工具。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不能用来做作业，句意不通。"}], "explanations": {"石头": "语义：石头不能用来学习，与“做作业”也不搭。", "饼干": "搭配：“学习”不修饰食品，不说“学习饼干”。", "终端": "终端指供用户直接使用的电子设备，这里是孩子学习时用来做作业的工具。", "水": "语义：水不能用来做作业，句意不通。"}, "sentence_index": 6, "correct_answer": "终端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台终端负责托管公司的网站。", "explanation": "这里应该用〈服务器〉。终端是供用户直接使用的设备，不负责托管网站。"}, {"text": "这个终端负责覆盖整个小区的信号。", "explanation": "这里应该用〈基站〉。终端是用户端的设备，不负责覆盖信号。"}, {"text": "这台终端负责为整个城市供水。", "explanation": "这里应该用〈水厂〉。终端是用户直接使用的设备，不负责为城市供水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校给每位老师配了一条终端。", "corrected_sentence": "学校给每位老师配了一台终端。", "error_description": "量词错误：“终端”作设备用“台”，“条”用于线状长物，这里应说“配了一台终端”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在图书馆的终端下可以查借书记录。", "corrected_sentence": "在图书馆的终端上可以查借书记录。", "error_description": "方位词错误：“终端”后的方位词用“上”，“下”表示位于下方，不能用于此处，应说“终端上”。错误形式：终端下；正确形式：终端上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
