INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20119, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据反馈或情况变化对系统或计划进行优化", "primary_collocate": null, "pronunciation": "tiáo zhěng", "ipa": "tʰiɑʊ̯˧˥ ʈʂɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "根据大家的意见，公司调整了工作计划。", "target_word": "调整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷了，我们要调整出发时间。", "target_word": "调整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师根据考试结果调整教学方法。", "target_word": "调整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "系统有问题，工程师正在调整设置。", "target_word": "调整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市场变了，公司要调整价格。", "target_word": "调整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看了反馈，马上调整了方案。", "target_word": "调整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以根据情况调整学习计划。", "target_word": "调整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛中，教练及时调整了队伍的打法。", "target_word": "调整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用户不喜欢这个功能，我们只好调整设计。", "target_word": "调整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把预算重新调整了一次。", "target_word": "调整", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调整了", "label": "完成体"}, {"form": "调整过", "label": "经历体"}, {"form": "调整调整", "label": "重叠"}], "register": "中性", "sense_fingerprint": "根据反馈或形势变化修改并优化计划、系统、方案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c928e1f6-5741-4790-be78-40c893415c14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20119, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "调整", "is_correct": true, "explanation": "调整：根据意见对已有计划做修改，与“根据大家的意见”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只能搭配食物，不能用于“工作计划”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场地或物品，计划不能被打扫。"}, {"text": "微笑", "is_correct": false, "explanation": "配价：“微笑”是不及物动词，不能带“工作计划”作宾语。"}], "explanations": {"调整": "调整：根据意见对已有计划做修改，与“根据大家的意见”相符。", "吃": "搭配：“吃”只能搭配食物，不能用于“工作计划”。", "打扫": "搭配：“打扫”的对象是场地或物品，计划不能被打扫。", "微笑": "配价：“微笑”是不及物动词，不能带“工作计划”作宾语。"}, "sentence_index": 0, "correct_answer": "调整"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房调整了一锅米饭，我们马上吃饭。", "explanation": "这里应该用〈煮〉。煮指用水加热把食物做熟；调整表示根据情况修改、优化计划或系统，不能表示做饭。"}, {"text": "我昨天把这封信调整给了远方的朋友。", "explanation": "这里应该用〈寄〉。寄指通过邮局送出信件；调整表示修改、优化计划或系统，不能表示寄送。"}, {"text": "工人把那块木板调整成了两半。", "explanation": "这里应该用〈切〉。切指把东西分开，调整表示使已有之物更合适，不能表示切开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20119, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调整", "is_correct": true, "explanation": "调整：“根据情况”与对学习计划做修改相符，句子合理。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能用于“学习计划”。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”的对象是花果等植物，不能用于计划。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与“根据情况”进行合理安排的意思不符。"}], "explanations": {"调整": "调整：“根据情况”与对学习计划做修改相符，句子合理。", "唱": "搭配：“唱”的对象是歌曲，不能用于“学习计划”。", "摘": "搭配：“摘”的对象是花果等植物，不能用于计划。", "讨厌": "语义：“讨厌”表示厌恶，与“根据情况”进行合理安排的意思不符。"}, "sentence_index": 6, "correct_answer": "调整"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师调整了那个迟到的学生。", "explanation": "这里应该用〈批评〉。批评指指出错误，调整只用于事物或计划，不用于指出人的错误。"}, {"text": "工人调整了那台脏机器，它现在很干净。", "explanation": "这里应该用〈清洗〉。清洗指用水或清洁剂去除污物，调整表示使已有之物更合适，不能表示清洁。"}, {"text": "工人调整了那座旧仓库，后来把它推倒了。", "explanation": "这里应该用〈拆除〉。拆除指拆掉建筑或设施，调整不能表示拆掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把计划调整在好了。", "corrected_sentence": "我们把计划调整好了。", "error_description": "补语位置错误：“调整”后直接接补语“好”，表示调整完成。多出的“在”插入了动词与补语之间，应去掉，说“调整好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20119, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校重新调整了一只课表。", "corrected_sentence": "学校重新调整了一张课表。", "error_description": "量词错误：“课表”是纸片，应用“张”，“只”是动物的量词，不能修饰课表。应说“调整了一张课表”，不能说“调整了一只课表”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
