INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "记录科学研究成果的书籍、论文等资料", "primary_collocate": null, "pronunciation": "wén xiàn", "ipa": "wən˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "老师要我们先梳理跨学科文献，再动笔写论文。", "target_word": "文献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写论文以前，我要先读很多文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文献介绍了新的研究方法。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在图书馆查找相关文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们把这个课题的文献按年份整理好。", "target_word": "文献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究生每周都要看几篇英文文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份文献记录了实验的全部结果。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用了三个月读完这些医学文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "论文后面要列出所有引用的文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个领域的文献很多，我读不完。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一篇文献", "label": "量词"}, {"form": "一份文献", "label": "量词"}, {"form": "参考文献", "label": "复合"}, {"form": "文献综述", "label": "复合"}, {"form": "文獻", "label": "繁体"}], "register": "书面", "sense_fingerprint": "记录科研成果的书籍、论文等学术资料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c928e1f6-5741-4790-be78-40c893415c14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文献", "is_correct": true, "explanation": "正确：“文献”指科研成果的资料，与“梳理跨学科”的语境相合。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡不是可以梳理的学术资料，无法用于科研梳理。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“梳理”用于资料、思路、问题，不与“天气”搭配。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温不是跨学科研究的对象，句中需要的是知识材料。"}], "explanations": {"文献": "正确：“文献”指科研成果的资料，与“梳理跨学科”的语境相合。", "咖啡": "语义：咖啡不是可以梳理的学术资料，无法用于科研梳理。", "天气": "搭配：“梳理”用于资料、思路、问题，不与“天气”搭配。", "体温": "语义：体温不是跨学科研究的对象，句中需要的是知识材料。"}, "sentence_index": 0, "correct_answer": "文献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天给这篇文献充了电，准备交给导师。", "explanation": "这里应该用〈手机〉。文献是文字资料，不能充电；需要充电的是手机等电子设备。"}, {"text": "请在表格里填写你的个人文献。", "explanation": "这里应该用〈资料〉。填写个人信息要说“个人资料”，文献专指学术或历史上的文字材料。"}, {"text": "请经理在这份文献上签字，然后交给财务。", "explanation": "这里应该用〈文件〉。需要签字的是公文或合同；文献指学术或历史文字资料，不用来签字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文献", "is_correct": true, "explanation": "正确：“文献”指记录实验成果的资料，与“记录了实验的全部结果”相合。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不能记录实验结果，句中的主语应是资料。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟只用来报时，不记录实验数据。"}, {"text": "影子", "is_correct": false, "explanation": "搭配：“记录”不与“影子”搭配，影子不是可以被记录结果的载体。"}], "explanations": {"文献": "正确：“文献”指记录实验成果的资料，与“记录了实验的全部结果”相合。", "面包": "语义：面包不能记录实验结果，句中的主语应是资料。", "闹钟": "语义：闹钟只用来报时，不记录实验数据。", "影子": "搭配：“记录”不与“影子”搭配，影子不是可以被记录结果的载体。"}, "sentence_index": 6, "correct_answer": "文献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本文献的情节很吸引人。", "explanation": "这里应该用〈小说〉。文献是学术资料，没有情节；形容情节吸引人要用〈小说〉。"}, {"text": "这篇文献讲了一个小老鼠冒险的故事，孩子们都爱听。", "explanation": "这里应该用〈童话〉。文献是学术或历史资料，不讲虚构的小老鼠冒险；讲给孩子听的虚构故事要用〈童话〉。"}, {"text": "这篇文献的幽默让人发笑。", "explanation": "这里应该用〈文章〉。文献重在资料价值；形容幽默、令人发笑的要用〈文章〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我读了三只文献。", "corrected_sentence": "我读了三篇文献。", "error_description": "量词错误：“文献”应搭配“篇”，不能用“只”（“只”用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天读了完这份文献。", "corrected_sentence": "我昨天读完了这份文献。", "error_description": "补语位置错误：“读完”是动补结构，“了”应放在“完”之后，应说“读完了这份文献”，不说“读了完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20121, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "资本", "is_correct": false, "explanation": "无关：资本指用于生产经营的钱或财产，与趋同无关。"}, {"text": "网络", "is_correct": false, "explanation": "无关：网络指相互连接的系统，与趋同没有反义关系。"}, {"text": "节奏", "is_correct": false, "explanation": "无关：节奏指有规律的快慢变化，与趋同无关。"}, {"text": "趋异", "is_correct": true, "explanation": "反义：趋异指事物朝不同方向发展，与趋同相对。"}], "correct_answer": "趋异", "explanations": {"资本": "无关：资本指用于生产经营的钱或财产，与趋同无关。", "网络": "无关：网络指相互连接的系统，与趋同没有反义关系。", "节奏": "无关：节奏指有规律的快慢变化，与趋同无关。", "趋异": "反义：趋异指事物朝不同方向发展，与趋同相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20121, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "预算", "is_correct": false, "explanation": "无关：预算指对收支的计划安排，与趋同无关。"}, {"text": "设施", "is_correct": false, "explanation": "无关：设施指为某种目的设置的建筑或装备，与趋同无关。"}, {"text": "分工", "is_correct": false, "explanation": "无关：分工指把任务分给不同的人或部门，与趋同没有反义关系。"}, {"text": "趋异", "is_correct": true, "explanation": "反义：趋异指事物朝不同方向发展，与趋同相对。"}], "correct_answer": "趋异", "explanations": {"预算": "无关：预算指对收支的计划安排，与趋同无关。", "设施": "无关：设施指为某种目的设置的建筑或装备，与趋同无关。", "分工": "无关：分工指把任务分给不同的人或部门，与趋同没有反义关系。", "趋异": "反义：趋异指事物朝不同方向发展，与趋同相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20121, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "多个个体的行为因相似目标而变得越来越一致", "primary_collocate": null, "pronunciation": "qū tóng", "ipa": "tɕʰy˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "更严峻的是，若大量代理基于相似优化目标自发演化，可能催生群体性的行为趋同，进而形成“分布式认知霸权”——表面上去中心化的系统，实质上演变为隐蔽的价值导向网络。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "投资者追逐同一个目标，行为渐渐趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想考高分，学习方法越来越趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了抢占市场，各家商店的促销行为趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目标相似使不同公司的决策出现趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多司机为了躲开堵车，行为渐渐趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同样想赢得比赛，几支球队的打法趋同了。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用户的购买行为因共同的需求而趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了得到更多点击，作者们的写法趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "求职者目标一致，简历的写法也趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "趨同", "label": "繁体"}, {"form": "趋同化", "label": "派生"}, {"form": "趋同性", "label": "派生"}], "register": "书面", "sense_fingerprint": "趋同|多个个体因相似目标而行为越来越一致", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3cdbb2-6def-43dc-9a20-b31c9024b160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20121, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "趋同", "is_correct": true, "explanation": "正确。“群体性的行为趋同”指许多个体因相似目标而行为一致，正好引出后文的霸权。"}, {"text": "个性", "is_correct": false, "explanation": "语义：个性指个人的独特之处，与“群体性”的一致行为相反。"}, {"text": "乐趣", "is_correct": false, "explanation": "语义：乐趣是快乐的感受，不是可以“催生”的行为特征。"}, {"text": "独立", "is_correct": false, "explanation": "搭配：“行为独立”与“群体性”相矛盾，“独立”不能与“群体性的行为”搭配。"}], "explanations": {"趋同": "正确。“群体性的行为趋同”指许多个体因相似目标而行为一致，正好引出后文的霸权。", "个性": "语义：个性指个人的独特之处，与“群体性”的一致行为相反。", "乐趣": "语义：乐趣是快乐的感受，不是可以“催生”的行为特征。", "独立": "搭配：“行为独立”与“群体性”相矛盾，“独立”不能与“群体性的行为”搭配。"}, "sentence_index": 0, "correct_answer": "趋同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "几家商店的促销活动趋同进行，顾客很方便。", "explanation": "这里应该用〈同时〉。同时指在同一时间发生；趋同强调不同个体逐渐靠拢，不能描述同时进行的活动。"}, {"text": "两家公司的股价趋同上涨，投资者很高兴。", "explanation": "这里应该用〈同步〉。同步指同时发生；趋同强调逐渐靠拢的过程，不能描述“上涨”这种同时的动作。"}, {"text": "他的购买习惯越来越趋同。", "explanation": "这里应该用〈改变〉。趋同需要多个个体因相似目标而靠拢，只说一个人的习惯，不能用趋同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "趋同", "is_correct": true, "explanation": "正确。几支球队目标一致，打法向同一方向靠拢，所以说打法趋同了。"}, {"text": "上涨", "is_correct": false, "explanation": "语义：上涨用于价格、数量，不用于打法，与“同样想赢得比赛”也不相符。"}, {"text": "降价", "is_correct": false, "explanation": "搭配：“降价”用于商品，不用于打法。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或物的重量，打法没有体重，句子不通。"}], "explanations": {"趋同": "正确。几支球队目标一致，打法向同一方向靠拢，所以说打法趋同了。", "上涨": "语义：上涨用于价格、数量，不用于打法，与“同样想赢得比赛”也不相符。", "降价": "搭配：“降价”用于商品，不用于打法。", "体重": "语义：体重指人或物的重量，打法没有体重，句子不通。"}, "sentence_index": 6, "correct_answer": "趋同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两篇作文的内容大段趋同，老师一眼就看出来了。", "explanation": "这里应该用〈雷同〉。雷同指内容几乎一样，常带有抄袭的意味；趋同强调不同事物逐渐靠拢的过程。"}, {"text": "两家公司合并后，两个部门终于趋同在一起了。", "explanation": "这里应该用〈融合〉。融合指合为一体；趋同只指朝相同方向靠拢，不能说“在一起”。"}, {"text": "这两把钥匙是同一台机器做的，形状完全趋同。", "explanation": "这里应该用〈相同〉。相同指本来就一样；趋同指不同个体在目标影响下逐渐变得一致，不能形容本来就一模一样的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家店的促销行为趋同很得明显，顾客很难分辨。", "corrected_sentence": "两家店的促销行为趋同得很明显，顾客很难分辨。", "error_description": "补语结构错：“得”应紧跟在“趋同”后，正确说法是“趋同得很明显”，不能说“趋同很得明显”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20121, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些学生的作答方式出现了一只令人惊讶的趋同。", "corrected_sentence": "这些学生的作答方式出现了一种令人惊讶的趋同。", "error_description": "量词用错：“只”不能修饰趋同，应改为“种”，即“一种令人惊讶的趋同”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
