INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20122, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "设备或程序之间交换信息的统一规则", "primary_collocate": null, "pronunciation": "xié yì", "ipa": "ɕjɛ˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "两台电脑要用同一个协议交换信息。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个协议规定了数据怎么传送。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网页用的是一种常见的协议。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机和路由器必须使用相同的协议。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协议不一样，设备就连不上。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师在检查这个协议有没有错误。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发邮件时，电脑会按协议传送信息。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的协议让网速变快了。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个协议是为了保护传输的数据。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的设备用着不同的协议。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "网络协议", "label": "复合"}, {"form": "協議", "label": "繁体"}], "register": "书面", "sense_fingerprint": "计算机网络中设备或程序交换数据所遵循的统一规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1be5a6e3-5db9-4be7-88db-c287895b77cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20122, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "协议", "is_correct": true, "explanation": "正确：「协议」xié yì，指设备或程序之间交换信息的统一规则。"}, {"text": "谢意", "is_correct": false, "explanation": "xiè（第四声）与 xié（第二声）声调不同，意思是感谢之意。"}, {"text": "协力", "is_correct": false, "explanation": "lì 与 yì 声母不同（l 与零声母），都是第四声，意思是齐心合力。"}, {"text": "鞋印", "is_correct": false, "explanation": "鞋印（xié yìn）第一个音节与协议相同，第二个音节多了鼻音韵尾 -n（yìn 与 yì），意思是鞋子踩出的印子。"}], "explanations": {"协议": "正确：「协议」xié yì，指设备或程序之间交换信息的统一规则。", "谢意": "xiè（第四声）与 xié（第二声）声调不同，意思是感谢之意。", "协力": "lì 与 yì 声母不同（l 与零声母），都是第四声，意思是齐心合力。", "鞋印": "鞋印（xié yìn）第一个音节与协议相同，第二个音节多了鼻音韵尾 -n（yìn 与 yì），意思是鞋子踩出的印子。"}, "sentence_index": null, "correct_answer": "协议"}, "level_3": {"options": [{"text": "协议", "is_correct": true, "explanation": "正确：「同一个协议」指设备之间共同遵守的通信规则，与「交换信息」搭配。"}, {"text": "字体", "is_correct": false, "explanation": "搭配：「字体」只描述文字样式，不能用来交换信息。"}, {"text": "饭盒", "is_correct": false, "explanation": "语义：饭盒是盛饭的容器，与计算机通信无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是通信规则或传输方式，无法用来交换信息。"}], "explanations": {"协议": "正确：「同一个协议」指设备之间共同遵守的通信规则，与「交换信息」搭配。", "字体": "搭配：「字体」只描述文字样式，不能用来交换信息。", "饭盒": "语义：饭盒是盛饭的容器，与计算机通信无关。", "颜色": "语义：颜色不是通信规则或传输方式，无法用来交换信息。"}, "sentence_index": 0, "correct_answer": "协议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的协议很好听。", "explanation": "这里把「协议」当作声音、旋律来用。本词条指设备或程序之间交换信息的统一规则，不能用来形容歌曲好听。"}, {"text": "他用这个协议打开了家里的门锁。", "explanation": "这里应该用〈钥匙〉。协议是设备或程序之间交换信息的规则，不能用来开门锁。"}, {"text": "妈妈用协议做了一锅汤。", "explanation": "这里把「协议」当作食材来用。本词条指设备或程序之间交换信息的统一规则，协议不能用来做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20122, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "协议", "is_correct": true, "explanation": "正确：「协议」xié yì，指设备或程序之间交换信息的统一规则。"}, {"text": "谢意", "is_correct": false, "explanation": "谢意（xiè yì）的第一个音节是第四声，与 xié（第二声）声调不同，意思是感谢之意。"}, {"text": "学艺", "is_correct": false, "explanation": "xué（第二声）与 xié（第二声）韵母不同（-ue 与 -ie），意思是学习技艺。"}, {"text": "写意", "is_correct": false, "explanation": "写意（xiě yì）的声母和韵母都与协议（xié yì）相同，只有第一个音节声调不同（第三声与第二声），意思是描绘意境、不拘形似。"}], "explanations": {"协议": "正确：「协议」xié yì，指设备或程序之间交换信息的统一规则。", "谢意": "谢意（xiè yì）的第一个音节是第四声，与 xié（第二声）声调不同，意思是感谢之意。", "学艺": "xué（第二声）与 xié（第二声）韵母不同（-ue 与 -ie），意思是学习技艺。", "写意": "写意（xiě yì）的声母和韵母都与协议（xié yì）相同，只有第一个音节声调不同（第三声与第二声），意思是描绘意境、不拘形似。"}, "sentence_index": null, "correct_answer": "协议"}, "level_3": {"options": [{"text": "协议", "is_correct": true, "explanation": "正确：「按协议传送信息」，即按照通信规则传送。"}, {"text": "拼音", "is_correct": false, "explanation": "语义：拼音是汉字的注音，不是传送方式。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不能作为传送信息的依据。"}, {"text": "字号", "is_correct": false, "explanation": "搭配：「按字号」用于排版，不用于传送信息。"}], "explanations": {"协议": "正确：「按协议传送信息」，即按照通信规则传送。", "拼音": "语义：拼音是汉字的注音，不是传送方式。", "温度": "语义：温度不能作为传送信息的依据。", "字号": "搭配：「按字号」用于排版，不用于传送信息。"}, "sentence_index": 6, "correct_answer": "协议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这个协议戴在了头上。", "explanation": "这里把「协议」当作可以佩戴的物品来用。本词条指设备或程序之间交换信息的统一规则，协议是抽象的规则，不能戴在头上。"}, {"text": "他想用这个协议来烤面包。", "explanation": "这里应该用〈烤箱〉。协议是设备或程序之间交换信息的规则，不能用来烤东西。"}, {"text": "他把这个协议种在了院子里。", "explanation": "这里把「协议」当作植物或种子来用。本词条指设备或程序之间交换信息的统一规则，协议不能种在土里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两台服务器通过同一台协议交换数据。", "corrected_sentence": "两台服务器通过同一种协议交换数据。", "error_description": "错误形式：同一台协议。正确形式：同一种协议。「台」用于机器设备，协议是规则，应用「种」或「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块新协议让登录更安全了。", "corrected_sentence": "这个新协议让登录更安全了。", "error_description": "错误形式：这块新协议。正确形式：这个新协议。「块」用于成块的物体，协议是抽象的规则，应用「个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
