INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20124, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "需要人亲自完成的工作或劳动力", "primary_collocate": null, "pronunciation": "rén gōng", "ipa": "ʐən³⁵ kʊŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "现在很多工作由机器完成，不需要那么多人工了。", "target_word": "人工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作要人工完成，不能用机器。", "target_word": "人工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的人工很贵。", "target_word": "人工", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "修房子的人工比材料还贵。", "target_word": "人工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打电话时按零，可以转人工。", "target_word": "人工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机器不能做，只能靠人工。", "target_word": "人工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些水果是人工采摘的。", "target_word": "人工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想减少人工，多用机器。", "target_word": "人工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地方的人工越来越贵了。", "target_word": "人工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种茶要用人工一片一片地摘。", "target_word": "人工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人工费", "label": "复合"}, {"form": "人工客服", "label": "复合"}], "register": "中性", "sense_fingerprint": "由人亲自完成的工作，或所需的劳动力、人力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '346c9218-cb43-4e91-8a90-710077c45e12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人工", "is_correct": true, "explanation": "人工：人亲自完成的劳动，与“由机器完成”形成对比"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”与工作由谁完成无关，句意不通"}, {"text": "天气", "is_correct": false, "explanation": "语义：机器做工作与“天气”无关，句意不通"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与劳动力无关，句意不通"}], "explanations": {"人工": "人工：人亲自完成的劳动，与“由机器完成”形成对比", "石头": "语义：“石头”与工作由谁完成无关，句意不通", "天气": "语义：机器做工作与“天气”无关，句意不通", "颜色": "语义：“颜色”与劳动力无关，句意不通"}, "sentence_index": 0, "correct_answer": "人工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "修房子的一只人工比材料还贵。", "explanation": "这里“人工”指劳动力，是抽象的不可数概念，不能说“一只人工”；应直接说“修房子的人工”"}, {"text": "这家公司很重视人工资源的培养。", "explanation": "这里应该用〈人力〉。“人工”指人亲自完成的劳动，“人力资源”才是固定说法"}, {"text": "这家公司一直在培养优秀的人工。", "explanation": "这里应该用〈人才〉。“人工”指劳动或劳力，不指有特殊才能的人；“优秀的人才”才是正确说法"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人工", "is_correct": true, "explanation": "人工：由人亲自完成，符合“采摘”的施事"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不能施行“采摘”的动作，句意荒唐"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能采摘水果，句意荒唐"}, {"text": "风", "is_correct": false, "explanation": "搭配：风不能施行“采摘”，动作的施事须是人或机器"}], "explanations": {"人工": "人工：由人亲自完成，符合“采摘”的施事", "花朵": "语义：花朵不能施行“采摘”的动作，句意荒唐", "小猫": "语义：小猫不能采摘水果，句意荒唐", "风": "搭配：风不能施行“采摘”，动作的施事须是人或机器"}, "sentence_index": 6, "correct_answer": "人工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的人工都很年轻。", "explanation": "这里应该用〈雇员〉。人工指劳动力，不指具体的人，不能说“人工都很年轻”"}, {"text": "这家店雇了三台人工。", "explanation": "量词误用：〈台〉用于机器设备，不能计量“人工”；这里应该说“雇了三个人”"}, {"text": "这个班级的人工都很认真地学习。", "explanation": "这里“人工”指劳动力，不指学生；指学习的人应说〈学生〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次装修要花很多只人工。", "corrected_sentence": "这次装修要花很多人工。", "error_description": "错误：加了量词“只”。“人工”是抽象名词，前面不能加个体量词，应直接说“很多人工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个工地上的人工们很多。", "corrected_sentence": "这个工地上的人工很多。", "error_description": "错误：加了复数标记“们”。“人工”表示劳动力，是抽象名词，不能加“们”，应说“人工很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
