INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20125, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "用在动词或形容词后，表示动作或状态开始并继续。", "primary_collocate": null, "pronunciation": "qǐ lai", "ipa": "t͡ɕʰi²¹⁴ lai⁰", "syllable_count": 2, "sentences": [{"text": "他一激动，声音就大起来了。", "target_word": "起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天一黑，孩子们就唱起来了。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到这个笑话，大家都笑起来。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨突然下起来了。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一看到我，就跑起来。", "target_word": "起来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气慢慢热起来了。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一下雨，她就哭起来了。", "target_word": "起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们说着说着，就吵起来了。", "target_word": "起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话一响，他马上忙起来。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，草都绿起来了。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用在动词或形容词后，表示动作或状态开始并继续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '346c9218-cb43-4e91-8a90-710077c45e12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20125, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起来", "is_correct": true, "explanation": "起来：用在形容词后，表示状态开始并继续，符合“声音就大起来”的语境。"}, {"text": "出来", "is_correct": false, "explanation": "搭配：“大出来”不成立，“出来”表示由内向外，不能表示声音变大的开始。"}, {"text": "回来", "is_correct": false, "explanation": "语义：“回来”表示返回原处，与“声音变大”的变化无关。"}, {"text": "上来", "is_correct": false, "explanation": "搭配：“大上来”不成立，“上来”表示向上或朝说话人移动，不能表示状态的变化。"}], "explanations": {"起来": "起来：用在形容词后，表示状态开始并继续，符合“声音就大起来”的语境。", "出来": "搭配：“大出来”不成立，“出来”表示由内向外，不能表示声音变大的开始。", "回来": "语义：“回来”表示返回原处，与“声音变大”的变化无关。", "上来": "搭配：“大上来”不成立，“上来”表示向上或朝说话人移动，不能表示状态的变化。"}, "sentence_index": 0, "correct_answer": "起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机器突然停起来了。", "explanation": "这里应该用〈下来〉。“起来”强调动作或变化开始，表示中止要用“下来”，“停起来”不成立。"}, {"text": "灯一关，教室里就静起来了。", "explanation": "这里应该用〈下来〉。表示从动到静、程度减弱的变化，常用“静下来”；“起来”多用于开始或增强。"}, {"text": "他说到一半，话就断起来了。", "explanation": "这里应该用〈下来〉。表示中断要用“断下来”，“起来”指开始，不能用于中断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20125, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起来", "is_correct": true, "explanation": "起来：用在动词后，表示“哭”这个动作开始并持续，符合“一下雨，她就哭……了”的语境。"}, {"text": "进去", "is_correct": false, "explanation": "搭配：“进去”表示由外向内移动，“哭进去”搭配不当。"}, {"text": "过来", "is_correct": false, "explanation": "搭配：“过来”表示朝说话人方向移动，与“哭”不能组合表示哭的开始。"}, {"text": "进来", "is_correct": false, "explanation": "语义：“进来”指从外面到里面，与“一下雨就哭”的语境不符。"}], "explanations": {"起来": "起来：用在动词后，表示“哭”这个动作开始并持续，符合“一下雨，她就哭……了”的语境。", "进去": "搭配：“进去”表示由外向内移动，“哭进去”搭配不当。", "过来": "搭配：“过来”表示朝说话人方向移动，与“哭”不能组合表示哭的开始。", "进来": "语义：“进来”指从外面到里面，与“一下雨就哭”的语境不符。"}, "sentence_index": 6, "correct_answer": "起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨还没停，我们就继续等起来。", "explanation": "这里应该用〈下去〉。“继续”表示接着做，要用“下去”；“起来”强调动作开始，与“继续”的意思冲突。"}, {"text": "他一直想，想到一半就停起来了。", "explanation": "这里应该用〈下来〉。“停下来”表示中止，“起来”表示开始，不能用于中止。"}, {"text": "他忙了一整天，晚上终于闲起来了。", "explanation": "这里应该用〈下来〉。从忙到闲是活动减弱、趋于停止，应说“闲下来”；“起来”表示开始或增强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20125, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气冷起来着。", "corrected_sentence": "天气冷起来了。", "error_description": "错误形式：“冷起来着”；正确形式：“冷起来了”。“起来”表示变化已经出现，应用“了”，不能用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20125, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "街上的人很多起来了。", "corrected_sentence": "街上的人多起来了。", "error_description": "错误形式：“很多起来了”；正确形式：“多起来了”。“多起来”已表示数量逐渐增加，“多”前面不能再加程度副词“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
