INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20126, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手拿笔在纸上写出字。", "primary_collocate": null, "pronunciation": "xiě", "ipa": "ɕjɛ˨˩˦", "syllable_count": 1, "sentences": [{"text": "请把你的名字写在这里。", "target_word": "写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在给妈妈写信。", "target_word": "写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用铅笔写字。", "target_word": "写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字怎么写？", "target_word": "写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写了一封很长的信。", "target_word": "写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写着今天的作业。", "target_word": "写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用左手写字。", "target_word": "写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你写下电话号码。", "target_word": "写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天写过日记。", "target_word": "写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们坐在桌子旁写作业。", "target_word": "写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "写了", "label": "体标"}, {"form": "写着", "label": "体标"}, {"form": "写过", "label": "体标"}, {"form": "写字", "label": "复合"}], "register": "中性", "sense_fingerprint": "用笔把字写在纸或其他东西上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bacc239c-df87-4c0c-a87d-ec7f9978f1b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20126, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "写", "is_correct": true, "explanation": "正确：“写”（xiě，第三声）指用笔把字写在纸上，即目标义项。"}, {"text": "谢", "is_correct": false, "explanation": "“谢”（xiè，第四声）与 xiě（第三声）声调不同，意思是感谢。"}, {"text": "鞋", "is_correct": false, "explanation": "“鞋”（xié，第二声）与 xiě（第三声）声调不同，意思是鞋子。"}, {"text": "些", "is_correct": false, "explanation": "“些”（xiē，第一声）与 xiě（第三声）声调不同，意思是一些。"}], "explanations": {"写": "正确：“写”（xiě，第三声）指用笔把字写在纸上，即目标义项。", "谢": "“谢”（xiè，第四声）与 xiě（第三声）声调不同，意思是感谢。", "鞋": "“鞋”（xié，第二声）与 xiě（第三声）声调不同，意思是鞋子。", "些": "“些”（xiē，第一声）与 xiě（第三声）声调不同，意思是一些。"}, "sentence_index": null, "correct_answer": "写"}, "level_3": {"options": [{"text": "写", "is_correct": true, "explanation": "正确：“写”指用笔把字写在纸上，符合“请把你的名字……在这里”的语境。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，不能把名字唱在某处。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“名字”和“在这里”搭配，说“洗名字”不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与“把名字……在这里”不相容。"}], "explanations": {"写": "正确：“写”指用笔把字写在纸上，符合“请把你的名字……在这里”的语境。", "唱": "语义：“唱”指发出歌声，不能把名字唱在某处。", "洗": "搭配：“洗”不能与“名字”和“在这里”搭配，说“洗名字”不通。", "吃": "语义：“吃”指进食，与“把名字……在这里”不相容。"}, "sentence_index": 0, "correct_answer": "写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在纸上写了一只猫。", "explanation": "这里应该用〈画〉。“写”指用笔写字，画猫要用“画”。"}, {"text": "他用尺子写了桌子的长度。", "explanation": "这里应该用〈量〉。“写”指用笔写字，测量长度要用“量”。"}, {"text": "我给朋友写饭。", "explanation": "这里应该用〈做〉。“写”指用笔写字，做饭不能用“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20126, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "写", "is_correct": true, "explanation": "正确：“写”（xiě，第三声）指用笔写字，即目标义项。"}, {"text": "雪", "is_correct": false, "explanation": "“雪”（xuě）与 xiě 的介音不同（u/i），意思是雪。"}, {"text": "歇", "is_correct": false, "explanation": "“歇”（xiē，第一声）与 xiě（第三声）声调不同，意思是休息。"}, {"text": "斜", "is_correct": false, "explanation": "“斜”（xié，第二声）与 xiě（第三声）声调不同，意思是斜。"}], "explanations": {"写": "正确：“写”（xiě，第三声）指用笔写字，即目标义项。", "雪": "“雪”（xuě）与 xiě 的介音不同（u/i），意思是雪。", "歇": "“歇”（xiē，第一声）与 xiě（第三声）声调不同，意思是休息。", "斜": "“斜”（xié，第二声）与 xiě（第三声）声调不同，意思是斜。"}, "sentence_index": null, "correct_answer": "写"}, "level_3": {"options": [{"text": "写", "is_correct": true, "explanation": "正确：“写”指用笔写字，符合“小明用左手……字”的语境。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”是跳跃的动作，不能用来写字。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚的动作，与“用左手”的语境不符。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”一般用于食物等，不能用来修饰“字”。"}], "explanations": {"写": "正确：“写”指用笔写字，符合“小明用左手……字”的语境。", "跳": "语义：“跳”是跳跃的动作，不能用来写字。", "踢": "语义：“踢”是用脚的动作，与“用左手”的语境不符。", "切": "搭配：“切”一般用于食物等，不能用来修饰“字”。"}, "sentence_index": 6, "correct_answer": "写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们大声写课文。", "explanation": "这里应该用〈念〉。“写”是用笔写字，不能“大声”进行。"}, {"text": "他写了一大碗饭。", "explanation": "这里应该用〈吃〉。“写”只能用于文字或图画，不能用于吃饭。"}, {"text": "妈妈写了一道好吃的菜。", "explanation": "这里应该用〈做〉。“写”指记录文字，不能用来做菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个句子我已经完写了。", "corrected_sentence": "这个句子我已经写完了。", "error_description": "补语位置错误：结果补语“完”应放在“写”后，说“写完”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个字你对写了吗？", "corrected_sentence": "这个字你写对了吗？", "error_description": "补语位置错误：结果补语“对”应放在动词“写”后，说“写对了”，不能说“对写”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
