INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20130, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指很多很多人。", "primary_collocate": null, "pronunciation": "rén men", "ipa": "ʐən˧˥ mən", "syllable_count": 2, "sentences": [{"text": "下雨了，人们都回家了。", "target_word": "人们", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，人们都很高兴。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在人们常用手机买东西。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里，人们在唱歌跳舞。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们说，好人会有好事。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，人们应该爱护环境。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很热，人们都想喝冰水。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个小城，人们过着安静的生活。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前人们坐火车去很远的地方。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的人们都在看那只大狗。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "泛指许多人的群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05710f7d-b7af-44a9-a7be-d2504441099b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人们", "is_correct": true, "explanation": "“人们”：泛指许多人，下雨时人们都回家，句子成立。"}, {"text": "石头们", "is_correct": false, "explanation": "语义：石头不会回家，与“下雨了”的语境不符。"}, {"text": "机器们", "is_correct": false, "explanation": "配价：“回家”的主语须是人或动物，不能是机器。"}, {"text": "桌子们", "is_correct": false, "explanation": "语义：桌子不能回家，句子无法成立。"}], "explanations": {"人们": "“人们”：泛指许多人，下雨时人们都回家，句子成立。", "石头们": "语义：石头不会回家，与“下雨了”的语境不符。", "机器们": "配价：“回家”的主语须是人或动物，不能是机器。", "桌子们": "语义：桌子不能回家，句子无法成立。"}, "sentence_index": 0, "correct_answer": "人们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的人们都在老家。", "explanation": "这里应该用〈家人〉。“人们”泛指社会上很多人，不能指自己的家人。"}, {"text": "他的人们今天都来了。", "explanation": "这里应该用〈手下〉。“人们”泛指很多人，不能指某人的部下。"}, {"text": "我们的人们正在开会。", "explanation": "这里应该用〈同事〉。“人们”泛指很多人，不能指自己单位里的同事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人们", "is_correct": true, "explanation": "“人们”：泛指的人，天气热时人们都想喝冰水，句子成立。"}, {"text": "窗户们", "is_correct": false, "explanation": "语义：窗户不能喝水，句子无法成立。"}, {"text": "电脑们", "is_correct": false, "explanation": "配价：“想喝”的主语须是有生命的人或动物，不能是电脑。"}, {"text": "房子们", "is_correct": false, "explanation": "语义：房子不能想喝水，句子不成立。"}], "explanations": {"人们": "“人们”：泛指的人，天气热时人们都想喝冰水，句子成立。", "窗户们": "语义：窗户不能喝水，句子无法成立。", "电脑们": "配价：“想喝”的主语须是有生命的人或动物，不能是电脑。", "房子们": "语义：房子不能想喝水，句子不成立。"}, "sentence_index": 6, "correct_answer": "人们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板的人们明天会来。", "explanation": "这里应该用〈员工〉。“人们”泛指很多人，不能指老板手下的员工。"}, {"text": "你的人们怎么还没到？", "explanation": "这里应该用〈朋友〉。“人们”泛指很多人，不能指你的某几位朋友。"}, {"text": "她的人们都住在城里。", "explanation": "这里应该用〈亲戚〉。“人们”泛指很多人，不能指她的亲戚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街上的三个人们都很忙。", "corrected_sentence": "街上的人们都很忙。", "error_description": "数量词错误：“人们”是复数，不能加“三个”。应说“街上的人们”，或改为“街上的三个人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里的人们们都很友好。", "corrected_sentence": "这里的人们都很友好。", "error_description": "重复：“人们”已含复数“们”，不能再加“们”。应说“这里的人们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20132, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "快", "is_correct": true, "explanation": "快：速度高、用时间短，与“慢”相对，互为反义。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：清晰、明白，与速度无关，不是反义。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮：好看，与速度无关，不是反义。"}, {"text": "干净", "is_correct": false, "explanation": "干净：没有脏东西，与速度无关，不是反义。"}], "correct_answer": "快", "explanations": {"快": "快：速度高、用时间短，与“慢”相对，互为反义。", "清楚": "清楚：清晰、明白，与速度无关，不是反义。", "漂亮": "漂亮：好看，与速度无关，不是反义。", "干净": "干净：没有脏东西，与速度无关，不是反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20132, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "快", "is_correct": true, "explanation": "快：速度高、用时间短，与“慢”相对，互为反义。"}, {"text": "轻松", "is_correct": false, "explanation": "轻松：不费力、不紧张，与速度的快慢不构成反义。"}, {"text": "大方", "is_correct": false, "explanation": "大方：举止自然或不吝啬，与速度无关，不是反义。"}, {"text": "冷静", "is_correct": false, "explanation": "冷静：不慌乱、不激动，与“慢”不构成反义。"}], "correct_answer": "快", "explanations": {"快": "快：速度高、用时间短，与“慢”相对，互为反义。", "轻松": "轻松：不费力、不紧张，与速度的快慢不构成反义。", "大方": "大方：举止自然或不吝啬，与速度无关，不是反义。", "冷静": "冷静：不慌乱、不激动，与“慢”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20132, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "慢的意思是做事用时间长，不着急。", "primary_collocate": null, "pronunciation": "màn", "ipa": "man˥˩", "syllable_count": 1, "sentences": [{"text": "他走路很慢。", "target_word": "慢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请说慢一点。", "target_word": "慢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶做饭很慢，但是很好吃。", "target_word": "慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的车太慢了，我们要迟到了。", "target_word": "慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃饭慢，每次都最后一个吃完。", "target_word": "慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只小乌龟爬得很慢。", "target_word": "慢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路上有雪，开车要慢，不要着急。", "target_word": "慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网速太慢，视频一直打不开。", "target_word": "慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的手机反应很慢，用起来不方便。", "target_word": "慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学汉语不能太急，慢一点才记得住。", "target_word": "慢", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "慢慢", "label": "重叠"}, {"form": "慢了", "label": "了体"}], "register": "中性", "sense_fingerprint": "形容词：速度低、动作或过程用时长，与“快”相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75b6c6b-1a83-43ea-bf8d-cebf12c05e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20132, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "慢", "is_correct": true, "explanation": "慢（màn）：速度低、做事用时间长，与听到的读音一致。"}, {"text": "满", "is_correct": false, "explanation": "满（mǎn，第三声）与 màn（第四声）声调不同，意思是装满，不是慢。"}, {"text": "瞒", "is_correct": false, "explanation": "瞒（mán，第二声）与 màn（第四声）声调不同，意思是隐瞒，不是慢。"}, {"text": "蛮", "is_correct": false, "explanation": "蛮（mán，第二声）与 màn（第四声）声调不同，意思是很、相当，不是慢。"}], "explanations": {"慢": "慢（màn）：速度低、做事用时间长，与听到的读音一致。", "满": "满（mǎn，第三声）与 màn（第四声）声调不同，意思是装满，不是慢。", "瞒": "瞒（mán，第二声）与 màn（第四声）声调不同，意思是隐瞒，不是慢。", "蛮": "蛮（mán，第二声）与 màn（第四声）声调不同，意思是很、相当，不是慢。"}, "sentence_index": null, "correct_answer": "慢"}, "level_3": {"options": [{"text": "慢", "is_correct": true, "explanation": "慢：速度低、用时间长，符合“他走路很慢”的说法。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”描述身高或位置，不能用来说走路的快慢。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”指颜色或受欢迎，与走路的速度无关。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”说价钱，不能用来描述走路。"}], "explanations": {"慢": "慢：速度低、用时间长，符合“他走路很慢”的说法。", "高": "搭配：“高”描述身高或位置，不能用来说走路的快慢。", "红": "语义：“红”指颜色或受欢迎，与走路的速度无关。", "贵": "语义：“贵”说价钱，不能用来描述走路。"}, "sentence_index": 0, "correct_answer": "慢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间太慢了，放不下一张床。", "explanation": "这里应该用〈小〉。房间的大小要用“大”“小”，慢只用于速度或时间。"}, {"text": "这把刀很慢，切菜都切不动。", "explanation": "这里应该用〈钝〉。钝指刀刃不锋利；慢只用于速度或时间，不能描述刀的锋利程度。"}, {"text": "这次考试他的成绩很慢。", "explanation": "这里应该用〈差〉。成绩的好坏要用“好”“差”来说，慢只用于速度或时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "慢", "is_correct": true, "explanation": "慢：速度低，符合“开车要慢，不要着急”的语境。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”说距离，不能用来说开车的快慢。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”描述味道，与开车无关。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描述人的身材，不能用于开车。"}], "explanations": {"慢": "慢：速度低，符合“开车要慢，不要着急”的语境。", "远": "语义：“远”说距离，不能用来说开车的快慢。", "甜": "语义：“甜”描述味道，与开车无关。", "胖": "体貌：“胖”描述人的身材，不能用于开车。"}, "sentence_index": 6, "correct_answer": "慢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤慢了，已经不热了。", "explanation": "这里应该用〈凉〉。汤变冷要说“凉”；慢只用于速度或时间，不能描述温度。"}, {"text": "今天天气很慢，出门要多穿衣服。", "explanation": "这里应该用〈冷〉。天气的冷热要用“冷”，慢只用于速度或时间，不能描述温度。"}, {"text": "这家店的价格很慢。", "explanation": "这里应该用〈低〉。价格的高低要用“低”，慢只用于速度或时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他走的很慢，所以大家都等他。", "corrected_sentence": "他走得很慢，所以大家都等他。", "error_description": "错误形式“走的很慢”：动词后的程度补语要用“得”，不能用“的”，应为“走得很慢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "开车请慢一个，路上有雪。", "corrected_sentence": "开车请慢一点，路上有雪。", "error_description": "错误形式“慢一个”：作程度补语的“一点”不能换成“一个”，“个”不能修饰表示速度的“慢”，应为“慢一点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
