INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20134, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20134, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手拿笔在纸上写出字。", "primary_collocate": null, "pronunciation": "xiě zì", "ipa": "ɕjɛ˨˩˦ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "小明拿着笔，正在桌子前写字。", "target_word": "写字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹才四岁，已经会在纸上写字了。", "target_word": "写字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他右手受了伤，没办法拿笔写字。", "target_word": "写字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天早上用毛笔练习写字。", "target_word": "写字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，写字时要坐直，笔要拿稳。", "target_word": "写字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她左手按着纸，右手写字。", "target_word": "写字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到笔了，现在没法写字。", "target_word": "写字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸他写字写得很漂亮。", "target_word": "写字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，外婆握着我的手教我写字。", "target_word": "写字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累了，把笔放下，不想再写字了。", "target_word": "写字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "写了字", "label": "完成体"}, {"form": "写过字", "label": "经验体"}, {"form": "写写字", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用手握笔在纸上书写汉字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4848e3-df86-4870-9771-0c70385a07a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20134, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "写字", "is_correct": true, "explanation": "正确：“写字”指用笔在纸上写字，与句中“拿着笔、在桌子前”相符。"}, {"text": "切菜", "is_correct": false, "explanation": "语义：句中拿着笔，切菜要用刀，与“拿着笔”的语境矛盾。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：洗澡需要浴室和水，不能说“在桌子前洗澡”。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：游泳需要水池，不能说“在桌子前游泳”。"}], "explanations": {"写字": "正确：“写字”指用笔在纸上写字，与句中“拿着笔、在桌子前”相符。", "切菜": "语义：句中拿着笔，切菜要用刀，与“拿着笔”的语境矛盾。", "洗澡": "搭配：洗澡需要浴室和水，不能说“在桌子前洗澡”。", "游泳": "搭配：游泳需要水池，不能说“在桌子前游泳”。"}, "sentence_index": 0, "correct_answer": "写字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天写字，写到深夜，希望将来成为一名作家。", "explanation": "这里应该用〈写作〉。写字指用笔写出字形，创作文章、作品要用写作。"}, {"text": "妈妈在厨房里写字，炒了一盘青菜。", "explanation": "这里应该用〈炒〉。写字指用笔书写，做菜要说炒菜。"}, {"text": "美术课上，老师带我们到湖边写字，每人都要画一幅湖边的风景。", "explanation": "这里应该用〈写生〉。写字指用笔书写文字，外出对着景物作画要说写生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "写字", "is_correct": true, "explanation": "正确：“写字”指用笔写字，与“找不到笔”的因果关系相符。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：“出生”是一次性事件，不能与“没法”搭配。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是自然现象，人不能“没法下雨”，句意不通。"}, {"text": "爆炸", "is_correct": false, "explanation": "语义：爆炸是突发事件，不能说人“没法爆炸”，与句意矛盾。"}], "explanations": {"写字": "正确：“写字”指用笔写字，与“找不到笔”的因果关系相符。", "出生": "搭配：“出生”是一次性事件，不能与“没法”搭配。", "下雨": "语义：下雨是自然现象，人不能“没法下雨”，句意不通。", "爆炸": "语义：爆炸是突发事件，不能说人“没法爆炸”，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "写字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工匠用凿子在石头上写字，刻了三天才完成。", "explanation": "这里应该用〈刻字〉。写字指用笔书写，用刀在石头上做字要说刻字。"}, {"text": "妈妈坐在窗前，用针在布上写字，绣出了一朵红花。", "explanation": "这里应该用〈绣花〉。写字指用笔书写，用针线在布上做花纹要说绣花。"}, {"text": "他坐在窗前用铅笔写字，画出了一只小鸟。", "explanation": "这里应该用〈画〉。写字指用笔写出文字，画出小鸟要说画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐写字写的特别快。", "corrected_sentence": "姐姐写字写得特别快。", "error_description": "“写的”应为“写得”：“写字”后接程度补语，要用结构助词“得”连接动词和补语，“的”不能用于此。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶写字得又慢又认真。", "corrected_sentence": "奶奶写字写得又慢又认真。", "error_description": "“写字得”应为“写字写得”：带程度补语时要重复动词“写”，不能只保留“写字”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
