INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20136, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "印刷术是一种把字或图画印在纸上的方法。", "primary_collocate": null, "pronunciation": "yìn shuā shù", "ipa": "in˥˩ ʂwa˥ ʂu˥˩", "syllable_count": 3, "sentences": [{"text": "印刷术是中国的重要发明。", "target_word": "印刷术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了印刷术，书就便宜了。", "target_word": "印刷术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人很早就发明了印刷术。", "target_word": "印刷术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了印刷术的历史。", "target_word": "印刷术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷术让更多的人能读书。", "target_word": "印刷术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里有很多用印刷术印出来的书。", "target_word": "印刷术", "complexity_tier": "T3", "furigana": "shū diàn lǐ yǒu hěn duō yòng yìn shuā shù yìn chū lái de shū", "sentence_source": "generated"}, {"text": "在印刷术出现以前，人们用手写书。", "target_word": "印刷术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷术的发明帮助知识传到远方。", "target_word": "印刷术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了印刷术怎样改变世界。", "target_word": "印刷术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在博物馆里看到了古代印刷术的工具。", "target_word": "印刷术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "活字印刷术", "label": "复合"}, {"form": "雕版印刷术", "label": "复合"}], "register": "中性", "sense_fingerprint": "把字或图画印到纸上的技术和方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bacc239c-df87-4c0c-a87d-ec7f9978f1b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20136, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "印刷术", "is_correct": true, "explanation": "正确：印刷术是把字或图画印在纸上的方法，可以作“发明”的主语。"}, {"text": "中国", "is_correct": false, "explanation": "语义：中国是国家名称，不是技术或方法，不能作“发明”的主语。"}, {"text": "长城", "is_correct": false, "explanation": "语义：长城是建筑，不是发明，说它是中国的重要发明不通。"}, {"text": "典籍", "is_correct": false, "explanation": "语域：典籍书面色彩重，指古代书籍本身，不是技术或方法，与“发明”搭配不当。"}], "explanations": {"印刷术": "正确：印刷术是把字或图画印在纸上的方法，可以作“发明”的主语。", "中国": "语义：中国是国家名称，不是技术或方法，不能作“发明”的主语。", "长城": "语义：长城是建筑，不是发明，说它是中国的重要发明不通。", "典籍": "语域：典籍书面色彩重，指古代书籍本身，不是技术或方法，与“发明”搭配不当。"}, "sentence_index": 0, "correct_answer": "印刷术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书是印刷术。", "explanation": "这里应该用〈印刷品〉。“这本书是……”指印出来的东西，印刷术是方法，不能这样判断。"}, {"text": "这张纸上印着很多印刷术。", "explanation": "这里应该用〈字〉。“印”的对象是字或图案，印刷术是方法，不能印在纸上。"}, {"text": "这家出版社每年出版很多印刷术。", "explanation": "这里应该用〈书籍〉。出版的对象是书籍或刊物，印刷术是方法，不能被出版。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "印刷术", "is_correct": true, "explanation": "正确：“在……出现以前”后接的正是被出现的技术，印刷术符合句意。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海本来就存在，不说“在大海出现以前”，与句中的时间背景不合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不是可以“出现”的事物，搭配不当。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮本来就存在，不说“出现以前”，句意不通。"}], "explanations": {"印刷术": "正确：“在……出现以前”后接的正是被出现的技术，印刷术符合句意。", "大海": "语义：大海本来就存在，不说“在大海出现以前”，与句中的时间背景不合。", "身材": "体貌：身材指人的体形，不是可以“出现”的事物，搭配不当。", "月亮": "语义：月亮本来就存在，不说“出现以前”，句意不通。"}, "sentence_index": 6, "correct_answer": "印刷术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂的印刷术每天都在工作。", "explanation": "这里应该用〈印刷机〉。印刷术是方法，不会工作，运转的是印刷机。"}, {"text": "他在印刷术工作。", "explanation": "这里应该用〈印刷厂〉。“在……工作”要接工作的地方，印刷术是方法，不是地点。"}, {"text": "我每天喝印刷术。", "explanation": "这里应该用〈茶〉。“喝”的对象是饮品，印刷术是方法，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在学校学了一把印刷术。", "corrected_sentence": "我在学校学了一种印刷术。", "error_description": "“印刷术”是技术，量词应用“种”。“把”用于有柄的物品，不能修饰印刷术，应说“一种印刷术”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前学过一本印刷术。", "corrected_sentence": "他以前学过印刷术。", "error_description": "“印刷术”是技术，不是书册，不能用量词“本”计量，多出的“一本”应去掉，说“学过印刷术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
