INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20138, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "意思是过去很远的时候。", "primary_collocate": null, "pronunciation": "hěn jiǔ yǐ qián", "ipa": "xən˨˩ tɕi̯oʊ˨˩˦ i˨˩˦ tɕʰi̯ɛn˧˥", "syllable_count": 4, "sentences": [{"text": "很久以前，这里有一条很大的河。", "target_word": "很久以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久以前，我家住在一个小村子里。", "target_word": "很久以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，很久以前这里没有学校。", "target_word": "很久以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们很久以前就认识了。", "target_word": "很久以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久以前，人们晚上用蜡烛看书。", "target_word": "很久以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事发生在很久以前，我已经忘了。", "target_word": "很久以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久以前，他是我的同学，现在是我的老师。", "target_word": "很久以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶很久以前去过北京。", "target_word": "很久以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久以前，有一个国王住在高山上。", "target_word": "很久以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店很久以前就开了，客人很多。", "target_word": "很久以前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "很久以前：过去很远的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8c9982-2261-4a26-bafc-a41b87d5771d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "很久以前", "is_correct": true, "explanation": "正确：“很久以前”表示过去很远的时候，与这段讲述古时情况的语境相符。"}, {"text": "每天", "is_correct": false, "explanation": "语义：“每天”表示反复发生，而“一条很大的河”是长期存在的状态，不能说每天有。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与“这里有一条很大的河”描述的现存状态相矛盾。"}, {"text": "刚才", "is_correct": false, "explanation": "搭配：“刚才”多用于刚发生的事，不用来说明一条河存在于很远的过去。"}], "explanations": {"很久以前": "正确：“很久以前”表示过去很远的时候，与这段讲述古时情况的语境相符。", "每天": "语义：“每天”表示反复发生，而“一条很大的河”是长期存在的状态，不能说每天有。", "明天": "语义：“明天”指将来，与“这里有一条很大的河”描述的现存状态相矛盾。", "刚才": "搭配：“刚才”多用于刚发生的事，不用来说明一条河存在于很远的过去。"}, "sentence_index": 0, "correct_answer": "很久以前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们明天很久以前就出发去北京。", "explanation": "这里应该用〈提前〉。“很久以前”指过去很远的时候，不能用于将来的“明天”；表示提早出发要说“提前”。"}, {"text": "我每天很久以前就起床。", "explanation": "这里应该用〈早早〉。“很久以前”只指一次性的遥远过去，不能表示每天的习惯；每天提早起床要说“早早”。"}, {"text": "他很久以前就会回来。", "explanation": "这里应该用〈不久以后〉。“很久以前”指过去很远的时候，不能与表示将来的“会”搭配；说将来的事要用“不久以后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很久以前", "is_correct": true, "explanation": "正确：“很久以前”表示过去很远的时候，与“他是我的同学，现在是我的老师”的前后变化相符。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”指将来，与“现在是我的老师”的现在时态矛盾。"}, {"text": "下个月", "is_correct": false, "explanation": "语义：“下个月”指将来，与“现在是我的老师”的现在时态矛盾。"}, {"text": "一会儿", "is_correct": false, "explanation": "搭配：“一会儿”表示短时段，不能用来说明身份经历的长期变化。"}], "explanations": {"很久以前": "正确：“很久以前”表示过去很远的时候，与“他是我的同学，现在是我的老师”的前后变化相符。", "明年": "语义：“明年”指将来，与“现在是我的老师”的现在时态矛盾。", "下个月": "语义：“下个月”指将来，与“现在是我的老师”的现在时态矛盾。", "一会儿": "搭配：“一会儿”表示短时段，不能用来说明身份经历的长期变化。"}, "sentence_index": 6, "correct_answer": "很久以前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很久以前才吃了早饭，现在还很饱。", "explanation": "这里应该用〈刚才〉。“很久以前”指过去很远的时候，和“现在还很饱”矛盾；刚刚吃过饭要说“刚才”。"}, {"text": "这家店很久以前刚刚开了。", "explanation": "这里应该用〈前几天〉。“很久以前”指过去很远的时候，与“刚刚”的近距离矛盾；说不久前开业要用“前几天”。"}, {"text": "这家店是很久以前才开的，桌子椅子都还是新的。", "explanation": "这里应该用〈不久前〉。“很久以前”指过去很远的时候，和店里东西都还是新的矛盾；说最近开业要用“不久前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我爸爸很久以前的就喜欢这首歌。", "corrected_sentence": "我爸爸很久以前就喜欢这首歌。", "error_description": "错误：“很久以前”后多加了“的”，使它变成定语，后面缺少中心语，句子不通。正确：删去“的”，应说“我爸爸很久以前就喜欢这首歌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的老师很久以前的就来过这里。", "corrected_sentence": "我们的老师很久以前就来过这里。", "error_description": "错误：“很久以前”后多加了“的”，使它变成定语，后面缺少中心语，句子不通。正确：直接接“就”，即“很久以前就来过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
