INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20140, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来印出字的模型。", "primary_collocate": null, "pronunciation": "zì mú", "ipa": "tsɹ̩⁵¹ mu³⁵", "syllable_count": 2, "sentences": [{"text": "这个字模是铁做的。", "target_word": "字模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅用字模印书。", "target_word": "字模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一个旧字模。", "target_word": "字模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把字模放在桌子上。", "target_word": "字模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套字模一共有五百个字。", "target_word": "字模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "字模太小，印出来的字不清楚。", "target_word": "字模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在做新字模。", "target_word": "字模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这个字模上的字是反的。", "target_word": "字模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前的人先做字模，再印书。", "target_word": "字模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字模很重，我拿不动。", "target_word": "字模", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "套", "label": "量词"}], "register": "中性", "sense_fingerprint": "印刷用的字的模型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f67254c-2b72-48f7-a62f-6cc95d11eae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20140, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "字模", "is_correct": true, "explanation": "正确：字模 zì mú，指用来印出字的模型。"}, {"text": "字母", "is_correct": false, "explanation": "第二音节 mǔ（第三声）与 mú（第二声）声调不同，意思是字母。"}, {"text": "字幕", "is_correct": false, "explanation": "第二音节 mù（第四声）与 mú（第二声）声调不同，意思是字幕。"}, {"text": "字谜", "is_correct": false, "explanation": "第二音节 mí 与 mú 韵母不同（i 与 u），意思是猜字的谜语。"}, {"text": "字符", "is_correct": false, "explanation": "第二音节 fú 与 mú 声母不同（f 与 m），意思是字符。"}, {"text": "制模", "is_correct": false, "explanation": "第一音节 zhì 与 zì 声母不同（zh 与 z），意思是制作模型。"}], "explanations": {"字模": "正确：字模 zì mú，指用来印出字的模型。", "字母": "第二音节 mǔ（第三声）与 mú（第二声）声调不同，意思是字母。", "字幕": "第二音节 mù（第四声）与 mú（第二声）声调不同，意思是字幕。", "字谜": "第二音节 mí 与 mú 韵母不同（i 与 u），意思是猜字的谜语。", "字符": "第二音节 fú 与 mú 声母不同（f 与 m），意思是字符。", "制模": "第一音节 zhì 与 zì 声母不同（zh 与 z），意思是制作模型。"}, "sentence_index": null, "correct_answer": "字模"}, "level_3": {"options": [{"text": "字模", "is_correct": true, "explanation": "正确：字模是印字用的模型，可以是铁做的。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能是铁做的。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头是木材，与“铁做的”矛盾。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能用来说物品是什么材料做的。"}], "explanations": {"字模": "正确：字模是印字用的模型，可以是铁做的。", "蛋糕": "语义：蛋糕是食物，不能是铁做的。", "木头": "语义：木头是木材，与“铁做的”矛盾。", "身材": "体貌：身材指人的体形，不能用来说物品是什么材料做的。"}, "sentence_index": 0, "correct_answer": "字模"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天翻字模查生词。", "explanation": "这里应该用〈字典〉。字模是印字用的模型，不能用来查生词。"}, {"text": "她是一名很有名的字模。", "explanation": "这里应该用〈模特〉。字模是印字用的模型，指物体，不能用来指人。"}, {"text": "我买了一头字模。", "explanation": "这里应该用〈个〉。字模是器物，“头”只用于牛马等大型牲畜，不能用于字模。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "字模", "is_correct": true, "explanation": "正确：字模是印字用的模型，工人可以做出来。"}, {"text": "谎言", "is_correct": false, "explanation": "搭配：“做”一般不和“谎言”搭配，要说“编”谎言。"}, {"text": "风景", "is_correct": false, "explanation": "语义：风景是自然景色，不能被工人“做”出来。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人的高矮，不是工人能做出来的东西。"}], "explanations": {"字模": "正确：字模是印字用的模型，工人可以做出来。", "谎言": "搭配：“做”一般不和“谎言”搭配，要说“编”谎言。", "风景": "语义：风景是自然景色，不能被工人“做”出来。", "身高": "体貌：身高指人的高矮，不是工人能做出来的东西。"}, "sentence_index": 6, "correct_answer": "字模"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们的字模。", "explanation": "这里应该用〈模范〉。字模是印字用的模型，指物体，不能用来指值得学习的人。"}, {"text": "他每天用字模练字。", "explanation": "这里应该用〈字帖〉。字模是印刷用的模型，不是练字的范本。"}, {"text": "他用字模开了门。", "explanation": "这里应该用〈钥匙〉。字模是印字用的模型，不能用来开门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一根字模。", "corrected_sentence": "我买了一套字模。", "error_description": "量词错误：字模成套使用，应说“一套字模”，不能用“根”（“根”用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人字模装进了箱子里。", "corrected_sentence": "工人把字模装进了箱子里。", "error_description": "把字句错误：“装进”这类处置动作要用“把”引出字模，应说“把字模装进”，不能省略“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
