INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20142, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做事情或制作东西。", "primary_collocate": null, "pronunciation": "zuò", "ipa": "tsuɔ˥˩", "syllable_count": 1, "sentences": [{"text": "妈妈在厨房做饭。", "target_word": "做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你晚上做什么？", "target_word": "做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经做完作业了。", "target_word": "做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想做一张木头桌子。", "target_word": "做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服是我妈妈自己做的。", "target_word": "做", "complexity_tier": "T3", "furigana": "zhè jiàn yīfu shì wǒ māma zìjǐ zuò de", "sentence_source": "generated"}, {"text": "她做的蛋糕很好吃。", "target_word": "做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天做了一个很大的风筝。", "target_word": "做", "complexity_tier": "T3", "furigana": "tā zuótiān zuò le yí ge hěn dà de fēngzheng", "sentence_source": "generated"}, {"text": "他在公司做销售工作。", "target_word": "做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做过中国菜吗？", "target_word": "做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们一起做点心吧。", "target_word": "做", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做了", "label": "体标"}, {"form": "做过", "label": "体标"}, {"form": "做着", "label": "体标"}], "register": "中性", "sense_fingerprint": "做事或制作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09aebaf0-be95-4ef2-b319-0da839c40a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20142, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "做", "is_correct": true, "explanation": "做 zuò：正确答案，指做事或制作东西。"}, {"text": "错", "is_correct": false, "explanation": "声母不同：错 cuò 的 c 与做 zuò 的 z 不同（送气与不送气），意思是错误。"}, {"text": "左", "is_correct": false, "explanation": "声调不同：左 zuǒ 是第三声，做 zuò 是第四声，意思是左边。"}, {"text": "最", "is_correct": false, "explanation": "韵母不同：最 zuì 的韵母与做 zuò 不同，意思是程度最高。"}], "explanations": {"做": "做 zuò：正确答案，指做事或制作东西。", "错": "声母不同：错 cuò 的 c 与做 zuò 的 z 不同（送气与不送气），意思是错误。", "左": "声调不同：左 zuǒ 是第三声，做 zuò 是第四声，意思是左边。", "最": "韵母不同：最 zuì 的韵母与做 zuò 不同，意思是程度最高。"}, "sentence_index": null, "correct_answer": "做"}, "level_3": {"options": [{"text": "做", "is_correct": true, "explanation": "做：正确答案，与“饭”搭配表示做饭，句意自然。"}, {"text": "修", "is_correct": false, "explanation": "语义：修指修理，不是烹饪动作，与“饭”搭配后句意不通。"}, {"text": "拆", "is_correct": false, "explanation": "语义：拆指拆开、拆除，不能用来描述在厨房里做饭。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语多为歌曲，不能与“饭”搭配。"}], "explanations": {"做": "做：正确答案，与“饭”搭配表示做饭，句意自然。", "修": "语义：修指修理，不是烹饪动作，与“饭”搭配后句意不通。", "拆": "语义：拆指拆开、拆除，不能用来描述在厨房里做饭。", "唱": "搭配：“唱”的宾语多为歌曲，不能与“饭”搭配。"}, "sentence_index": 0, "correct_answer": "做"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天做了感冒。", "explanation": "这里应该用〈得〉。患上感冒要说“得了感冒”，“做”不能与“感冒”搭配。"}, {"text": "我们今天做了一场大雨。", "explanation": "这里应该用〈下〉。下雨要说“下了一场大雨”，“做”不能与“雨”搭配。"}, {"text": "护士做病人。", "explanation": "这里应该用〈照顾〉。护士对病人做的是照顾，“做病人”的说法不符合护士的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做", "is_correct": true, "explanation": "做：正确答案，“做了一个风筝”表示制作，句意自然。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应为食物，风筝不能吃，搭配不成立。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝指饮用液体，与风筝无关，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：洗的对象多为衣物或身体，不能用于风筝。"}], "explanations": {"做": "做：正确答案，“做了一个风筝”表示制作，句意自然。", "吃": "配价：“吃”的宾语应为食物，风筝不能吃，搭配不成立。", "喝": "语义：喝指饮用液体，与风筝无关，句意不通。", "洗": "搭配：洗的对象多为衣物或身体，不能用于风筝。"}, "sentence_index": 6, "correct_answer": "做"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上去公园做步。", "explanation": "这里应该用〈散〉或〈跑〉。“散步”“跑步”都是常见说法，“做”不能与“步”搭配。"}, {"text": "夏天我们去河里做泳。", "explanation": "这里应该用〈游〉。在水里锻炼说“游泳”，“做”不能与“泳”搭配。"}, {"text": "我们做了一盘棋。", "explanation": "这里应该用〈下〉。下棋要用“下”，“做”不能与“棋”这类游戏搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我做了过这道菜。", "corrected_sentence": "我做过这道菜。", "error_description": "体标错误：表示经历的“过”应紧跟动词“做”，不能和“了”连用说成“做了过”，应说“做过这道菜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班的同学都很会饭做。", "corrected_sentence": "我们班的同学都很会做饭。", "error_description": "语序错误：“做饭”是动宾结构，应说“做饭”，不能颠倒成“饭做”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
