INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20144, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用印章在纸上留下记号。", "primary_collocate": null, "pronunciation": "yìn", "ipa": "in˥˩", "syllable_count": 1, "sentences": [{"text": "请在这张纸上印一下你的章。", "target_word": "印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在我的本子上印了一朵花。", "target_word": "印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿起印章，在文件上印了一下。", "target_word": "印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用小印章在每本书上印名字。", "target_word": "印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作人员在票上印了一个日期。", "target_word": "印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先在这里用印章印一下。", "target_word": "印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把红色印章按在纸上，印出一个圆圈。", "target_word": "印", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢用小印章在纸上印小动物。", "target_word": "印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行职员把红章印在合同上，然后还给了我。", "target_word": "印", "complexity_tier": "T3", "furigana": "yínháng zhíyuán bǎ hóngzhāng yìn zài hétóng shàng, ránhòu huán gěi le wǒ", "sentence_source": "generated"}, {"text": "这份合同你先印上公司的章，我再签字。", "target_word": "印", "complexity_tier": "T3", "furigana": "zhè fèn hétong nǐ xiān yìn shàng gōngsī de zhāng, wǒ zài qiānzì", "sentence_source": "generated"}], "morphological_forms": [{"form": "印了", "label": "体标"}, {"form": "印过", "label": "体标"}, {"form": "印章", "label": "复合"}], "register": "中性", "sense_fingerprint": "印：用印章在纸上按出记号或图案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63f12163-19cc-4b51-bb0d-63aa4777bd4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20144, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "印", "is_correct": true, "explanation": "印：yìn（第四声），用印章在纸上按出记号。"}, {"text": "引", "is_correct": false, "explanation": "yǐn（第三声）与 yìn（第四声）声调不同，意思是引导。"}, {"text": "因", "is_correct": false, "explanation": "yīn（第一声）与 yìn（第四声）声调不同，意思是因为。"}, {"text": "银", "is_correct": false, "explanation": "yín（第二声）与 yìn（第四声）声调不同，意思是银子。"}, {"text": "饮", "is_correct": false, "explanation": "yǐn（第三声）与 yìn（第四声）声调不同，意思是饮用。"}], "explanations": {"印": "印：yìn（第四声），用印章在纸上按出记号。", "引": "yǐn（第三声）与 yìn（第四声）声调不同，意思是引导。", "因": "yīn（第一声）与 yìn（第四声）声调不同，意思是因为。", "银": "yín（第二声）与 yìn（第四声）声调不同，意思是银子。", "饮": "yǐn（第三声）与 yìn（第四声）声调不同，意思是饮用。"}, "sentence_index": null, "correct_answer": "印"}, "level_3": {"options": [{"text": "印", "is_correct": true, "explanation": "印：用印章在纸上按出记号，与“你的章”搭配。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“章”要用来盖印，不说“写章”，与“你的章”不搭配。"}, {"text": "切", "is_correct": false, "explanation": "语义：切不会在纸上留下章的痕迹，句意不通。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦会抹去痕迹，与在纸上留章的意思相反。"}], "explanations": {"印": "印：用印章在纸上按出记号，与“你的章”搭配。", "写": "搭配：“章”要用来盖印，不说“写章”，与“你的章”不搭配。", "切": "语义：切不会在纸上留下章的痕迹，句意不通。", "擦": "语义：擦会抹去痕迹，与在纸上留章的意思相反。"}, "sentence_index": 0, "correct_answer": "印"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用尺子印了一下桌子的长度。", "explanation": "这里应该用〈量〉。“量”是测量长度，“印”是按压留记号，不能用来测长度。"}, {"text": "老师把黑板上的字印掉了。", "explanation": "这里应该用〈擦〉。“擦”是抹去，“印”是按压留下记号，不能用来抹掉字迹。"}, {"text": "他用刻刀印了一枚图章。", "explanation": "这里应该用〈刻〉。“刻”是用刀在硬物上刻出字或图章，“印”是按压留痕，不能用来制作图章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20144, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "印", "is_correct": true, "explanation": "印：yìn（第四声），用印章在纸上按出记号。"}, {"text": "阴", "is_correct": false, "explanation": "yīn（第一声）与 yìn（第四声）声调不同，意思是阴天。"}, {"text": "音", "is_correct": false, "explanation": "yīn（第一声）与 yìn（第四声）声调不同，意思是声音。"}, {"text": "进", "is_correct": false, "explanation": "jìn 与 yìn 声母不同，意思是进入。"}, {"text": "尽", "is_correct": false, "explanation": "jìn 与 yìn 声母不同，意思是尽力。"}], "explanations": {"印": "印：yìn（第四声），用印章在纸上按出记号。", "阴": "yīn（第一声）与 yìn（第四声）声调不同，意思是阴天。", "音": "yīn（第一声）与 yìn（第四声）声调不同，意思是声音。", "进": "jìn 与 yìn 声母不同，意思是进入。", "尽": "jìn 与 yìn 声母不同，意思是尽力。"}, "sentence_index": null, "correct_answer": "印"}, "level_3": {"options": [{"text": "印", "is_correct": true, "explanation": "印：用印章按在纸上留下图案，与“按在纸上”的动作一致。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写出”多用于文字、文章，不用于留下圆圈。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃不会在纸上留下圆圈，与“按在纸上”冲突。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱不会在纸上留下图形，句意不通。"}], "explanations": {"印": "印：用印章按在纸上留下图案，与“按在纸上”的动作一致。", "写": "搭配：“写出”多用于文字、文章，不用于留下圆圈。", "吃": "语义：吃不会在纸上留下圆圈，与“按在纸上”冲突。", "唱": "语义：唱不会在纸上留下图形，句意不通。"}, "sentence_index": 6, "correct_answer": "印"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工匠用木头印了一把椅子。", "explanation": "这里应该用〈做〉。“印”是按压留痕，不能用来制作家具，应说“做了一把椅子”。"}, {"text": "妈妈印了一个西瓜，大家一起吃。", "explanation": "这里应该用〈切〉。“切”是把西瓜分开，“印”是按压留痕，不能用来处理西瓜。"}, {"text": "他用肥皂印了手，然后去吃饭。", "explanation": "这里应该用〈洗〉。“洗”是用水和肥皂去除污垢，“印”是用印章按压留痕，不能用来洗手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把章印了在纸上。", "corrected_sentence": "他把章印在了纸上。", "error_description": "“了”位置错误：“印在”是一个整体，“了”应放在“在”后面，说“印在了纸上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子用小印章印了出一朵花。", "corrected_sentence": "孩子用小印章印出了一朵花。", "error_description": "补语语序错误：“出”是“印”的结果补语，应紧跟在“印”后，再接“了”，说“印出了一朵花”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20146, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "很慢", "is_correct": true, "explanation": "正确：“快”与“慢”相对，“很快”描写速度时与“很慢”是反义。"}, {"text": "确实", "is_correct": false, "explanation": "无关：“确实”表示真实可信，与“很快”的速度义没有反义关系。"}, {"text": "一直", "is_correct": false, "explanation": "无关：“一直”表示持续，与“很快”的速度义没有反义关系。"}, {"text": "当然", "is_correct": false, "explanation": "无关：“当然”表示理所应当，与“很快”的速度义没有反义关系。"}], "correct_answer": "很慢", "explanations": {"很慢": "正确：“快”与“慢”相对，“很快”描写速度时与“很慢”是反义。", "确实": "无关：“确实”表示真实可信，与“很快”的速度义没有反义关系。", "一直": "无关：“一直”表示持续，与“很快”的速度义没有反义关系。", "当然": "无关：“当然”表示理所应当，与“很快”的速度义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
