INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20146, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事情用的时间很少，或事情不久就会发生。", "primary_collocate": null, "pronunciation": "hěn kuài", "ipa": "xən˨˩˦ kʰwaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "饭很快就好了，我们可以吃了。", "target_word": "很快", "complexity_tier": "T3", "furigana": "fàn hěn kuài jiù hǎo le, wǒ men kě yǐ chī le", "sentence_source": "generated"}, {"text": "请等一下，我很快就回来。", "target_word": "很快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作很快就能做完。", "target_word": "很快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃饭很快，五分钟就吃完了。", "target_word": "很快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信很快就寄到了。", "target_word": "很快", "complexity_tier": "T3", "furigana": "zhè fēng xìn hěn kuài jiù jì dào le", "sentence_source": "generated"}, {"text": "她写字很快，作业一会儿就写完了。", "target_word": "很快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议很快就结束了。", "target_word": "很快", "complexity_tier": "T3", "furigana": "huì yì hěn kuài jiù jié shù le", "sentence_source": "generated"}, {"text": "雨很快就停了。", "target_word": "很快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，医生很快就来。", "target_word": "很快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的感冒很快就好了。", "target_word": "很快", "complexity_tier": "T3", "furigana": "tā de gǎn mào hěn kuài jiù hǎo le", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做事情用的时间很少，速度大或马上就会发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bacc239c-df87-4c0c-a87d-ec7f9978f1b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20146, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "很快", "is_correct": true, "explanation": "正确：“很快就好了”表示饭在短时间内做好，符合句意。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“饭快好了、可以吃了”的即时语境不合。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰形容词或心理动词，不能用在“就好了”前表示时间快。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不断，与“就好了”表示短时间完成的语境矛盾。"}], "explanations": {"很快": "正确：“很快就好了”表示饭在短时间内做好，符合句意。", "偶尔": "语义：“偶尔”表示不常发生，与“饭快好了、可以吃了”的即时语境不合。", "十分": "搭配：“十分”修饰形容词或心理动词，不能用在“就好了”前表示时间快。", "一直": "语义：“一直”表示持续不断，与“就好了”表示短时间完成的语境矛盾。"}, "sentence_index": 0, "correct_answer": "很快"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我花了三年，很快才学会了中文。", "explanation": "这里应该用〈慢慢〉。很快表示用时很短，与“花了三年”矛盾。"}, {"text": "他做这道题很快，结果做了一整天。", "explanation": "这里应该用〈慢〉。很快表示做事用时很少，与“做了一整天”矛盾。"}, {"text": "这座大桥很快修了五年。", "explanation": "这里应该用〈整整〉。很快表示用时很少，不能和“修了五年”这样的长时间搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20146, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很快", "is_correct": true, "explanation": "正确：“会议很快就结束了”表示会议用时短、马上结束，符合句意。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”表示超出一般的程度，不能用在“就结束了”前表示时间快。"}, {"text": "特别", "is_correct": false, "explanation": "搭配：“特别”修饰形容词或表示程度，不能与“就结束了”的时间语境搭配。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“会议结束”的事件语境矛盾。"}], "explanations": {"很快": "正确：“会议很快就结束了”表示会议用时短、马上结束，符合句意。", "格外": "搭配：“格外”表示超出一般的程度，不能用在“就结束了”前表示时间快。", "特别": "搭配：“特别”修饰形容词或表示程度，不能与“就结束了”的时间语境搭配。", "从不": "语义：“从不”表示从来没有，与“会议结束”的事件语境矛盾。"}, "sentence_index": 6, "correct_answer": "很快"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家离学校很快。", "explanation": "这里应该用〈近〉。很快指做事用时少，不用来说距离远近。"}, {"text": "这座楼很快修了三年。", "explanation": "这里应该用〈足足〉。很快表示用时很短，不能和“修了三年”这样的长时间搭配。"}, {"text": "我的电脑很快，启动要用一个小时。", "explanation": "这里应该用〈慢〉。很快表示用时少，与“启动要用一个小时”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车票卖地很快。", "corrected_sentence": "车票卖得很快。", "error_description": "补语标记误用：“卖”后面引出程度补语要用结构助词“得”，不能用“地”（“地”只标状语）。应说“车票卖得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做事很快得。", "corrected_sentence": "他做事很快。", "error_description": "“很快”作谓语时后面不能再加“得”，应说“做事很快”，去掉多余的“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
