INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20150, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词。表示程度随时间不断增加，变得更多或更强。", "primary_collocate": null, "pronunciation": "yuè lái yuè", "ipa": "ɥɛ˥˩ laɪ˧˥ ɥɛ˥˩", "syllable_count": 3, "sentences": [{"text": "天气越来越冷了。", "target_word": "越来越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的汉语越来越好。", "target_word": "越来越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的人越来越多。", "target_word": "越来越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得越来越快。", "target_word": "越来越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的车越来越多了。", "target_word": "越来越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们越来越高了。", "target_word": "越来越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，风越来越大了。", "target_word": "越来越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌越来越好听。", "target_word": "越来越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我越来越喜欢这个城市。", "target_word": "越来越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近工作越来越忙，我很累。", "target_word": "越来越", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "越来越：程度随时间不断增加，变得更多或更强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f82c8ae-82ab-4595-b449-235c22ee33c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20150, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "越来越", "is_correct": true, "explanation": "“越来越”表示程度随时间不断增加，与“天气冷了”的变化相符。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示持续不变，与“冷了”的变化相冲突。"}, {"text": "并", "is_correct": false, "explanation": "搭配：“并”一般与否定词连用，不能直接修饰肯定的“冷了”这一变化。"}, {"text": "总是", "is_correct": false, "explanation": "搭配：“总是”多修饰习惯性动作，不能修饰“冷了”这种状态变化。"}], "explanations": {"越来越": "“越来越”表示程度随时间不断增加，与“天气冷了”的变化相符。", "始终": "语义：“始终”表示持续不变，与“冷了”的变化相冲突。", "并": "搭配：“并”一般与否定词连用，不能直接修饰肯定的“冷了”这一变化。", "总是": "搭配：“总是”多修饰习惯性动作，不能修饰“冷了”这种状态变化。"}, "sentence_index": 0, "correct_answer": "越来越"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这学期的作业比上学期越来越多。", "explanation": "这里应该直接比较或用〈更〉。“越来越”表示随时间推移的变化，不用于两者之间的比较。"}, {"text": "这次考试他越来越及格了。", "explanation": "这里应该用〈终于〉。〈越来越〉表示逐步加深的变化，“及格”是一次性的结果，不能渐进，应用〈终于〉。"}, {"text": "他越来越是我的朋友了。", "explanation": "这里应该用〈成为〉。〈越来越〉表示程度逐步变化，不能修饰判断动词〈是〉；表示变成某种身份要用〈成为〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "越来越", "is_correct": true, "explanation": "“越来越”表示风力逐渐增强，与“天黑了，风大了”的渐进变化相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不定时、少有地发生，与风持续变大的渐进义相反。"}, {"text": "只好", "is_correct": false, "explanation": "搭配：“只好”后接动作或无奈的选择，不能直接接“大了”这样的变化。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：“仍然”表示状态延续不变，与风逐渐变大的递增义冲突。"}], "explanations": {"越来越": "“越来越”表示风力逐渐增强，与“天黑了，风大了”的渐进变化相符。", "偶尔": "语义：“偶尔”表示不定时、少有地发生，与风持续变大的渐进义相反。", "只好": "搭配：“只好”后接动作或无奈的选择，不能直接接“大了”这样的变化。", "仍然": "语义：“仍然”表示状态延续不变，与风逐渐变大的递增义冲突。"}, "sentence_index": 6, "correct_answer": "越来越"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天越来越买了一本书。", "explanation": "这里应该直接用“买了一本书”。〈越来越〉表示逐步加深的变化，不能用于一次性的动作。"}, {"text": "他昨天越来越迟到了一次。", "explanation": "〈越来越〉表示持续的渐进变化，不能用于一次性的事件，这里应改用〈又〉或〈再〉。"}, {"text": "这本书越来越在桌子上。", "explanation": "这里不能用〈越来越〉修饰表示位置的〈在〉。〈越来越〉只用于可以逐步变化的状态或程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的汉语越来越的流利。", "corrected_sentence": "他的汉语越来越流利。", "error_description": "错误：“越来越”后不能加“的”，应直接接形容词，写作“越来越流利”，不写“越来越的流利”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说话越来越慢着。", "corrected_sentence": "他说话越来越慢了。", "error_description": "错误：“越来越慢着”，句末应用“了”表示变化的结果，写作“越来越慢了”；“着”表示持续状态，与“越来越”表示的渐进变化不相容。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
