INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20152, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "石头是很硬的东西，在地上可以捡到。", "primary_collocate": null, "pronunciation": "shí tou", "ipa": "ʂɻ̩˧˥ tʰoʊ̯", "syllable_count": 2, "sentences": [{"text": "地上有一块大石头。", "target_word": "石头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他捡起一块石头扔进河里。", "target_word": "石头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石头又大又硬。", "target_word": "石头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在河边找小石头。", "target_word": "石头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路上的石头很多，走路要小心。", "target_word": "石头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的鞋里进了一块小石头。", "target_word": "石头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用石头把门挡住了。", "target_word": "石头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头太重了，我一个人搬不动。", "target_word": "石头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很清，能看见水里的石头。", "target_word": "石头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座桥是用石头做的。", "target_word": "石头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "石頭", "label": "繁体"}], "register": "口语", "sense_fingerprint": "构成山岩、地上随处可见的坚硬块状物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76649259-ba21-4681-8829-56e282963d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": true, "explanation": "正确：“石头”指地上的坚硬石块，“一块大石头”语义通顺。"}, {"text": "云", "is_correct": false, "explanation": "语义：云在天上，不会落在地上成为“一块”。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：树叶以“片”计量，说“一块大树叶”不地道。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”是广阔的空间，不能用“一块”计量。"}], "explanations": {"石头": "正确：“石头”指地上的坚硬石块，“一块大石头”语义通顺。", "云": "语义：云在天上，不会落在地上成为“一块”。", "树叶": "搭配：树叶以“片”计量，说“一块大树叶”不地道。", "天空": "语义：“天空”是广阔的空间，不能用“一块”计量。"}, "sentence_index": 0, "correct_answer": "石头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在河边找一只小石头。", "explanation": "这里量词应为〈块〉。“只”用于动物，石头这类块状物应用“块”。"}, {"text": "孩子们在河边找一条小石头。", "explanation": "这里量词应为〈块〉。“条”用于细长的东西，小石头不用“条”。"}, {"text": "孩子们在河边找一座小石头。", "explanation": "这里量词应为〈块〉。“座”用于山、房屋等大型物体，小石头不用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": true, "explanation": "正确：“石头”指块状的硬物，“用石头把门挡住”语义通顺。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见摸不着，不能用来挡门。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“挡住”的工具要是实体，不能用“声音”挡门。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪不能挡门，“用眼泪挡门”说不通。"}], "explanations": {"石头": "正确：“石头”指块状的硬物，“用石头把门挡住”语义通顺。", "空气": "语义：空气看不见摸不着，不能用来挡门。", "声音": "搭配：“挡住”的工具要是实体，不能用“声音”挡门。", "眼泪": "语义：眼泪不能挡门，“用眼泪挡门”说不通。"}, "sentence_index": 6, "correct_answer": "石头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给他的腿打上了石头。", "explanation": "这里应该用〈石膏〉。固定骨折部位的材料叫石膏，“石头”是天然的石块，不能用来打在腿上。"}, {"text": "河面上结了一层厚厚的石头。", "explanation": "这里应该用〈冰〉。“结”指水凝固成冰，石头不会结成一层，应说“结了一层厚厚的冰”。"}, {"text": "她吃了一个红红的石头。", "explanation": "这里应该用〈石榴〉。石榴是一种红色的水果，“石头”是石块，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从地上捡起一只石头。", "corrected_sentence": "他从地上捡起一块石头。", "error_description": "量词错误：“石头”应搭配量词“块”，不能用“只”（“只”用于动物等）。正确说法是“一块石头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河边的石头们很光滑。", "corrected_sentence": "河边的石头很光滑。", "error_description": "“们”不能加在“石头”后。石头是物体，表示多个时直接用“一些”或数量词，不加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
