INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20154, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "读书就是看一本书。", "primary_collocate": null, "pronunciation": "dú shū", "ipa": "tu˧˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "我喜欢晚上在家读书。", "target_word": "读书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天睡觉前读书半小时。", "target_word": "读书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常常去图书馆读书。", "target_word": "读书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷坐在窗边读书，很安静。", "target_word": "读书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在公园里安静地读书。", "target_word": "读书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，我喜欢喝茶读书。", "target_word": "读书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坐在沙发上读书，不喜欢听音乐。", "target_word": "读书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在读书吗？我不想吵你。", "target_word": "读书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最近很忙，没有时间读书。", "target_word": "读书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈坐在火车上读书，一路上都没有玩手机。", "target_word": "读书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "读过书", "label": "体标"}, {"form": "读读书", "label": "重叠"}, {"form": "读书人", "label": "复合"}, {"form": "读书会", "label": "复合"}, {"form": "讀書", "label": "繁体"}], "register": "中性", "sense_fingerprint": "拿着书阅读、看书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb662756-0b78-4edf-9c5e-051c04c57dff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20154, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "读书", "is_correct": true, "explanation": "读书指拿着书阅读，符合“在家”的语境，句意通顺。"}, {"text": "逛街", "is_correct": false, "explanation": "语义：逛街要出门，与“在家”矛盾，“晚上在家逛街”句意不通。"}, {"text": "登山", "is_correct": false, "explanation": "语义：登山要到山上去，与“在家”矛盾，句意不通。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“出差”指离开常住地去外地，与“在家”搭配不当。"}], "explanations": {"读书": "读书指拿着书阅读，符合“在家”的语境，句意通顺。", "逛街": "语义：逛街要出门，与“在家”矛盾，“晚上在家逛街”句意不通。", "登山": "语义：登山要到山上去，与“在家”矛盾，句意不通。", "出差": "搭配：“出差”指离开常住地去外地，与“在家”搭配不当。"}, "sentence_index": 0, "correct_answer": "读书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在北京大学读书，学的是计算机。", "explanation": "这里的“读书”表示求学、上学，是另一个意思，不是“看一本书”。"}, {"text": "他每天八点就去公司读书。", "explanation": "这里应该用〈上班〉。读书指阅读或求学，去公司工作要说上班。"}, {"text": "她高中毕业后去了国外读书。", "explanation": "这里的“读书”表示求学，是另一个意思，不是“看一本书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "读书", "is_correct": true, "explanation": "读书指阅读，与“不喜欢听音乐”的安静状态相符，句意通顺。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：跑步要站起来活动，与“坐在沙发上”矛盾，句意不通。"}, {"text": "做饭", "is_correct": false, "explanation": "语义：做饭要在厨房里进行，与“坐在沙发上”矛盾，句意不通。"}, {"text": "洗碗", "is_correct": false, "explanation": "语义：洗碗要站在水池边，与“坐在沙发上”矛盾，句意不通。"}], "explanations": {"读书": "读书指阅读，与“不喜欢听音乐”的安静状态相符，句意通顺。", "跑步": "语义：跑步要站起来活动，与“坐在沙发上”矛盾，句意不通。", "做饭": "语义：做饭要在厨房里进行，与“坐在沙发上”矛盾，句意不通。", "洗碗": "语义：洗碗要站在水池边，与“坐在沙发上”矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "读书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在学校读书，周末打工。", "explanation": "这里的“读书”表示上学学习，是另一个意思，不是“看一本书”。"}, {"text": "教练让运动员每天去大学读书。", "explanation": "这里的“读书”表示求学，是另一个意思，不是“看一本书”。"}, {"text": "他们每天下午在补习班读书。", "explanation": "这里的“读书”表示上课学习，是另一个意思，不是“看一本书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小时候读书了很多书。", "corrected_sentence": "他小时候读了很多书。", "error_description": "错误在“读书”的离合用法：“读书”是离合词，带宾语时要拆开，应说“读了很多书”，不能说“读书了很多书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她读书得很专心。", "corrected_sentence": "她读书读得很专心。", "error_description": "错误在补语结构：“读书”后接补语时要重复动词，应说“读书读得很专心”，少了第二个“读”就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
