INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20162, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "知识就是你知道的东西。", "primary_collocate": null, "pronunciation": "zhī shi", "ipa": "ʈʂɻ̩˥ ʂɻ̩", "syllable_count": 2, "sentences": [{"text": "读书可以学到很多知识。", "target_word": "知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他知识很多，什么都知道。", "target_word": "知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上教给我们新知识。", "target_word": "知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学一点历史知识。", "target_word": "知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有很多有用的知识。", "target_word": "知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多科学知识。", "target_word": "知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有丰富的知识，所以大家都喜欢问他。", "target_word": "知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多看书，你的知识会越来越多。", "target_word": "知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习新知识让我很高兴。", "target_word": "知识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的医学知识让大家很放心。", "target_word": "知识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "知识分子", "label": "复合词"}, {"form": "知识面", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人通过学习或经验知道的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b8f789-626d-40d7-a308-633398a91259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20162, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "知识", "is_correct": true, "explanation": "正确：知识（zhī shi），指人通过学习或经验知道的内容。"}, {"text": "只是", "is_correct": false, "explanation": "只是（zhǐ shì）与知识（zhī shi）两个音节的声调都不同，意思是“仅仅”。"}, {"text": "致使", "is_correct": false, "explanation": "致使（zhì shǐ）与知识（zhī shi）两个音节的声调都不同，意思是“导致”。"}, {"text": "直视", "is_correct": false, "explanation": "直视（zhí shì）与知识（zhī shi）两个音节的声调都不同，意思是“笔直地看着”。"}], "explanations": {"知识": "正确：知识（zhī shi），指人通过学习或经验知道的内容。", "只是": "只是（zhǐ shì）与知识（zhī shi）两个音节的声调都不同，意思是“仅仅”。", "致使": "致使（zhì shǐ）与知识（zhī shi）两个音节的声调都不同，意思是“导致”。", "直视": "直视（zhí shì）与知识（zhī shi）两个音节的声调都不同，意思是“笔直地看着”。"}, "sentence_index": null, "correct_answer": "知识"}, "level_3": {"options": [{"text": "知识", "is_correct": true, "explanation": "正确：“学到”的对象是知识，与“读书”相合。"}, {"text": "钱", "is_correct": false, "explanation": "语义：钱不是通过读书学到的内容，与句意不符。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“学到”的宾语应是知识或本领，不能接“眼泪”。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头是材料，不能通过读书学到。"}], "explanations": {"知识": "正确：“学到”的对象是知识，与“读书”相合。", "钱": "语义：钱不是通过读书学到的内容，与句意不符。", "眼泪": "搭配：“学到”的宾语应是知识或本领，不能接“眼泪”。", "木头": "语义：木头是材料，不能通过读书学到。"}, "sentence_index": 0, "correct_answer": "知识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他学会了一本知识。", "explanation": "这里应该用〈些〉。“本”用于书籍等物品，“知识”不能用“本”来计量。"}, {"text": "我饿了，想吃一点知识。", "explanation": "这里应该用〈东西〉。“知识”表示所学的内容，不能吃，吃的要用〈东西〉。"}, {"text": "这座桥的知识很结实。", "explanation": "这里应该用〈材料〉。“知识”是抽象的，不能用“结实”来形容，说桥的坚固要用〈材料〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知识", "is_correct": true, "explanation": "正确：“丰富的知识”搭配自然，并能解释大家为什么喜欢问他。"}, {"text": "色彩", "is_correct": false, "explanation": "语义：色彩与“大家都喜欢问他”没有因果关系，句意不通。"}, {"text": "矿产", "is_correct": false, "explanation": "语义：矿产指地下资源，与“大家都喜欢问他”没有因果关系。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“丰富”一般不修饰“脾气”，说“丰富的脾气”不自然。"}], "explanations": {"知识": "正确：“丰富的知识”搭配自然，并能解释大家为什么喜欢问他。", "色彩": "语义：色彩与“大家都喜欢问他”没有因果关系，句意不通。", "矿产": "语义：矿产指地下资源，与“大家都喜欢问他”没有因果关系。", "脾气": "搭配：“丰富”一般不修饰“脾气”，说“丰富的脾气”不自然。"}, "sentence_index": 6, "correct_answer": "知识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在院子里种了很多知识。", "explanation": "这里应该用〈树〉。“知识”是抽象的内容，不能种植，种植的东西要用〈树〉。"}, {"text": "妈妈每天都在唱知识。", "explanation": "这里应该用〈歌〉。“唱”的对象是歌曲，不能与“知识”搭配。"}, {"text": "我们走的这条知识很宽。", "explanation": "这里应该用〈路〉。“知识”是抽象的内容，不能走，也不能说宽窄，应说〈路〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本词典收集了很多本知识。", "corrected_sentence": "这本词典收集了很多知识。", "error_description": "错误：“知识”前加了量词“本”。“本”用于书籍等，“知识”前不用量词，正确为“很多知识”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她掌握了丰富地知识。", "corrected_sentence": "她掌握了丰富的知识。", "error_description": "错误：修饰名词“知识”的成分用了“地”。“地”用于修饰动词，修饰名词要用“的”，正确为“丰富的知识”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
