INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20166, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20166, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出以前没有的东西。", "primary_collocate": null, "pronunciation": "fā míng", "ipa": "fa˥ mɪŋ˧˥", "syllable_count": 2, "sentences": [{"text": "谁发明了电话？", "target_word": "发明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国人很早就发明了纸。", "target_word": "发明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爱迪生发明了电灯。", "target_word": "发明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想发明一种新机器。", "target_word": "发明", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个孩子发明过一个小玩具。", "target_word": "发明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们为什么要发明筷子？", "target_word": "发明", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科学家发明了新的药。", "target_word": "发明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器是他三年前发明的。", "target_word": "发明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他发明了一种不用电的灯。", "target_word": "发明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爷爷发明了这种小工具。", "target_word": "发明", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "发明了", "label": "完成体"}, {"form": "发明过", "label": "经历体"}, {"form": "发明家", "label": "复合"}, {"form": "发明者", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：创造出以前没有的东西或方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebfe7736-19f5-4660-8550-caa3fb9fd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发明", "is_correct": true, "explanation": "发明：动词，表示做出以前没有的东西，与“电话”搭配，句子通顺。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“电话”搭配，句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指演唱，不能用于“电话”。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，不能带宾语“电话”。"}], "explanations": {"发明": "发明：动词，表示做出以前没有的东西，与“电话”搭配，句子通顺。", "吃": "搭配：“吃”不能与“电话”搭配，句子不通。", "唱": "语义：“唱”指演唱，不能用于“电话”。", "跑": "配价：“跑”是不及物动词，不能带宾语“电话”。"}, "sentence_index": 0, "correct_answer": "发明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哥伦布发明了美洲大陆。", "explanation": "这里应该用〈发现〉。“发明”指做出以前没有的东西，美洲大陆本来就存在，应用“发现”。"}, {"text": "工人在这里发明了石油。", "explanation": "这里应该用〈开采〉。石油是地下本来就有的资源，应用“开采”，不能用“发明”。"}, {"text": "他终于发明了丢失的钥匙。", "explanation": "这里应该用〈找到〉。丢失的钥匙早已存在，只是找不到，应说“找到”，不能说“发明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发明", "is_correct": true, "explanation": "发明：动词，表示做出以前没有的东西，与“新的药”搭配，句子通顺。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”不能与“药”搭配，句子不通。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带宾语“药”。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”不能与“药”搭配，句子不通。"}], "explanations": {"发明": "发明：动词，表示做出以前没有的东西，与“新的药”搭配，句子通顺。", "穿": "搭配：“穿”不能与“药”搭配，句子不通。", "哭": "配价：“哭”是不及物动词，不能带宾语“药”。", "戴": "搭配：“戴”不能与“药”搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "发明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位作家发明了一部小说。", "explanation": "这里应该用〈创作〉。“发明”指做出以前没有的器物或技术，文学作品应说“创作”或“写”。"}, {"text": "工人发明了那台坏掉的洗衣机。", "explanation": "这里应该用〈修理〉。机器已经坏了，应说“修理”，“发明”指做出以前没有的东西。"}, {"text": "农民发明了一片麦田。", "explanation": "这里应该用〈种植〉。麦田是种出来的，应说“种植”，不能说“发明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他发明着一种省电的机器。", "corrected_sentence": "他发明了一种省电的机器。", "error_description": "错误形式是“发明着”，正确形式是“发明了”。“发明”是瞬间完成的动作，不能用表示持续状态的“着”，应用完成体“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种方法是她五年前发明了的。", "corrected_sentence": "这种方法是她五年前发明的。", "error_description": "“是……的”结构中，“的”前面不能再加“了”，应说“发明的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
