INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20168, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用眼睛看文字或图画。", "primary_collocate": null, "pronunciation": "kàn shū", "ipa": "kʰan˥˩ ʂu˥", "syllable_count": 2, "sentences": [{"text": "我喜欢在图书馆看书。", "target_word": "看书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上都看书。", "target_word": "看书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在安静的房间里看书。", "target_word": "看书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常在家看书。", "target_word": "看书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷戴着眼镜看书。", "target_word": "看书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坐在窗边看书，没有听见我。", "target_word": "看书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们就在家看书吧。", "target_word": "看书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢看电影，喜欢看书。", "target_word": "看书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在床上看书，看着看着就睡了。", "target_word": "看书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在看书还是在写字？", "target_word": "看书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看了书", "label": "体标（了），离合"}, {"form": "看过书", "label": "体标（过），离合"}, {"form": "看看书", "label": "重叠"}, {"form": "看書", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用眼睛阅读书本上的文字或图画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b63a2c7-7b4b-4b6e-a491-5467c19626e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20168, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "看书", "is_correct": true, "explanation": "正确。“看书”指用眼睛阅读书本上的文字或图画。"}, {"text": "看树", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，「看树」意思是观看树木。"}, {"text": "看守", "is_correct": false, "explanation": "kān shǒu 与 kàn shū 声调、韵母不同，「看守」意思是照看、守卫。"}, {"text": "砍树", "is_correct": false, "explanation": "kǎn shù 与 kàn shū 声调不同，「砍树」意思是用刀斧砍伐树木。"}], "explanations": {"看书": "正确。“看书”指用眼睛阅读书本上的文字或图画。", "看树": "shù（第四声）与 shū（第一声）声调不同，「看树」意思是观看树木。", "看守": "kān shǒu 与 kàn shū 声调、韵母不同，「看守」意思是照看、守卫。", "砍树": "kǎn shù 与 kàn shū 声调不同，「砍树」意思是用刀斧砍伐树木。"}, "sentence_index": null, "correct_answer": "看书"}, "level_3": {"options": [{"text": "看书", "is_correct": true, "explanation": "正确。“看书”是动宾结构，指阅读书本，与“在图书馆”相合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：图书馆里没有游泳池，不能在那里游泳，句子读不通。"}, {"text": "洗书", "is_correct": false, "explanation": "搭配：“洗”不与“书”搭配，不能说洗书。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：图书馆要求安静，不适合唱歌，句子读不通。"}], "explanations": {"看书": "正确。“看书”是动宾结构，指阅读书本，与“在图书馆”相合。", "游泳": "语义：图书馆里没有游泳池，不能在那里游泳，句子读不通。", "洗书": "搭配：“洗”不与“书”搭配，不能说洗书。", "唱歌": "语义：图书馆要求安静，不适合唱歌，句子读不通。"}, "sentence_index": 0, "correct_answer": "看书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用鼻子看书，闻到了纸的味道。", "explanation": "这里应该用〈闻〉。“看书”要用眼睛看文字，用鼻子感知气味应说“闻”。"}, {"text": "我用脚看书，看得很清楚。", "explanation": "“看书”要用眼睛看文字或图画，用脚无法看书。"}, {"text": "我用耳朵看书，效果很好。", "explanation": "“看”指用眼睛看，“看书”不能用耳朵完成；用耳朵接收内容应说“听书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看书", "is_correct": true, "explanation": "正确。“看书”指阅读书本，下雨时在家做这件事相合。"}, {"text": "晒太阳", "is_correct": false, "explanation": "语义：下雨时不能晒太阳，与“下雨了”矛盾，句子读不通。"}, {"text": "吃雨", "is_correct": false, "explanation": "搭配：“吃”的宾语应为食物，不能说吃雨。"}, {"text": "打雪仗", "is_correct": false, "explanation": "语义：下雨时没有雪，不能打雪仗，句子读不通。"}], "explanations": {"看书": "正确。“看书”指阅读书本，下雨时在家做这件事相合。", "晒太阳": "语义：下雨时不能晒太阳，与“下雨了”矛盾，句子读不通。", "吃雨": "搭配：“吃”的宾语应为食物，不能说吃雨。", "打雪仗": "语义：下雨时没有雪，不能打雪仗，句子读不通。"}, "sentence_index": 6, "correct_answer": "看书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用舌头看书，尝到了纸的味道。", "explanation": "这里应该用〈品尝〉。“看书”要用眼睛阅读，用舌头感知味道应用“品尝”。"}, {"text": "她用后背看书，把字都看清了。", "explanation": "“看书”要用眼睛看文字或图画，用后背无法看书。"}, {"text": "他用牙齿看书，咬出了一个洞。", "explanation": "这里应该用〈咬〉。“看书”要用眼睛阅读，用牙齿接触书本并咬出洞不是阅读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我晚饭后常在沙发上看书了。", "corrected_sentence": "我晚饭后常在沙发上看书。", "error_description": "错误：“看书了”。应为“看书”。“了”表示动作已完成，与“常”表示的习惯性动作相矛盾，习惯性动作不加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他常家在看书。", "corrected_sentence": "他常在家看书。", "error_description": "错误：地点状语“在家”颠倒成“家在”。“在”是介词，须与“家”组成“在家”，引出动作的地点，并置于动词之前；“家在”不能作地点状语。应为“常在家看书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
