INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人本来就有的本事或本领。", "primary_collocate": null, "pronunciation": "cái néng", "ipa": "tsʰaɪ˧˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他在音乐上很有才能。", "target_word": "才能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师发现了这个孩子的才能。", "target_word": "才能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都有自己的才能。", "target_word": "才能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用自己的才能帮助了很多人。", "target_word": "才能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想找有才能的年轻人。", "target_word": "才能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的才能表现在画画上。", "target_word": "才能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王在工作中发挥了自己的才能。", "target_word": "才能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的才能让大家很佩服。", "target_word": "才能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师会帮学生发现自己的才能。", "target_word": "才能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一种才能，所以很会画画。", "target_word": "才能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "管理才能", "label": "复合词"}, {"form": "艺术才能", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人天生具有的本事、本领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a97e88-3abc-4912-87f4-f7c53757717e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "才能", "is_correct": true, "explanation": "正确：“有才能”指天生具有的本事，符合句意。"}, {"text": "钱", "is_correct": false, "explanation": "语义：“有钱”指有财富，“在音乐上很有钱”与句意不合。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“力气”指体力，不说“在音乐上很有力气”。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“有时间”指空闲，与句中说的能力方面不合。"}], "explanations": {"才能": "正确：“有才能”指天生具有的本事，符合句意。", "钱": "语义：“有钱”指有财富，“在音乐上很有钱”与句意不合。", "力气": "搭配：“力气”指体力，不说“在音乐上很有力气”。", "时间": "语义：“有时间”指空闲，与句中说的能力方面不合。"}, "sentence_index": 0, "correct_answer": "才能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位作家才能横溢。", "explanation": "这里应该用〈才华〉。“才华横溢”是固定说法，“才能”不与“横溢”搭配。"}, {"text": "这台机器的才能很强。", "explanation": "这里应该用〈性能〉。才能指人的本事，机器的能力要说性能。"}, {"text": "这道菜的才能很好，大家都爱吃。", "explanation": "这里应该用〈味道〉。才能指人的本事，菜好不好吃要说味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e44e0593-4a94-4af7-9478-59338c772782') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "才能", "is_correct": true, "explanation": "正确：“发挥自己的才能”是常见说法，符合句意。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“发挥”后接的是才能、作用、优势，不说“发挥脾气”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“发挥”不能与“房子”搭配，句中说的是能力的施展。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是物品，不能被“发挥”，与“工作中”的能力施展不合。"}], "explanations": {"才能": "正确：“发挥自己的才能”是常见说法，符合句意。", "脾气": "搭配：“发挥”后接的是才能、作用、优势，不说“发挥脾气”。", "房子": "搭配：“发挥”不能与“房子”搭配，句中说的是能力的施展。", "汽车": "语义：汽车是物品，不能被“发挥”，与“工作中”的能力施展不合。"}, "sentence_index": 6, "correct_answer": "才能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一块才能，所以很会画画。", "explanation": "这里量词用错。才能是抽象名词，不能用“块”，应说“一种才能”。"}, {"text": "她有一只才能，唱歌很好听。", "explanation": "这里量词用错。“只”用于动物或成对的物件，不用于才能，应说“一种才能”。"}, {"text": "老师发现了一颗才能。", "explanation": "这里量词用错。“颗”用于颗粒状的东西，才能是抽象的，应说“一种才能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e44e0593-4a94-4af7-9478-59338c772782') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很才能。", "corrected_sentence": "她很有才能。", "error_description": "错误：“很才能”。正确：“很有才能”。才能作谓语前要带动词“有”，省略“有”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e44e0593-4a94-4af7-9478-59338c772782') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师发现了这个学生的一条才能。", "corrected_sentence": "老师发现了这个学生的一种才能。", "error_description": "错误：“一条才能”。正确：“一种才能”。“条”用于细长的东西，才能是抽象的，应用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e44e0593-4a94-4af7-9478-59338c772782') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20174, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进", "is_correct": true, "explanation": "进与出构成反义，指从外到里，与“医生出了病房”正好相反。"}, {"text": "站", "is_correct": false, "explanation": "站不表示方向上的相反，与“出”不构成反义。"}, {"text": "唱", "is_correct": false, "explanation": "唱与“出”没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "睡与“出”没有反义关系。"}], "correct_answer": "进", "explanations": {"进": "进与出构成反义，指从外到里，与“医生出了病房”正好相反。", "站": "站不表示方向上的相反，与“出”不构成反义。", "唱": "唱与“出”没有反义关系。", "睡": "睡与“出”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20174, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入", "is_correct": true, "explanation": "入与出构成反义，指从外到里，与“我出了地铁站”正好相反。"}, {"text": "写", "is_correct": false, "explanation": "写与“出”没有反义关系。"}, {"text": "跳", "is_correct": false, "explanation": "跳与“出”没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "走与“出”没有反义关系，“走出”与“走”是同向的动作。"}], "correct_answer": "入", "explanations": {"入": "入与出构成反义，指从外到里，与“我出了地铁站”正好相反。", "写": "写与“出”没有反义关系。", "跳": "跳与“出”没有反义关系。", "走": "走与“出”没有反义关系，“走出”与“走”是同向的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20174, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从里面到外面。", "primary_collocate": null, "pronunciation": "chū", "ipa": "ʈʂʰu˥", "syllable_count": 1, "sentences": [{"text": "他出了教室，往操场走去。", "target_word": "出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们出了商店，天已经黑了。", "target_word": "出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车慢慢出了车站。", "target_word": "出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生出了病房，对家人笑了笑。", "target_word": "出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫出了家门，在院子里玩。", "target_word": "出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们出了学校，都很高兴。", "target_word": "出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从后门出，别走正门。", "target_word": "出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们出了城，路上的车就少了。", "target_word": "出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下课后，学生们一个一个出教室。", "target_word": "出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我出了地铁站，下起了大雨。", "target_word": "出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "出了", "label": "体标"}, {"form": "出过", "label": "体标"}, {"form": "出来", "label": "复合"}, {"form": "出去", "label": "复合"}, {"form": "出门", "label": "复合"}], "register": "中性", "sense_fingerprint": "从里面走到外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 小猫 (Zipf 3.7), 家门 (Zipf 3.74), 院子 (Zipf 3.93)']::text[], 'bb662756-0b78-4edf-9c5e-051c04c57dff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20174, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出", "is_correct": true, "explanation": "正确答案。出（chū）指从里面到外面。"}, {"text": "书", "is_correct": false, "explanation": "sh 与 ch 声母不同，声调相同，意思是书籍。"}, {"text": "猪", "is_correct": false, "explanation": "zh 与 ch 声母不同，声调相同，意思是猪。"}, {"text": "粗", "is_correct": false, "explanation": "c 与 ch 声母不同，声调相同，意思是粗细的粗。"}], "explanations": {"出": "正确答案。出（chū）指从里面到外面。", "书": "sh 与 ch 声母不同，声调相同，意思是书籍。", "猪": "zh 与 ch 声母不同，声调相同，意思是猪。", "粗": "c 与 ch 声母不同，声调相同，意思是粗细的粗。"}, "sentence_index": null, "correct_answer": "出"}, "level_3": {"options": [{"text": "出", "is_correct": true, "explanation": "出：从里面到外面，“出了教室”表示离开教室，句意正确。"}, {"text": "坐", "is_correct": false, "explanation": "配价：“坐”不能带“教室”作宾语，“坐了教室”不通。"}, {"text": "站", "is_correct": false, "explanation": "配价：“站”不能带“教室”作宾语，“站了教室”不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”与“往操场走去”的行动矛盾，句意不通。"}], "explanations": {"出": "出：从里面到外面，“出了教室”表示离开教室，句意正确。", "坐": "配价：“坐”不能带“教室”作宾语，“坐了教室”不通。", "站": "配价：“站”不能带“教室”作宾语，“站了教室”不通。", "睡": "语义：“睡”与“往操场走去”的行动矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们准时出了课。", "explanation": "这里应该用〈下〉。“下课”指一节课结束；“出”表示从里到外，不指课程结束，所以不说“出了课”。"}, {"text": "她今年出了一本新书。", "explanation": "这里的“出”表示出版，是另一个意思，不是“从里面到外面”。"}, {"text": "他跑完步，出了一身汗。", "explanation": "这里的“出”表示出汗，是另一个意思，不是“从里面到外面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出", "is_correct": true, "explanation": "出：从里面到外面，“从后门出”表示经由后门离开，句意正确。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”不表示经由门的移动，“从后门哭”句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”不能表示经由门的移动，“从后门吃”不通。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”不表示移动，“从后门笑”句意不通。"}], "explanations": {"出": "出：从里面到外面，“从后门出”表示经由后门离开，句意正确。", "哭": "语义：“哭”不表示经由门的移动，“从后门哭”句意不通。", "吃": "配价：“吃”不能表示经由门的移动，“从后门吃”不通。", "笑": "语义：“笑”不表示移动，“从后门笑”句意不通。"}, "sentence_index": 6, "correct_answer": "出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她出了一件新外套。", "explanation": "这里应该用〈穿〉。穿衣服要说“穿”，“出”表示从里到外，不用于穿衣。"}, {"text": "妈妈给孩子出了围巾。", "explanation": "这里应该用〈围〉。给别人围围巾要说“围”，不能用“出”。"}, {"text": "她出了帽子。", "explanation": "这里应该用〈戴〉。戴帽子要说“戴”，“出”不能用于戴东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们出来了校门，往公园走去。", "corrected_sentence": "孩子们出了校门，往公园走去。", "error_description": "补语错误：“出来”不能带处所宾语，表示离开校门时应说“出了校门”，不能说“出来了校门”，正确为“出了校门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她了出办公室，去吃午饭。", "corrected_sentence": "她出了办公室，去吃午饭。", "error_description": "错误在体标“了”的位置：“了”要放在动词“出”的后面，应说“出了办公室”，不能说“了出办公室”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
