INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20178, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西的样子或状态有了不同。", "primary_collocate": null, "pronunciation": "biàn", "ipa": "pjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "天气变了，快带伞。", "target_word": "变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的样子一点都没变。", "target_word": "变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，天气变暖了。", "target_word": "变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，声音也变了。", "target_word": "变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么变得这么高了？", "target_word": "变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶秋天会变黄。", "target_word": "变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街变得很干净。", "target_word": "变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法变了。", "target_word": "变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水变成了冰。", "target_word": "变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯变绿灯了，我们走吧。", "target_word": "变", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变了", "label": "体标"}, {"form": "变过", "label": "体标"}, {"form": "变成", "label": "复合"}, {"form": "变化", "label": "复合"}, {"form": "變", "label": "繁体"}], "register": "中性", "sense_fingerprint": "变：样子或状态发生不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09aebaf0-be95-4ef2-b319-0da839c40a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20178, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变", "is_correct": true, "explanation": "变：东西的样子或状态有了不同。"}, {"text": "边", "is_correct": false, "explanation": "biān（第一声）与 biàn（第四声）声调不同，意思是边。"}, {"text": "扁", "is_correct": false, "explanation": "biǎn（第三声）与 biàn（第四声）声调不同，意思是扁。"}, {"text": "片", "is_correct": false, "explanation": "piàn 与 biàn 声母不同（p 与 b），意思是片。"}, {"text": "面", "is_correct": false, "explanation": "miàn 与 biàn 声母不同（m 与 b），意思是面。"}], "explanations": {"变": "变：东西的样子或状态有了不同。", "边": "biān（第一声）与 biàn（第四声）声调不同，意思是边。", "扁": "biǎn（第三声）与 biàn（第四声）声调不同，意思是扁。", "片": "piàn 与 biàn 声母不同（p 与 b），意思是片。", "面": "miàn 与 biàn 声母不同（m 与 b），意思是面。"}, "sentence_index": null, "correct_answer": "变"}, "level_3": {"options": [{"text": "变", "is_correct": true, "explanation": "变：表示状态有了不同，这里指天气有了变化。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”是人的情绪，天气不会生气。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的主语须是能进食的生物，天气不能吃。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”需要说话的人，天气不能说话。"}], "explanations": {"变": "变：表示状态有了不同，这里指天气有了变化。", "生气": "语义：“生气”是人的情绪，天气不会生气。", "吃": "语义：“吃”的主语须是能进食的生物，天气不能吃。", "说": "配价：“说”需要说话的人，天气不能说话。"}, "sentence_index": 0, "correct_answer": "变"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上八点变学校。", "explanation": "这里应该用〈去〉。到某个地方要用“去”；“变”表示样子或状态有了不同，不表示移动到某处。"}, {"text": "我们把书变进了箱子。", "explanation": "这里应该用〈装〉。把东西放进箱子要用〈装〉，“变”不表示放入。"}, {"text": "她每天晚上给妈妈变电话。", "explanation": "这里应该用〈打〉。打电话是固定说法；“变”表示样子或状态的不同，不能和“电话”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20178, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "变", "is_correct": true, "explanation": "变：东西的样子或状态有了不同。"}, {"text": "电", "is_correct": false, "explanation": "diàn 与 biàn 声母不同（d 与 b），意思是电。"}, {"text": "半", "is_correct": false, "explanation": "bàn 比 biàn 少了介音 i，意思是一半。"}, {"text": "练", "is_correct": false, "explanation": "liàn 与 biàn 声母不同（l 与 b），意思是练习。"}], "explanations": {"变": "变：东西的样子或状态有了不同。", "电": "diàn 与 biàn 声母不同（d 与 b），意思是电。", "半": "bàn 比 biàn 少了介音 i，意思是一半。", "练": "liàn 与 biàn 声母不同（l 与 b），意思是练习。"}, "sentence_index": null, "correct_answer": "变"}, "level_3": {"options": [{"text": "变", "is_correct": true, "explanation": "变：表示状态有了不同，这里指街道变得干净。"}, {"text": "走", "is_correct": false, "explanation": "语义：“走”的主语须是人或动物，街道不会走。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃得很干净”形容吃的动作，街道不能吃。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱得很干净”说的是歌声，不能用来形容街道。"}], "explanations": {"变": "变：表示状态有了不同，这里指街道变得干净。", "走": "语义：“走”的主语须是人或动物，街道不会走。", "吃": "语义：“吃得很干净”形容吃的动作，街道不能吃。", "唱": "搭配：“唱得很干净”说的是歌声，不能用来形容街道。"}, "sentence_index": 6, "correct_answer": "变"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上起床后变牙。", "explanation": "这里应该用〈刷〉。清洁牙齿说“刷牙”；“变”表示样子或状态有了不同，不表示清洁。"}, {"text": "他在黑板上变了几个字。", "explanation": "这里应该用〈写〉。在黑板上留下文字要用“写”；“变”表示样子或状态的不同，不表示书写。"}, {"text": "爷爷坐在椅子上变报纸。", "explanation": "这里应该用〈看〉。阅读报纸说“看报纸”；“变”表示样子或状态的不同，不表示阅读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖水变了冰。", "corrected_sentence": "湖水变成了冰。", "error_description": "补语错误：“变”之后缺少结果补语“成”，应说“变成了冰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的脸色突然白变了。", "corrected_sentence": "他的脸色突然变白了。", "error_description": "语序错误：“变”与结果补语“白”的顺序颠倒。正确：“他的脸色突然变白了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
