INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20180, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示动作或变化进行得很慢，不着急。", "primary_collocate": null, "pronunciation": "màn màn", "ipa": "man⁵¹ man⁵¹", "syllable_count": 2, "sentences": [{"text": "你慢慢吃，不着急。", "target_word": "慢慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天慢慢黑了。", "target_word": "慢慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢地走进房间。", "target_word": "慢慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请慢慢说，我听不懂。", "target_word": "慢慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪慢慢变小了。", "target_word": "慢慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "慢慢来，别着急。", "target_word": "慢慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩慢慢长大了。", "target_word": "慢慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她慢慢打开了门。", "target_word": "慢慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我慢慢喜欢上了这个城市。", "target_word": "慢慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢走在路上。", "target_word": "慢慢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "慢慢地", "label": "复合"}], "register": "中性", "sense_fingerprint": "动作或变化缓慢进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f67254c-2b72-48f7-a62f-6cc95d11eae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "慢慢", "is_correct": true, "explanation": "正确。“慢慢”表示动作缓慢进行，与“不着急”的语境相符。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”表示速度高，与句中“不着急”的语境矛盾。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示催促、加快，与句中“不着急”矛盾。"}, {"text": "猛", "is_correct": false, "explanation": "搭配：“猛”多修饰用力或突然的动作，“猛吃”与“不着急”的语境不符。"}], "explanations": {"慢慢": "正确。“慢慢”表示动作缓慢进行，与“不着急”的语境相符。", "快": "语义：“快”表示速度高，与句中“不着急”的语境矛盾。", "赶紧": "语义：“赶紧”表示催促、加快，与句中“不着急”矛盾。", "猛": "搭配：“猛”多修饰用力或突然的动作，“猛吃”与“不着急”的语境不符。"}, "sentence_index": 0, "correct_answer": "慢慢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他慢慢地打了一个喷嚏。", "explanation": "“慢慢”表示动作或变化缓慢进行，“打喷嚏”是瞬间完成的动作，不能用“慢慢”修饰。"}, {"text": "门慢慢地砰的一声关上了。", "explanation": "“砰的一声”是瞬间发出的响声，与“慢慢”表示的缓慢过程矛盾。"}, {"text": "他慢慢地得了冠军。", "explanation": "“得冠军”是一次性完成的结果，不能用“慢慢”表示缓慢的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "慢慢", "is_correct": true, "explanation": "正确。“慢慢”表示变化缓慢进行，与“长大”搭配，表示逐渐长大。"}, {"text": "赶忙", "is_correct": false, "explanation": "语义：“赶忙”表示急急忙忙，与“长大”这种逐步的变化不相符。"}, {"text": "仔细", "is_correct": false, "explanation": "搭配：“仔细”多修饰认真做事的动作，不能修饰“长大”这种身体变化。"}, {"text": "认真", "is_correct": false, "explanation": "语义：“认真”形容态度，不能用来说明身体的成长变化。"}], "explanations": {"慢慢": "正确。“慢慢”表示变化缓慢进行，与“长大”搭配，表示逐渐长大。", "赶忙": "语义：“赶忙”表示急急忙忙，与“长大”这种逐步的变化不相符。", "仔细": "搭配：“仔细”多修饰认真做事的动作，不能修饰“长大”这种身体变化。", "认真": "语义：“认真”形容态度，不能用来说明身体的成长变化。"}, "sentence_index": 6, "correct_answer": "慢慢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他慢慢地冲出了房间。", "explanation": "“冲出”本身是急速跑出去的意思，与“慢慢”表示的缓慢矛盾。"}, {"text": "他慢慢地突然大笑起来。", "explanation": "“突然”表示出乎意料地发生，与“慢慢”表示的缓慢过程矛盾。"}, {"text": "他慢慢地一下子跳过了小河。", "explanation": "“一下子”表示很快完成，与“慢慢”表示的缓慢进行互相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷很慢慢地走下楼梯。", "corrected_sentence": "爷爷慢慢地走下楼梯。", "error_description": "“慢慢地”是表示方式的重叠副词，前面一般不能再加程度副词“很”，应去掉“很”，说“爷爷慢慢地走下楼梯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶慢慢得读完了报纸。", "corrected_sentence": "奶奶慢慢地读完了报纸。", "error_description": "“慢慢”修饰动词“读”，状语后应用“地”，不用“得”。“得”用在动词或形容词后引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
