INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20182, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "数量由少增多，东西或人的数目比原来增加了。", "primary_collocate": null, "pronunciation": "biàn duō", "ipa": "pjɛn˥˩ tuɔ˥", "syllable_count": 2, "sentences": [{"text": "下雨以后，路上的水变多了。", "target_word": "变多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷了，我家的衣服变多了。", "target_word": "变多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，家里的客人会变多。", "target_word": "变多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近我的作业变多了，每天都很忙。", "target_word": "变多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了周末，公园里的人变多了。", "target_word": "变多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，树上的小鸟变多了。", "target_word": "变多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的钱变多了，可是他不开心。", "target_word": "变多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，街上的灯变多了。", "target_word": "变多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，我喝的热水变多了。", "target_word": "变多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了一年汉语，我认识的字变多了。", "target_word": "变多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变多了", "label": "体标"}, {"form": "變多", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：数量由少变多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40c6bb68-9edb-4a24-ad31-cf0cde640a3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变多", "is_correct": true, "explanation": "正确。下雨以后路上的水增多，“变多”符合句意。"}, {"text": "变甜", "is_correct": false, "explanation": "搭配：“水”不能说“变甜”，“甜”指味道，与句意不合。"}, {"text": "变软", "is_correct": false, "explanation": "搭配：“软”指质地，不能用来说水的数量变化。"}, {"text": "变轻", "is_correct": false, "explanation": "语义：“轻”指重量，与下雨后水的增多无关。"}], "explanations": {"变多": "正确。下雨以后路上的水增多，“变多”符合句意。", "变甜": "搭配：“水”不能说“变甜”，“甜”指味道，与句意不合。", "变软": "搭配：“软”指质地，不能用来说水的数量变化。", "变轻": "语义：“轻”指重量，与下雨后水的增多无关。"}, "sentence_index": 0, "correct_answer": "变多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的质量变多了。", "explanation": "这里应该用〈提高〉。「变多」只用于数量增加，质量的变化要说「提高」。"}, {"text": "天气变多了，今天的太阳很好。", "explanation": "这里应该用〈转晴〉。「变多」只用于数量，天气好转要说「转晴」。"}, {"text": "他的个子变多了。", "explanation": "这里应该用〈长高〉。“变多”用于数量，身高的变化要说“长高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变多", "is_correct": true, "explanation": "正确。“他的钱变多了”与后半句“他不开心”形成转折，符合句意。"}, {"text": "变热", "is_correct": false, "explanation": "语义：“热”指温度，与钱的数量无关。"}, {"text": "变圆", "is_correct": false, "explanation": "语义：“圆”指形状，不能用来说钱的变化。"}, {"text": "变香", "is_correct": false, "explanation": "搭配：“香”形容气味，不能用来形容钱的数量变化。"}], "explanations": {"变多": "正确。“他的钱变多了”与后半句“他不开心”形成转折，符合句意。", "变热": "语义：“热”指温度，与钱的数量无关。", "变圆": "语义：“圆”指形状，不能用来说钱的变化。", "变香": "搭配：“香”形容气味，不能用来形容钱的数量变化。"}, "sentence_index": 6, "correct_answer": "变多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的价格变多了。", "explanation": "这里应该用〈涨〉。价格上升要说“涨”，“变多”只用于数量增加。"}, {"text": "我的脾气变多了。", "explanation": "这里应该用〈变坏〉。脾气的变化要说“变坏”或“变好”，“变多”只用于数量。"}, {"text": "屋里的温度变多了。", "explanation": "这里应该用〈升高〉。温度的上升要说「升高」，「变多」只用于数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最近路上的车变多了了。", "corrected_sentence": "最近路上的车变多了。", "error_description": "错误：「变多了」已经带了「了」，句末不能再加一个「了」。正确是「最近路上的车变多了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年的游客很变多了。", "corrected_sentence": "今年的游客变多了。", "error_description": "错误：「很」修饰形容词或状态，不能修饰动词「变多」。正确是「变多了」，应说「今年的游客变多了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20184, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贵", "is_correct": true, "explanation": "“贵”与“便宜”意思相反，指价钱高、花钱多。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”说卫生状况，与价钱高低没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”说声音或环境，与“便宜”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容人的智力，与“便宜”没有反义关系。"}], "correct_answer": "贵", "explanations": {"贵": "“贵”与“便宜”意思相反，指价钱高、花钱多。", "干净": "“干净”说卫生状况，与价钱高低没有反义关系。", "安静": "“安静”说声音或环境，与“便宜”没有反义关系。", "聪明": "“聪明”形容人的智力，与“便宜”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1a3ec7-449c-48e0-8566-4389d94b2815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20184, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贵", "is_correct": true, "explanation": "“贵”与“便宜”意思相反，指价钱高、花钱多。"}, {"text": "勇敢", "is_correct": false, "explanation": "“勇敢”形容人的品质，与“便宜”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”说排列或外观规整，与价钱高低没有反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”说物品耐用，与“便宜”没有反义关系。"}], "correct_answer": "贵", "explanations": {"贵": "“贵”与“便宜”意思相反，指价钱高、花钱多。", "勇敢": "“勇敢”形容人的品质，与“便宜”没有反义关系。", "整齐": "“整齐”说排列或外观规整，与价钱高低没有反义关系。", "结实": "“结实”说物品耐用，与“便宜”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1a3ec7-449c-48e0-8566-4389d94b2815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20184, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西花的钱少。", "primary_collocate": null, "pronunciation": "pián yi", "ipa": "pʰiɛn˧˥ i", "syllable_count": 2, "sentences": [{"text": "这件衣服很便宜，只要三十块。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的水果比市场便宜。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买便宜一点儿的手机。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜又好吃又便宜。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋太便宜了，我买了两双。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种青菜在早市比较便宜。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里的旧书很便宜。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁比打车便宜多了。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子不便宜，要八十块。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这家店的东西真便宜。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "便宜了", "label": "体标"}], "register": "口语", "sense_fingerprint": "东西价格低，花钱少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b5a3a5a-e3c1-4dad-8df2-068a10a8f807') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便宜", "is_correct": true, "explanation": "“便宜”说价钱低，与“只要三十块”相符。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容声音或环境，不能形容衣服的价钱。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，衣服不能是甜的，句意不通。"}, {"text": "辛苦", "is_correct": false, "explanation": "搭配：“辛苦”形容人的劳累，不用来形容衣服。"}], "explanations": {"便宜": "“便宜”说价钱低，与“只要三十块”相符。", "安静": "语义：“安静”形容声音或环境，不能形容衣服的价钱。", "甜": "语义：“甜”形容味道，衣服不能是甜的，句意不通。", "辛苦": "搭配：“辛苦”形容人的劳累，不用来形容衣服。"}, "sentence_index": 0, "correct_answer": "便宜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市离我家很便宜。", "explanation": "这里应该用〈方便〉。便宜说价钱低；说距离近、去那里省事要用方便。"}, {"text": "这个问题很便宜，三言两语就解决了。", "explanation": "这里应该用〈简单〉。便宜说价钱低；说事情容易做、不费力要用简单。"}, {"text": "这座城市的气候很便宜。", "explanation": "这里应该用〈宜人〉。便宜说价钱低；形容气候、环境舒适要用宜人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1a3ec7-449c-48e0-8566-4389d94b2815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便宜", "is_correct": true, "explanation": "“便宜”说价钱低，书店里的旧书价钱低，句意通顺。"}, {"text": "新鲜", "is_correct": false, "explanation": "语义：“新鲜”与“旧书”矛盾，不能说旧书新鲜。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”形容人或生物，不用来形容书。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”形容味道，书没有辣味，句意不通。"}], "explanations": {"便宜": "“便宜”说价钱低，书店里的旧书价钱低，句意通顺。", "新鲜": "语义：“新鲜”与“旧书”矛盾，不能说旧书新鲜。", "年轻": "搭配：“年轻”形容人或生物，不用来形容书。", "辣": "语义：“辣”形容味道，书没有辣味，句意不通。"}, "sentence_index": 6, "correct_answer": "便宜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这款软件操作很便宜。", "explanation": "这里应该用〈便捷〉。便宜说价钱低；说操作简单、使用快捷要用便捷。"}, {"text": "他的汉字写得很便宜。", "explanation": "这里应该用〈漂亮〉。便宜说价钱低；说字写得好看要用漂亮。"}, {"text": "这次考试的时间很便宜，大家都做完了。", "explanation": "这里应该用〈充足〉。便宜只说价钱低，不能形容时间；说时间够用要用充足。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1a3ec7-449c-48e0-8566-4389d94b2815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些了水果今天便宜了。", "corrected_sentence": "这些水果今天便宜了。", "error_description": "“了”的位置错误：“了”不能插在定语“这些”和名词“水果”之间，删去这个多余的“了”即可。句末的“了”表示变化，应保留。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1a3ec7-449c-48e0-8566-4389d94b2815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的衣服比商场便宜多得。", "corrected_sentence": "这家店的衣服比商场便宜得多。", "error_description": "错误：程度补语的语序错误，“便宜多得”应为“便宜得多”，“得”要紧跟动词或形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1a3ec7-449c-48e0-8566-4389d94b2815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
