INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20188, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过学习获得知识或技能。", "primary_collocate": null, "pronunciation": "xué", "ipa": "ɕɥɛ˧˥", "syllable_count": 1, "sentences": [{"text": "他白天上班，晚上去夜校学英语。", "target_word": "学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想学好数学，就要多看书，多做题。", "target_word": "学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在国外学法律，明年才回来。", "target_word": "学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟老师学画画，每周去两次。", "target_word": "学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在课堂上认真听老师讲，学得很快。", "target_word": "学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很难，我学了三个月才学完。", "target_word": "学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没学过日语，所以听不懂他们说话。", "target_word": "学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去北京学中医。", "target_word": "学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹上课时认真听讲，下课后看书，学得很好。", "target_word": "学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了两年钢琴，可是弹得不太好。", "target_word": "学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "学了", "label": "完成体"}, {"form": "学过", "label": "经验体"}, {"form": "学着", "label": "持续体"}, {"form": "学学", "label": "重叠"}], "register": "中性", "sense_fingerprint": "通过学习获得知识或技能，如学英语、学钢琴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4848e3-df86-4870-9771-0c70385a07a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20188, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "学", "is_correct": true, "explanation": "正确：“学”（第二声）指学习知识或技能，与“学英语”一致。"}, {"text": "雪", "is_correct": false, "explanation": "xuě（第三声）与 xué（第二声）声调不同，意思是雪。"}, {"text": "血", "is_correct": false, "explanation": "xuè（第四声）与 xué（第二声）声调不同，意思是血。"}, {"text": "靴", "is_correct": false, "explanation": "xuē（第一声）与 xué（第二声）声调不同，意思是靴子。"}], "explanations": {"学": "正确：“学”（第二声）指学习知识或技能，与“学英语”一致。", "雪": "xuě（第三声）与 xué（第二声）声调不同，意思是雪。", "血": "xuè（第四声）与 xué（第二声）声调不同，意思是血。", "靴": "xuē（第一声）与 xué（第二声）声调不同，意思是靴子。"}, "sentence_index": null, "correct_answer": "学"}, "level_3": {"options": [{"text": "学", "is_correct": true, "explanation": "正确：“学英语”指在夜校学习英语，与“夜校”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：英语不能吃，“吃英语”与句意矛盾。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的对象是商品，不能说“买英语”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料等液体，不能说“喝英语”。"}], "explanations": {"学": "正确：“学英语”指在夜校学习英语，与“夜校”相符。", "吃": "语义：英语不能吃，“吃英语”与句意矛盾。", "买": "搭配：“买”的对象是商品，不能说“买英语”。", "喝": "搭配：“喝”的对象是饮料等液体，不能说“喝英语”。"}, "sentence_index": 0, "correct_answer": "学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天认真学作业，很快就能完成。", "explanation": "这里应该用〈做〉。学指学习知识或技能，完成作业要说做作业。"}, {"text": "我每天在家学电视剧，直到很晚才睡。", "explanation": "这里应该用〈看〉。学指学习知识或技能，观看电视剧要说看，不能说学。"}, {"text": "我每天早上在家学报纸，了解新闻。", "explanation": "这里应该用〈看〉。学指学习知识或技能，阅读报纸要说看报纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学", "is_correct": true, "explanation": "正确：“没学过日语”指从未学习过日语，与“听不懂”的因果相符。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”的对象是具体的东西，不能说“切日语”，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”一般用于衣物等，不能说“洗日语”。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”是掘取具体物体，不能说“挖日语”，与句意矛盾。"}], "explanations": {"学": "正确：“没学过日语”指从未学习过日语，与“听不懂”的因果相符。", "切": "语义：“切”的对象是具体的东西，不能说“切日语”，句意不通。", "洗": "搭配：“洗”一般用于衣物等，不能说“洗日语”。", "挖": "语义：“挖”是掘取具体物体，不能说“挖日语”，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师每天认真学课，给我们讲得很清楚。", "explanation": "这里应该用〈教〉。学指学习知识或技能，老师向学生传授课程要说教，不能说学课。"}, {"text": "同学们每天认真学讲座，老师很满意。", "explanation": "这里应该用〈听〉。学指学习知识，参加讲座要说听讲座，不能说学讲座。"}, {"text": "他这次数学学了一百分，全班都很惊讶。", "explanation": "这里应该用〈考〉。学指学习知识，取得考试成绩要说考，不能说学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹学钢琴学很快。", "corrected_sentence": "妹妹学钢琴学得很快。", "error_description": "“学很快”应为“学得很快”：程度补语前要用“得”，漏掉“得”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我三个月就学了完法语。", "corrected_sentence": "我三个月就学完了法语。", "error_description": "“学了完”应为“学完了”：结果补语“完”要紧跟动词，“了”放在“完”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
