INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20190, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有足够的钱，能够买下某样东西。", "primary_collocate": null, "pronunciation": "mǎi de qǐ", "ipa": "maɪ˨˩ tɤ tɕʰi˨˩", "syllable_count": 3, "sentences": [{"text": "我买得起这本书。", "target_word": "买得起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他有钱，买得起车。", "target_word": "买得起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你买得起这么大的房子吗？", "target_word": "买得起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一杯水很便宜，谁都买得起。", "target_word": "买得起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我现在买得起新电脑了。", "target_word": "买得起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服不贵，你买得起。", "target_word": "买得起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么多钱，你真的买得起吗？", "target_word": "买得起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "普通人也买得起这种手机。", "target_word": "买得起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她工作了三年，终于买得起房子了。", "target_word": "买得起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他现在还买得起一辆好车。", "target_word": "买得起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "买不起", "label": "否定形式"}], "register": "口语", "sense_fingerprint": "动词：有足够的钱，能够买下某样东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9421cf6-24de-499f-a0bb-a94d3893ac19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "买得起", "is_correct": true, "explanation": "正确：买得起表示有足够的钱买下这本书，与句意相符。"}, {"text": "吃得起", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃这本书。"}, {"text": "住得起", "is_correct": false, "explanation": "语义：“住”指居住，书不能住，句子说不通。"}, {"text": "穿得起", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物，不能说穿这本书。"}], "explanations": {"买得起": "正确：买得起表示有足够的钱买下这本书，与句意相符。", "吃得起": "搭配：“吃”的对象是食物，不能说吃这本书。", "住得起": "语义：“住”指居住，书不能住，句子说不通。", "穿得起": "搭配：“穿”的对象是衣物，不能说穿这本书。"}, "sentence_index": 0, "correct_answer": "买得起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买得起一个小时。", "explanation": "这里应该用〈抽得出〉。时间不能用钱买，“买得起”只用于能用钱买下的东西。"}, {"text": "我买得起这笔学费。", "explanation": "这里应该用〈付得起〉。买得起的对象是可以买下的东西，不能用来说付学费。"}, {"text": "他买得起这份责任。", "explanation": "这里应该用〈担得起〉。责任不能被买，买得起只用于说能买下东西，不用于承担责任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "买得起", "is_correct": true, "explanation": "正确：买得起表示有足够的钱买下这么贵的东西，与“这么多钱”的语境相符。"}, {"text": "看得起", "is_correct": false, "explanation": "语义：“看得起”指尊重某人，不能用来说钱够不够。"}, {"text": "对不起", "is_correct": false, "explanation": "语义：“对不起”是道歉用语，放在句中说不通。"}, {"text": "想得起", "is_correct": false, "explanation": "语义：“想得起”指能记起来，与花钱买东西无关。"}], "explanations": {"买得起": "正确：买得起表示有足够的钱买下这么贵的东西，与“这么多钱”的语境相符。", "看得起": "语义：“看得起”指尊重某人，不能用来说钱够不够。", "对不起": "语义：“对不起”是道歉用语，放在句中说不通。", "想得起": "语义：“想得起”指能记起来，与花钱买东西无关。"}, "sentence_index": 6, "correct_answer": "买得起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买得起一家五口。", "explanation": "这里应该用〈养得起〉。买得起用于说能买下东西，不能用来说供养一家人。"}, {"text": "这次损失，他买得起。", "explanation": "这里应该用〈赔得起〉。买得起的对象是可买的东西，损失不能买，这里要说能承担赔偿。"}, {"text": "我买得起他的建议，就接受了。", "explanation": "这里应该用〈接受〉。买得起用于能花钱买下的东西，建议不能买，要说接受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他工资很高，买得起来一辆车。", "corrected_sentence": "他工资很高，买得起一辆车。", "error_description": "补语错误：“买得起”是可能补语，“起”后面不能再加“来”。错误形式是“买得起来”，正确形式是“买得起一辆车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆车很好，我们买得起过。", "corrected_sentence": "这辆车很好，我们买得起。", "error_description": "体标错误：“买得起”已表示有能力买下，后面不能再加“过”，应说“我们买得起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
