INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20192, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20192, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事情变得更好。", "primary_collocate": null, "pronunciation": "gǎi jìn", "ipa": "kai˨˩˦ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "公司正在改进产品的质量。", "target_word": "改进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师建议我改进写字的方法。", "target_word": "改进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法还需要改进。", "target_word": "改进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们改进了学习方法。", "target_word": "改进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语还有很多地方要改进。", "target_word": "改进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们改进了机器，工作快多了。", "target_word": "改进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得这家餐厅应该改进什么？", "target_word": "改进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都在改进自己的方法。", "target_word": "改进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求大家改进服务。", "target_word": "改进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这个计划改进了一下。", "target_word": "改进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改进了", "label": "体标"}, {"form": "改进过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把已有的事物改得更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09aebaf0-be95-4ef2-b319-0da839c40a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改进", "is_correct": true, "explanation": "改进：正确答案，表示把产品质量变得更好，句意自然。"}, {"text": "偷", "is_correct": false, "explanation": "语义：偷是窃取他人财物，不能用来改善产品质量。"}, {"text": "骗", "is_correct": false, "explanation": "搭配：骗的对象多为人，不能与“质量”搭配作宾语。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是牙齿的动作，不能用来改变产品质量，句意不通。"}], "explanations": {"改进": "改进：正确答案，表示把产品质量变得更好，句意自然。", "偷": "语义：偷是窃取他人财物，不能用来改善产品质量。", "骗": "搭配：骗的对象多为人，不能与“质量”搭配作宾语。", "咬": "语义：咬是牙齿的动作，不能用来改变产品质量，句意不通。"}, "sentence_index": 0, "correct_answer": "改进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子在这一年改进了不少。", "explanation": "这里应该用〈长〉。个子变高要说“长”，“改进”指使事物变得更好，不能用于身高。"}, {"text": "我们改进了浪费。", "explanation": "这里应该用〈减少〉。改进用于事物的优化，浪费要用“减少”，不能说“改进浪费”。"}, {"text": "老师改进了错误。", "explanation": "这里应该用〈纠正〉。改进指使事物变好，错误要用“纠正”，不能说“改进错误”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改进", "is_correct": true, "explanation": "改进：正确答案，“你觉得这家餐厅应该改进什么”符合对餐厅的建议语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，餐厅本身不吃东西，句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语多为歌曲，与餐厅需要改进的方面不搭配。"}, {"text": "忘", "is_correct": false, "explanation": "语义：忘指遗忘，不是对餐厅的改善建议，句意不符合语境。"}], "explanations": {"改进": "改进：正确答案，“你觉得这家餐厅应该改进什么”符合对餐厅的建议语境。", "吃": "语义：“吃”指进食，餐厅本身不吃东西，句意不通。", "唱": "搭配：“唱”的宾语多为歌曲，与餐厅需要改进的方面不搭配。", "忘": "语义：忘指遗忘，不是对餐厅的改善建议，句意不符合语境。"}, "sentence_index": 6, "correct_answer": "改进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们改进了他的生日。", "explanation": "这里应该用〈庆祝〉。改进是使事物变好，生日要用“庆祝”。"}, {"text": "他一直改进安静。", "explanation": "这里应该用〈保持〉。“安静”是状态，要说“保持安静”，改进不能与状态搭配。"}, {"text": "他想改进机会。", "explanation": "这里应该用〈抓住〉。机会是用来把握的，不能说“改进机会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂改进了过生产方法。", "corrected_sentence": "这家工厂改进过生产方法。", "error_description": "体标错误：“改进”后面的“过”已表示经历，不能再加“了”，应说“改进过生产方法”；“了”和“过”不能同时用在同一个动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天改进了这个办法。", "corrected_sentence": "我们明天改进这个办法。", "error_description": "体标错误：“明天”表示还没发生的事，“改进”后面不能加“了”，应说“明天改进这个办法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
