INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20194, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把文字做成书。", "primary_collocate": null, "pronunciation": "yìn shū", "ipa": "in˥˩ ʂu˥", "syllable_count": 2, "sentences": [{"text": "这家工厂专门印书。", "target_word": "印书", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在工厂里印书，一天能印几千本。", "target_word": "印书", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前人们用木板印书，速度很慢。", "target_word": "印书", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在用电脑印书，比以前快多了。", "target_word": "印书", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出版社请这家公司印书，要用好纸。", "target_word": "印书", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "印书要先排好字，再放进机器里。", "target_word": "印书", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，印书以前要先把文字检查一遍。", "target_word": "印书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在印刷厂工作，每天的事就是印书。", "target_word": "印书", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月要印书的订单特别多，工人们都很忙。", "target_word": "印书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了省钱，他们决定用便宜的纸印书。", "target_word": "印书", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "印书馆", "label": "复合"}], "register": "中性", "sense_fingerprint": "用机器把文字印刷成书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6062633-d150-4b42-8c9e-91408b62d40d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20194, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "印书", "is_correct": true, "explanation": "印书：用机器把文字印刷成书，符合“专门印书”的句意。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”是种植作物，与工厂的工作内容不符。"}, {"text": "养花", "is_correct": false, "explanation": "语义：“养花”是照料花草，与工厂的生产活动无关。"}, {"text": "卖书", "is_correct": false, "explanation": "搭配：“卖书”是书店的事，工厂一般不说“专门卖书”。"}], "explanations": {"印书": "印书：用机器把文字印刷成书，符合“专门印书”的句意。", "种植": "语义：“种植”是种植作物，与工厂的工作内容不符。", "养花": "语义：“养花”是照料花草，与工厂的生产活动无关。", "卖书": "搭配：“卖书”是书店的事，工厂一般不说“专门卖书”。"}, "sentence_index": 0, "correct_answer": "印书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生每天在医院给病人印书，治好了很多病。", "explanation": "这里应该用〈看病〉。给病人治病是看病，“印书”指把文字印成书。"}, {"text": "厨师在厨房里印书，做了一桌好菜。", "explanation": "这里应该用〈做菜〉。在厨房做出菜是做菜，不是印书。"}, {"text": "农民在田里印书，种了很多玉米。", "explanation": "这里应该用〈种地〉。在田里种玉米是种地，不是印书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "印书", "is_correct": true, "explanation": "印书：用机器把文字印刷成书，符合“印书以前要先检查文字”的句意。"}, {"text": "种地", "is_correct": false, "explanation": "语义：“种地”是农活，与“检查文字”没有关系，句子不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与检查文字无关，句子不通。"}, {"text": "修车", "is_correct": false, "explanation": "搭配：“修车”与“检查文字”的语境不搭配，句子不通。"}], "explanations": {"印书": "印书：用机器把文字印刷成书，符合“印书以前要先检查文字”的句意。", "种地": "语义：“种地”是农活，与“检查文字”没有关系，句子不通。", "唱歌": "语义：“唱歌”与检查文字无关，句子不通。", "修车": "搭配：“修车”与“检查文字”的语境不搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "印书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机每天印书，把乘客安全送到车站。", "explanation": "这里应该用〈开车〉。把乘客送到车站要开车，不是印书。"}, {"text": "护士给病人印书，病人觉得手有点疼。", "explanation": "这里应该用〈打针〉。护士给病人打针，不是印书。"}, {"text": "警察在街上印书，抓住了小偷。", "explanation": "这里应该用〈巡逻〉。警察在街上巡逻抓小偷，不是印书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们正在印书着。", "corrected_sentence": "他们正在印着书。", "error_description": "“印书”是动宾结构，动态助词“着”要插在动词“印”和宾语“书”之间，应说“印着书”，不能说“印书着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂每天印书了。", "corrected_sentence": "这家工厂每天印书。", "error_description": "“每天”表示经常、习惯性的动作，句末不能用表示完成或变化的“了”；应去掉“了”，说“这家工厂每天印书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
