INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20198, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "声音或消息经传递到达某处或某人。", "primary_collocate": null, "pronunciation": "chuán dào", "ipa": "ʈʂʰuan˧˥ tau˥˩", "syllable_count": 2, "sentences": [{"text": "他的声音传到了很远的地方。", "target_word": "传到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好消息很快传到了我家。", "target_word": "传到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个消息传到每一个同学那里。", "target_word": "传到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面的音乐传到了我的房间。", "target_word": "传到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事早就传到老师那里了。", "target_word": "传到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的新闻传到了别的城市。", "target_word": "传到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哭声传到了楼下。", "target_word": "传到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的歌声传到了河对岸。", "target_word": "传到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好消息终于传到了山里。", "target_word": "传到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事传到过很多国家。", "target_word": "传到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传到了", "label": "体标"}, {"form": "传到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "声音或消息经过传递而到达某处或某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b8f789-626d-40d7-a308-633398a91259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20198, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传到", "is_correct": true, "explanation": "传到：指声音传播到远处，与“很远的地方”相配，符合句意。"}, {"text": "传染", "is_correct": false, "explanation": "语义：传染指疾病的感染，声音不能被传染。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”的对象是物体，不能与“声音”搭配。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：“倒”不能用来表示声音的去向，句子不通。"}], "explanations": {"传到": "传到：指声音传播到远处，与“很远的地方”相配，符合句意。", "传染": "语义：传染指疾病的感染，声音不能被传染。", "扔": "搭配：“扔”的对象是物体，不能与“声音”搭配。", "倒": "搭配：“倒”不能用来表示声音的去向，句子不通。"}, "sentence_index": 0, "correct_answer": "传到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火车传到了北京站，全车的人都下了车。", "explanation": "这里应该用〈到达〉。传到指声音或消息的传递，火车到站要用〈到达〉。"}, {"text": "河水传到了大海里。", "explanation": "这里应该用〈流到〉。传到只用于声音或消息，水的流动要用〈流到〉。"}, {"text": "小偷传到了国外。", "explanation": "这里应该用〈逃到〉。传到只用于声音或消息，人的移动要用〈逃到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传到", "is_correct": true, "explanation": "传到：指声音传到楼下，符合句意。"}, {"text": "卖", "is_correct": false, "explanation": "搭配：声音不能被买卖，“卖”与“哭声”不搭配。"}, {"text": "滚", "is_correct": false, "explanation": "语义：滚指物体的滚动，哭声不会滚动。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧指燃烧，哭声不会燃烧，句子意思不通。"}], "explanations": {"传到": "传到：指声音传到楼下，符合句意。", "卖": "搭配：声音不能被买卖，“卖”与“哭声”不搭配。", "滚": "语义：滚指物体的滚动，哭声不会滚动。", "烧": "语义：烧指燃烧，哭声不会燃烧，句子意思不通。"}, "sentence_index": 6, "correct_answer": "传到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把伞传到了学校。", "explanation": "这里应该用〈带到〉。传到指声音或消息的传递，携带物品去某处要用〈带到〉。"}, {"text": "垃圾已经传到了垃圾桶里。", "explanation": "这里应该用〈扔到〉。传到只用于声音或消息，丢弃物品要用〈扔到〉。"}, {"text": "他家的房子传到了城里。", "explanation": "这里应该用〈搬到〉。房子不能被传递，只能用〈搬到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个消息很快就传到到全校。", "corrected_sentence": "这个消息很快就传到了全校。", "error_description": "重复错误：“传到”后多出一个“到”，应为“传到了”，“了”表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "消息已经把传到了村子里。", "corrected_sentence": "消息已经传到了村子里。", "error_description": "“把”字句错误：“传到”后面没有处置对象，不能加“把”，应去掉“把”，说“消息已经传到了村子里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
