INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20200, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出声呼喊，以招呼或呼唤别人。", "primary_collocate": null, "pronunciation": "jiào", "ipa": "tɕjɑʊ̯⁵¹", "syllable_count": 1, "sentences": [{"text": "妈妈在楼下叫我吃饭。", "target_word": "叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大声叫我的名字。", "target_word": "叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩在门口叫爸爸。", "target_word": "叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师叫了他两次，他没听见。", "target_word": "叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人在外面叫你，快出去看看。", "target_word": "叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在门口叫了半天，屋里的人才听见。", "target_word": "叫", "complexity_tier": "T3", "furigana": "jiào", "sentence_source": "generated"}, {"text": "他在山上大声叫，可是没有人回答。", "target_word": "叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你去叫一下经理，客人在等他。", "target_word": "叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叫了好几声，你怎么不理我？", "target_word": "叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到有人叫救命，他马上跑过去。", "target_word": "叫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "叫了", "label": "体标"}, {"form": "叫着", "label": "体标"}, {"form": "叫过", "label": "体标"}, {"form": "叫一叫", "label": "重叠"}, {"form": "大叫", "label": "复合"}, {"form": "叫喊", "label": "复合"}], "register": "口语", "sense_fingerprint": "出声呼喊，招呼别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d56d81d-7b32-4ed2-b81f-faaa77360a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20200, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "叫", "is_correct": true, "explanation": "“叫”意思是用声音招呼或呼唤。"}, {"text": "脚", "is_correct": false, "explanation": "jiǎo（第三声）与 jiào（第四声）声调不同，“脚”意思是身体的脚。"}, {"text": "笑", "is_correct": false, "explanation": "xiào 与 jiào 声母不同（x／j），“笑”意思是露出笑容或发笑。"}, {"text": "角", "is_correct": false, "explanation": "jiǎo（第三声）与 jiào（第四声）声调不同，“角”意思是角落或动物的角。"}, {"text": "翘", "is_correct": false, "explanation": "qiào 与 jiào 声母不同（q／j），“翘”意思是翘起。"}], "explanations": {"叫": "“叫”意思是用声音招呼或呼唤。", "脚": "jiǎo（第三声）与 jiào（第四声）声调不同，“脚”意思是身体的脚。", "笑": "xiào 与 jiào 声母不同（x／j），“笑”意思是露出笑容或发笑。", "角": "jiǎo（第三声）与 jiào（第四声）声调不同，“角”意思是角落或动物的角。", "翘": "qiào 与 jiào 声母不同（q／j），“翘”意思是翘起。"}, "sentence_index": null, "correct_answer": "叫"}, "level_3": {"options": [{"text": "叫", "is_correct": true, "explanation": "“叫”在此表示招呼对方来吃饭，正符合句意。"}, {"text": "梦见", "is_correct": false, "explanation": "语义：“梦见”指睡梦中见到，与楼下招呼吃饭的情境不符。"}, {"text": "烧", "is_correct": false, "explanation": "配价：“烧”的宾语应是饭菜等食物，不能带“我吃饭”这样的兼语结构。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”是暗中拿走，与招呼我吃饭的语境相反。"}], "explanations": {"叫": "“叫”在此表示招呼对方来吃饭，正符合句意。", "梦见": "语义：“梦见”指睡梦中见到，与楼下招呼吃饭的情境不符。", "烧": "配价：“烧”的宾语应是饭菜等食物，不能带“我吃饭”这样的兼语结构。", "偷": "语义：“偷”是暗中拿走，与招呼我吃饭的语境相反。"}, "sentence_index": 0, "correct_answer": "叫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我给妈妈叫了个电话。", "explanation": "这里应该用〈打〉。打电话不能说“叫电话”。"}, {"text": "我在门口叫了一下门铃。", "explanation": "这里应该用〈按〉。门铃要用“按”，“叫”表示呼唤，不能用来说按门铃。"}, {"text": "他叫了一个笑话，大家都笑了。", "explanation": "这里应该用〈讲〉。“叫”用于呼唤，不说“叫笑话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20200, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "叫", "is_correct": true, "explanation": "“叫”意思是用声音招呼或呼唤。"}, {"text": "交", "is_correct": false, "explanation": "jiāo（第一声）与 jiào（第四声）声调不同，“交”意思是交给。"}, {"text": "效", "is_correct": false, "explanation": "xiào 与 jiào 声母不同（x／j），“效”意思是效果。"}, {"text": "缴", "is_correct": false, "explanation": "jiǎo（第三声）与 jiào（第四声）声调不同，“缴”意思是缴纳。"}], "explanations": {"叫": "“叫”意思是用声音招呼或呼唤。", "交": "jiāo（第一声）与 jiào（第四声）声调不同，“交”意思是交给。", "效": "xiào 与 jiào 声母不同（x／j），“效”意思是效果。", "缴": "jiǎo（第三声）与 jiào（第四声）声调不同，“缴”意思是缴纳。"}, "sentence_index": null, "correct_answer": "叫"}, "level_3": {"options": [{"text": "叫", "is_correct": true, "explanation": "“大声叫”指大声呼喊，后面说没有人回答，正符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：大声吃东西不需要有人回答，与“没有人回答”不搭。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”不能用“大声”修饰，也与“回答”无关。"}, {"text": "搬", "is_correct": false, "explanation": "配价：“搬”需要宾语，且与“没有人回答”无关。"}], "explanations": {"叫": "“大声叫”指大声呼喊，后面说没有人回答，正符合句意。", "吃": "语义：大声吃东西不需要有人回答，与“没有人回答”不搭。", "睡": "语义：“睡”不能用“大声”修饰，也与“回答”无关。", "搬": "配价：“搬”需要宾语，且与“没有人回答”无关。"}, "sentence_index": 6, "correct_answer": "叫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上都叫一次澡。", "explanation": "这里应该用〈洗〉。“叫”不能和“澡”搭配，应说“洗澡”。"}, {"text": "学生叫了一次试。", "explanation": "这里应该用〈考〉。“叫”不用于考试，应说“考试”。"}, {"text": "他上个月叫了一场重病。", "explanation": "这里应该用〈得〉。“叫”表示呼唤，不能用来说得病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在楼下很叫了他一声。", "corrected_sentence": "我在楼下叫了他一声。", "error_description": "副词误用：“很”只修饰形容词等，不修饰动作动词“叫”，多余的“很”应删去。正确为“叫了他一声”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚才叫着我一声。", "corrected_sentence": "他刚才叫了我一声。", "error_description": "体标错误：表示一次已完成的呼唤要用“了”，“着”表示持续状态，“叫着我一声”不通。正确为“叫了我一声”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
