INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20201, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由许多零件组成、能代替人做工作的机械装置。", "primary_collocate": null, "pronunciation": "jī qì", "ipa": "tɕi˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "工厂里有很多大机器。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器坏了，需要修理。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器可以帮人做重复的工作。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器怎么开？请你教教我。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器一开，整个房间都很吵。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人每天要检查机器。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新机器比旧机器快两倍。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用机器收麦子。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器没有电就不能工作。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板花了很多钱买机器。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一台机器", "label": "量词"}, {"form": "一部机器", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，能代替人工作的机械装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c13fba2-698e-4727-b25b-42f4c360e701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20201, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机器", "is_correct": true, "explanation": "正确：“机器”指能帮人工作的装置，工厂里有很多大机器，语义与搭配都自然。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不会出现在工厂里，这里的语境是车间设备。"}, {"text": "语言", "is_correct": false, "explanation": "搭配：“大”不修饰“语言”，说“大语言”不搭配。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：工厂里不会有海洋，与“工厂里有”的语境矛盾。"}], "explanations": {"机器": "正确：“机器”指能帮人工作的装置，工厂里有很多大机器，语义与搭配都自然。", "星星": "语义：星星不会出现在工厂里，这里的语境是车间设备。", "语言": "搭配：“大”不修饰“语言”，说“大语言”不搭配。", "海洋": "语义：工厂里不会有海洋，与“工厂里有”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "机器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把锤子是我最常用的机器。", "explanation": "这里应该用〈工具〉。锤子是手用的、不带动力的用具，应说“工具”，“机器”指有动力的装置。"}, {"text": "他学的是机器工程。", "explanation": "这里应该用〈机械〉。学科名称“机械工程”是固定说法，“机器”不用于这一名称。"}, {"text": "这些机器是妈妈从树上摘下来的。", "explanation": "这里应该用〈水果〉。从树上摘下来的是水果，“机器”指能代替人工作的机械装置，不长在树上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20201, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机器", "is_correct": true, "explanation": "正确：“新机器”与后半句“旧机器”相互比较，快慢的对象是机器，语义自然。"}, {"text": "花", "is_correct": false, "explanation": "语义：“花”是植物，不能拿来与旧机器比较快慢。"}, {"text": "电影", "is_correct": false, "explanation": "语义：“电影”不能与旧机器比较工作速度，这里的比较对象应是机器。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“快两倍”说的是速度或效率，不与“小说”搭配。"}], "explanations": {"机器": "正确：“新机器”与后半句“旧机器”相互比较，快慢的对象是机器，语义自然。", "花": "语义：“花”是植物，不能拿来与旧机器比较快慢。", "电影": "语义：“电影”不能与旧机器比较工作速度，这里的比较对象应是机器。", "小说": "搭配：“快两倍”说的是速度或效率，不与“小说”搭配。"}, "sentence_index": 6, "correct_answer": "机器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校操场上摆着一套体育机器。", "explanation": "这里应该用〈器械〉。“体育器械”是固定说法，指健身用的器材；“机器”指有动力的装置，不用于健身器材。"}, {"text": "车上有一个安全机器，很重要。", "explanation": "这里应该用〈装置〉。“安全装置”是固定说法，“机器”指能工作的机械，不用于这种安全部件。"}, {"text": "汽车的机器显示速度。", "explanation": "这里应该用〈仪表〉。显示数值的部件是“仪表”，“机器”不用于指示速度的仪表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车间里那只机器坏了，需要修理。", "corrected_sentence": "车间里那台机器坏了，需要修理。", "error_description": "错误在于量词：“机器”用“台”计量，写成“那只机器”是错的，正确说法是“那台机器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台新机器把跑得特别快。", "corrected_sentence": "这台新机器跑得特别快。", "error_description": "错误在于多加了“把”：“跑”后面没有处置对象，不能用“把”字句，应去掉“把”，说“这台新机器跑得特别快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20204, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "容易", "is_correct": true, "explanation": "容易：做起来不费力，与“难”互为反义，符合“找工作很难”的句意。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：便宜指价格低，与“难”的“做起来不容易”不构成反义。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：整齐指排列有序，与“难”无关。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：粗糙指表面不光滑，与“难”无关。"}], "correct_answer": "容易", "explanations": {"容易": "容易：做起来不费力，与“难”互为反义，符合“找工作很难”的句意。", "便宜": "语义：便宜指价格低，与“难”的“做起来不容易”不构成反义。", "整齐": "语义：整齐指排列有序，与“难”无关。", "粗糙": "语义：粗糙指表面不光滑，与“难”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20204, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "容易", "is_correct": true, "explanation": "容易：做起来不费力，与“难”互为反义，符合“在山里找水”的句意。"}, {"text": "安静", "is_correct": false, "explanation": "语义：安静指没有声音，与“难”不构成反义。"}, {"text": "肥", "is_correct": false, "explanation": "语义：肥指体态胖或土地肥沃，与“难”无关。"}, {"text": "粗", "is_correct": false, "explanation": "语义：粗指物体不细，与“难”无关。"}], "correct_answer": "容易", "explanations": {"容易": "容易：做起来不费力，与“难”互为反义，符合“在山里找水”的句意。", "安静": "语义：安静指没有声音，与“难”不构成反义。", "肥": "语义：肥指体态胖或土地肥沃，与“难”无关。", "粗": "语义：粗指物体不细，与“难”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20204, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做起来不容易。", "primary_collocate": null, "pronunciation": "nán", "ipa": "nan˧˥", "syllable_count": 1, "sentences": [{"text": "这道数学题很难。", "target_word": "难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉字难不难？", "target_word": "难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的考试不太难。", "target_word": "难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这么大的城市找工作很难。", "target_word": "难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得说汉语比写汉字难。", "target_word": "难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题太难了，我不会做。", "target_word": "难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对我来说，早上起床最难。", "target_word": "难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书不难，你可以看看。", "target_word": "难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做好人容易，做好朋友难。", "target_word": "难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在山里找水非常难。", "target_word": "难", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "難", "label": "繁体"}, {"form": "难度", "label": "复合词"}, {"form": "难题", "label": "复合词"}], "register": "中性", "sense_fingerprint": "事情做起来费力、不容易", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b8f789-626d-40d7-a308-633398a91259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20204, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "难", "is_correct": true, "explanation": "难 nán：做起来不容易，正确答案。"}, {"text": "蓝", "is_correct": false, "explanation": "lán 与 nán 声母不同，意思是蓝色。"}, {"text": "拿", "is_correct": false, "explanation": "ná 比 nán 少了韵尾 n，意思是拿取。"}, {"text": "年", "is_correct": false, "explanation": "nián 比 nán 多了介音 i，意思是年份。"}], "explanations": {"难": "难 nán：做起来不容易，正确答案。", "蓝": "lán 与 nán 声母不同，意思是蓝色。", "拿": "ná 比 nán 少了韵尾 n，意思是拿取。", "年": "nián 比 nán 多了介音 i，意思是年份。"}, "sentence_index": null, "correct_answer": "难"}, "level_3": {"options": [{"text": "难", "is_correct": true, "explanation": "难：形容题目做起来费力、不容易，符合句意。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”形容光线或颜色，不能用来形容数学题。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面，不能用来形容数学题。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”指清洁，数学题不能说干净与否。"}], "explanations": {"难": "难：形容题目做起来费力、不容易，符合句意。", "亮": "语义：“亮”形容光线或颜色，不能用来形容数学题。", "热闹": "搭配：“热闹”形容场面，不能用来形容数学题。", "干净": "语义：“干净”指清洁，数学题不能说干净与否。"}, "sentence_index": 0, "correct_answer": "难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他吃坏了肚子，一整天都很难。", "explanation": "这里应该用〈难受〉。难指做事不容易，身体不舒服要用〈难受〉。"}, {"text": "这碗汤很难，喝了一口就吐了。", "explanation": "这里应该用〈难喝〉。难指做事不容易，形容汤的味道不好要用〈难喝〉。"}, {"text": "他今天的样子很难。", "explanation": "这里应该用〈难看〉。难不能形容外貌，样子不好看要用〈难看〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "难", "is_correct": true, "explanation": "难：指做起来不容易，与“早上起床”相配，符合句意。"}, {"text": "远", "is_correct": false, "explanation": "语义：起床是动作，不能用“远”来形容。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”形容形状，起床不能说圆。"}, {"text": "好吃", "is_correct": false, "explanation": "搭配：“好吃”只形容食物，不能用来形容起床。"}], "explanations": {"难": "难：指做起来不容易，与“早上起床”相配，符合句意。", "远": "语义：起床是动作，不能用“远”来形容。", "圆": "语义：“圆”形容形状，起床不能说圆。", "好吃": "搭配：“好吃”只形容食物，不能用来形容起床。"}, "sentence_index": 6, "correct_answer": "难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的天气很难，我们别出门了。", "explanation": "这里应该用〈糟糕〉。难指做事不容易，形容天气要用〈糟糕〉。"}, {"text": "这件衣服很难，我舍不得买。", "explanation": "这里应该用〈贵〉。难指做事不容易，形容价格高要用〈贵〉。"}, {"text": "这台电脑很难，开机只要两秒钟。", "explanation": "这里应该用〈快〉。难指做事不容易，形容速度要用〈快〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学汉字对外国人来说难很。", "corrected_sentence": "学汉字对外国人来说很难。", "error_description": "语序错误：程度副词“很”应放在形容词“难”之前，应说“很难”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一道很难题。", "corrected_sentence": "这是一道很难的题。", "error_description": "漏字错误：形容词修饰名词时要用“的”，“很难题”应改为“很难的题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
