INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "孩子就是小男孩或小女孩。", "primary_collocate": null, "pronunciation": "hái zi", "ipa": "xaɪ̯˧˥ tsɹ̩", "syllable_count": 2, "sentences": [{"text": "这个孩子很可爱。", "target_word": "孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家有两个孩子，都在上小学。", "target_word": "孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子在公园里玩。", "target_word": "孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子饿了，快给他做饭。", "target_word": "孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈每天送孩子去上学。", "target_word": "孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个孩子才三岁，还不会写字。", "target_word": "孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子睡着了，请小声一点。", "target_word": "孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子哭了，因为他找不到妈妈。", "target_word": "孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的孩子喜欢画画，也喜欢唱歌。", "target_word": "孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，这个孩子学得很快。", "target_word": "孩子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "孩子们", "label": "复数"}], "register": "中性", "sense_fingerprint": "年纪还小的男孩或女孩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245410d8-ef7c-4e0b-b864-35d4e472cd06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20212, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "孩子", "is_correct": true, "explanation": "“孩子”指年纪小的男孩或女孩，是本词。"}, {"text": "还是", "is_correct": false, "explanation": "háishi 与 háizi 第二音节声母不同（sh 与 z），意思是“还是”。"}, {"text": "牌子", "is_correct": false, "explanation": "páizi 与 háizi 首音节声母不同（p 与 h），意思是“牌子”。"}, {"text": "盒子", "is_correct": false, "explanation": "hézi 与 háizi 首音节韵母不同（e 与 ai），意思是“盒子”。"}], "explanations": {"孩子": "“孩子”指年纪小的男孩或女孩，是本词。", "还是": "háishi 与 háizi 第二音节声母不同（sh 与 z），意思是“还是”。", "牌子": "páizi 与 háizi 首音节声母不同（p 与 h），意思是“牌子”。", "盒子": "hézi 与 háizi 首音节韵母不同（e 与 ai），意思是“盒子”。"}, "sentence_index": null, "correct_answer": "孩子"}, "level_3": {"options": [{"text": "孩子", "is_correct": true, "explanation": "“孩子”指年纪小的男孩或女孩，符合“很可爱”的评价。"}, {"text": "病", "is_correct": false, "explanation": "语义：“病”指身体不适，不能用“可爱”来形容。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是测验活动，不能说“很可爱”。"}, {"text": "报告", "is_correct": false, "explanation": "搭配：“可爱”用于人或动物等能被喜爱的对象，不与“报告”搭配。"}], "explanations": {"孩子": "“孩子”指年纪小的男孩或女孩，符合“很可爱”的评价。", "病": "语义：“病”指身体不适，不能用“可爱”来形容。", "考试": "语义：“考试”是测验活动，不能说“很可爱”。", "报告": "搭配：“可爱”用于人或动物等能被喜爱的对象，不与“报告”搭配。"}, "sentence_index": 0, "correct_answer": "孩子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家有一只孩子，很可爱。", "explanation": "这里应该用〈个〉。“只”用于动物或成对的东西，指人的“孩子”要用量词“个”。"}, {"text": "他是我的孩子，我们决定明年结婚。", "explanation": "这里应该用〈对象〉。“孩子”指年纪小的男孩或女孩，不能指要结婚的成年人。"}, {"text": "我的父母是我的孩子，我每天照顾他们。", "explanation": "这里应该用〈长辈〉。“孩子”指年纪小的男孩或女孩，不能指父母这样的成年人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孩子", "is_correct": true, "explanation": "“孩子”是会睡觉的小孩，与“睡着了”相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”没有生命，不能“睡着”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是无生命的物体，不会“睡着”。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“睡着”只用于人或动物，不与“作业”搭配。"}], "explanations": {"孩子": "“孩子”是会睡觉的小孩，与“睡着了”相符。", "桌子": "语义：“桌子”没有生命，不能“睡着”。", "窗户": "语义：“窗户”是无生命的物体，不会“睡着”。", "作业": "搭配：“睡着”只用于人或动物，不与“作业”搭配。"}, "sentence_index": 6, "correct_answer": "孩子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子是一本书，可以读。", "explanation": "“孩子”指人，指小男孩或小女孩，不能用来指书这类物品。"}, {"text": "那个孩子是一位八十岁的老爷爷，每天在公园里下棋。", "explanation": "“孩子”指年纪小的人，不能用来指八十岁的老人。"}, {"text": "那几位孩子是大学老师，他们每天给学生上课。", "explanation": "“孩子”指年纪小的人，不能指大学老师这样的成年人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们家有三本孩子。", "corrected_sentence": "他们家有三个孩子。", "error_description": "“孩子”的量词应用“个”，不能用“本”。“本”用于书、本子等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子们在教室里画画。", "corrected_sentence": "这个孩子在教室里画画。", "error_description": "“这个”指单数，“孩子们”表示复数，二者不能搭配，应去掉“们”，说“这个孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
