INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20214, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小朋友学习的地方。", "primary_collocate": null, "pronunciation": "xué xiào", "ipa": "ɕɥɛ˧˥ ɕi̯ɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我的学校离家很近，走路十分钟。", "target_word": "学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里有一个很大的操场。", "target_word": "学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天学校不上课，我们去公园玩。", "target_word": "学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明每天早上七点去学校。", "target_word": "学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校有三百个学生。", "target_word": "学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口有很多家长在等孩子。", "target_word": "学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的老师都很好。", "target_word": "学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下午放学后，孩子们还在学校踢球。", "target_word": "学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹今年六岁，下个月就去学校了。", "target_word": "学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边有一家小书店。", "target_word": "学校", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "学校生活", "label": "复合"}], "register": "中性", "sense_fingerprint": "学校：孩子学习的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 离家 (Zipf 3.83), 很近 (Zipf 3.22), 十分钟 (Zipf 3.83)']::text[], '0e8c9982-2261-4a26-bafc-a41b87d5771d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20214, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学校", "is_correct": true, "explanation": "正确：“学校”是地点名词，可以说离家很近、走路十分钟。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：“铅笔”是文具，不是地点，不能说离家很近、走路十分钟。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，不是地点，不能说离家很近、走路十分钟。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“离家很近，走路十分钟”用于地点，不用于随身携带的书包。"}], "explanations": {"学校": "正确：“学校”是地点名词，可以说离家很近、走路十分钟。", "铅笔": "语义：“铅笔”是文具，不是地点，不能说离家很近、走路十分钟。", "作业": "语义：“作业”是学习任务，不是地点，不能说离家很近、走路十分钟。", "书包": "搭配：“离家很近，走路十分钟”用于地点，不用于随身携带的书包。"}, "sentence_index": 0, "correct_answer": "学校"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他发烧了，所以一早就去学校看病。", "explanation": "这里应该用〈医院〉。学校是教学的地方，看病要去医院。"}, {"text": "周末我们去学校看大熊猫。", "explanation": "这里应该用〈动物园〉。学校不养大熊猫，看大熊猫要去动物园。"}, {"text": "周末我们去学校买菜。", "explanation": "这里应该用〈菜市场〉。学校不卖菜，买菜要去菜市场或超市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学校", "is_correct": true, "explanation": "正确：“学校”指教书育人的机构，“我们学校的老师”指学校里的教师。"}, {"text": "医院", "is_correct": false, "explanation": "语义：老师一般不在医院工作，“医院的老师”不成立。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市不是教书育人的机构，“超市的老师”不成立。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是玩的地方，没有老师，“我们公园的老师”不成立。"}], "explanations": {"学校": "正确：“学校”指教书育人的机构，“我们学校的老师”指学校里的教师。", "医院": "语义：老师一般不在医院工作，“医院的老师”不成立。", "超市": "语义：超市不是教书育人的机构，“超市的老师”不成立。", "公园": "语义：公园是玩的地方，没有老师，“我们公园的老师”不成立。"}, "sentence_index": 6, "correct_answer": "学校"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去学校取钱。", "explanation": "这里应该用〈银行〉。取钱要去银行，学校不是办理取款的地方。"}, {"text": "我下午去学校剪头发。", "explanation": "这里应该用〈理发店〉。剪头发要去理发店，学校里一般没有理发服务。"}, {"text": "我去学校买药。", "explanation": "这里应该用〈药店〉。买药要去药店，学校一般不卖药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天学校门口等妈妈。", "corrected_sentence": "我每天在学校门口等妈妈。", "error_description": "错误：表示动作地点时漏掉了介词“在”。正确：“在学校门口等妈妈”，用“在”引出处所；漏掉后“学校门口”无法作处所，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只学校有八位老师。", "corrected_sentence": "这所学校有八位老师。", "error_description": "错误：用“只”修饰“学校”。正确：学校应该用量词“所”，“只”通常用于动物等，不能修饰学校。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
