INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20216, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情，就是一个人做的一件工作或发生的一件事。", "primary_collocate": null, "pronunciation": "shì", "ipa": "ʂʐ̩⁵¹", "syllable_count": 1, "sentences": [{"text": "明天我有事，不能来了。", "target_word": "事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你别告诉别人。", "target_word": "事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都忙着做事。", "target_word": "事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天发生了一件奇怪的事。", "target_word": "事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你找我有什么事？", "target_word": "事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不重要的事你自己做，重要的事问爸爸。", "target_word": "事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我自己的事，不用你管。", "target_word": "事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事很认真，老板很喜欢他。", "target_word": "事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了什么事？你怎么哭了？", "target_word": "事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的事，我现在还记得。", "target_word": "事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "事情", "label": "复合"}, {"form": "小事", "label": "复合"}, {"form": "大事", "label": "复合"}], "register": "中性", "sense_fingerprint": "人做的事或发生的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d56d81d-7b32-4ed2-b81f-faaa77360a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20216, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事", "is_correct": true, "explanation": "“事”意思是事情，指人做的工作或发生的事。"}, {"text": "史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，“史”意思是历史。"}, {"text": "师", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，“师”意思是老师。"}, {"text": "十", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“十”是数字十。"}, {"text": "四", "is_correct": false, "explanation": "sì 与 shì 声母不同（s／sh），“四”是数字四。"}, {"text": "制", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh／sh），“制”意思是制度。"}], "explanations": {"事": "“事”意思是事情，指人做的工作或发生的事。", "史": "shǐ（第三声）与 shì（第四声）声调不同，“史”意思是历史。", "师": "shī（第一声）与 shì（第四声）声调不同，“师”意思是老师。", "十": "shí（第二声）与 shì（第四声）声调不同，“十”是数字十。", "四": "sì 与 shì 声母不同（s／sh），“四”是数字四。", "制": "zhì 与 shì 声母不同（zh／sh），“制”意思是制度。"}, "sentence_index": null, "correct_answer": "事"}, "level_3": {"options": [{"text": "事", "is_correct": true, "explanation": "“有事”指有事情要处理，正符合不能来的原因。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“有时间”与“不能来”矛盾，句意不通。"}, {"text": "钱", "is_correct": false, "explanation": "语义：“有钱”与不能来的原因无关，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“有”后不接“天气”，不成搭配。"}], "explanations": {"事": "“有事”指有事情要处理，正符合不能来的原因。", "时间": "语义：“有时间”与“不能来”矛盾，句意不通。", "钱": "语义：“有钱”与不能来的原因无关，句意不通。", "天气": "搭配：“有”后不接“天气”，不成搭配。"}, "sentence_index": 0, "correct_answer": "事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天发生了一只大事。", "explanation": "这里应该用〈件〉。事情用“件”，不用“只”。"}, {"text": "这次交通事很严重。", "explanation": "这里应该用〈事故〉。“事”不能单独指交通事故。"}, {"text": "他吃了一件大事。", "explanation": "这里应该用〈饭〉。“吃”的对象是食物，不能说吃“事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20216, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "事", "is_correct": true, "explanation": "“事”意思是事情，指人做的工作或发生的事。"}, {"text": "使", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，“使”意思是使用或使得。"}, {"text": "诗", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，“诗”意思是诗歌。"}, {"text": "时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“时”意思是时间。"}, {"text": "志", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh／sh），声调相同，“志”意思是志向。"}, {"text": "似", "is_correct": false, "explanation": "sì 与 shì 声母不同（s／sh），“似”意思是好像。"}], "explanations": {"事": "“事”意思是事情，指人做的工作或发生的事。", "使": "shǐ（第三声）与 shì（第四声）声调不同，“使”意思是使用或使得。", "诗": "shī（第一声）与 shì（第四声）声调不同，“诗”意思是诗歌。", "时": "shí（第二声）与 shì（第四声）声调不同，“时”意思是时间。", "志": "zhì 与 shì 声母不同（zh／sh），声调相同，“志”意思是志向。", "似": "sì 与 shì 声母不同（s／sh），“似”意思是好像。"}, "sentence_index": null, "correct_answer": "事"}, "level_3": {"options": [{"text": "事", "is_correct": true, "explanation": "“事”指自己的事情，别人不该干涉，句意通顺。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不能说成“我自己的”，与“不用你管”也不搭，句意不通。"}, {"text": "左边", "is_correct": false, "explanation": "语义：“我自己的左边”与“不用你管”搭不上，句意不通。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“星期”是时间名词，不说“我自己的星期”。"}], "explanations": {"事": "“事”指自己的事情，别人不该干涉，句意通顺。", "太阳": "语义：太阳不能说成“我自己的”，与“不用你管”也不搭，句意不通。", "左边": "语义：“我自己的左边”与“不用你管”搭不上，句意不通。", "星期": "搭配：“星期”是时间名词，不说“我自己的星期”。"}, "sentence_index": 6, "correct_answer": "事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下午参加了一场事。", "explanation": "这里应该用〈考试〉。“参加”后接活动，“事”不能指考试。"}, {"text": "这件事很好吃。", "explanation": "这里应该用〈饭菜〉。“好吃”形容食物，“事”指事情，不能这样形容。"}, {"text": "他买了一件事。", "explanation": "这里应该用〈东西〉。“事”不指可以买的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_i