INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天发生了一块意外的事。", "corrected_sentence": "昨天发生了一件意外的事。", "error_description": "量词错误：事情要用“件”，“块”是用于块状物的量词，应改为“件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
