INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20220, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "大小上超过一般。", "primary_collocate": null, "pronunciation": "hěn dà", "ipa": "xən˨˩˦ ta˥˩", "syllable_count": 2, "sentences": [{"text": "这个房子很大。", "target_word": "很大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的教室很大。", "target_word": "很大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手很大。", "target_word": "很大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里有一棵很大的树。", "target_word": "很大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鱼很大，我们吃不完。", "target_word": "很大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗很大，小孩有点怕。", "target_word": "很大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市很大，坐地铁最方便。", "target_word": "很大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的书包很大，里面放着很多书。", "target_word": "很大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个西瓜很大，够十个人吃。", "target_word": "很大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脚很大，买鞋不容易。", "target_word": "很大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更大", "label": "比较"}, {"form": "最大", "label": "最高级"}], "register": "口语", "sense_fingerprint": "大小超过一般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245aa18a-045a-46cc-b4fa-b7de9581fe19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings =