INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "很大", "is_correct": true, "explanation": "正确：「很大」形容房子的大小超过一般，符合句意。"}, {"text": "很苦", "is_correct": false, "explanation": "搭配：「苦」形容味道，不能用来形容房子。"}, {"text": "很聪明", "is_correct": false, "explanation": "语义：「聪明」形容人的智力，不能用来形容房子。"}, {"text": "很饿", "is_correct": false, "explanation": "语义：「饿」只能用于人或动物，房子不会饿。"}], "explanations": {"很大": "正确：「很大」形容房子的大小超过一般，符合句意。", "很苦": "搭配：「苦」形容味道，不能用来形容房子。", "很聪明": "语义：「聪明」形容人的智力，不能用来形容房子。", "很饿": "语义：「饿」只能用于人或动物，房子不会饿。"}, "sentence_index": 0, "correct_answer": "很大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行的时间很大，我们玩了好几天。", "explanation": "这里应该用〈很长〉。〈很大〉说的是大小，时间的多少要说〈很长〉或〈很久〉，不能用「很大」形容时间。"}, {"text": "这辆车的速度很大，一会儿就到了。", "explanation": "这里应该用〈很快〉。〈很大〉说大小，速度要说〈很快〉，不能用「很大」形容速度。"}, {"text": "我的感冒很大，所以我今天没去上学。", "explanation": "这里应该用〈很严重〉。〈很大〉说大小，病情的轻重要说〈很严重〉，不能用「很大」形容感冒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很大", "is_correct": true, "explanation": "正确：「很大」形容城市的面积超过一般，符合句意。"}, {"text": "很香", "is_correct": false, "explanation": "搭配：「香」一般形容气味，不能用来形容城市。"}, {"text": "很渴", "is_correct": false, "explanation": "语义：「渴」只能用于人或动物，城市不会渴。"}, {"text": "很胖", "is_correct": false, "explanation": "语义：「胖」形容人或动物的体型，不能用来形容城市。"}], "explanations": {"很大": "正确：「很大」形容城市的面积超过一般，符合句意。", "很香": "搭配：「香」一般形容气味，不能用来形容城市。", "很渴": "语义：「渴」只能用于人或动物，城市不会渴。", "很胖": "语义：「胖」形容人或动物的体型，不能用来形容城市。"}, "sentence_index": 6, "correct_answer": "很大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭店的价格很大，我们没去吃。", "explanation": "这里应该用〈很贵〉。〈很大〉说大小，价格的高低要说〈很贵〉，不能用「很大」形容价格。"}, {"text": "他的性格很大，大家都喜欢他。", "explanation": "这里应该用〈很开朗〉或〈很好〉。〈很大〉说大小，性格要用别的词来评价，不能用「很大」形容性格。"}, {"text": "今天的天气很大，我们去公园玩。", "explanation": "这里应该用〈很好〉。〈很大〉说大小，天气的好坏要说〈很好〉，不能用「很大」形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个很大公园。", "corrected_sentence": "这是一个很大的公园。", "error_description": "的字漏用：错误形式为「很大公园」，正确形式为「很大的公园」。「很大」修饰名词「公园」时，中间要加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家饭店很大地，客人很多。", "corrected_sentence": "这家饭店很大，客人很多。", "error_description": "助词错误：「很大」后面不能加「地」，这里应该去掉「地」，写作「很大，客人很多」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
