INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20222, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容速度比原来更大。", "primary_collocate": null, "pronunciation": "gèng kuài", "ipa": "kɤŋ˥˩ kʰwaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "坐高铁去上海更快，我们别坐大巴吧。", "target_word": "更快", "complexity_tier": "T3", "furigana": "zuò gāo tiě qù shàng hǎi gèng kuài, wǒ men bié zuò dà bā ba", "sentence_source": "generated"}, {"text": "我想跑得更快一点。", "target_word": "更快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新软件更快，打开文件很方便。", "target_word": "更快", "complexity_tier": "T3", "furigana": "zhè ge xīn ruǎn jiàn gèng kuài, dǎ kāi wén jiàn hěn fāng biàn", "sentence_source": "generated"}, {"text": "他每天练习，所以游得更快了。", "target_word": "更快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车去更快，我们一起骑车吧。", "target_word": "更快", "complexity_tier": "T3", "furigana": "qí chē qù gèng kuài, wǒ men yì qǐ qí chē ba", "sentence_source": "generated"}, {"text": "网速变得更快了。", "target_word": "更快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁去机场更快，路上不堵车。", "target_word": "更快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你多练习，会进步得更快。", "target_word": "更快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天跑得更快了，因为天气好。", "target_word": "更快", "complexity_tier": "T3", "furigana": "wǒ jīn tiān pǎo de gèng kuài le, yīn wèi tiān qì hǎo", "sentence_source": "generated"}, {"text": "风越来越大，船开得更快了。", "target_word": "更快", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "速度比原来或比别的更大，比较之后更快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bacc239c-df87-4c0c-a87d-ec7f9978f1b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更快", "is_correct": true, "explanation": "正确：“更快”表示高铁速度比大巴更大，与后句“别坐大巴”呼应。"}, {"text": "更慢", "is_correct": false, "explanation": "语义：“更慢”与“更快”意思相反，说高铁更慢与“别坐大巴”的建议矛盾。"}, {"text": "太慢", "is_correct": false, "explanation": "语义：“太慢”说高铁过慢，与“更快”的比较和“别坐大巴”的推荐矛盾。"}, {"text": "最慢", "is_correct": false, "explanation": "语义：“最慢”指所有之中最慢，与“别坐大巴”的推荐矛盾。"}], "explanations": {"更快": "正确：“更快”表示高铁速度比大巴更大，与后句“别坐大巴”呼应。", "更慢": "语义：“更慢”与“更快”意思相反，说高铁更慢与“别坐大巴”的建议矛盾。", "太慢": "语义：“太慢”说高铁过慢，与“更快”的比较和“别坐大巴”的推荐矛盾。", "最慢": "语义：“最慢”指所有之中最慢，与“别坐大巴”的推荐矛盾。"}, "sentence_index": 0, "correct_answer": "更快"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的人数更快了。", "explanation": "这里应该用〈更多〉。“更快”说速度的变化，人数的增减要用“更多”或“更少”。"}, {"text": "这件衣服的价格更快了。", "explanation": "这里应该用〈更贵〉。价格的变化是高低，不说快慢，“更快”用错了对象。"}, {"text": "他每天练习，所以成绩更快了。", "explanation": "这里应该用〈更好〉。成绩的变化说高低，不说快慢，“更快”用错了对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更快", "is_correct": true, "explanation": "正确：“坐地铁去机场更快，路上不堵车”是速度比较，“更快”符合句意。"}, {"text": "很慢", "is_correct": false, "explanation": "语义：“很慢”与后句“路上不堵车”及“更快”的比较结论相反。"}, {"text": "稍慢", "is_correct": false, "explanation": "语义：“稍慢”说地铁较慢，与“坐地铁更快”的推荐矛盾。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”表示超出一般的程度，不能用在“去机场”后表示快慢比较。"}], "explanations": {"更快": "正确：“坐地铁去机场更快，路上不堵车”是速度比较，“更快”符合句意。", "很慢": "语义：“很慢”与后句“路上不堵车”及“更快”的比较结论相反。", "稍慢": "语义：“稍慢”说地铁较慢，与“坐地铁更快”的推荐矛盾。", "格外": "搭配：“格外”表示超出一般的程度，不能用在“去机场”后表示快慢比较。"}, "sentence_index": 6, "correct_answer": "更快"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "气温更快了。", "explanation": "这里应该用〈更低〉。气温的变化说高低，不说快慢，“更快”用错了对象。"}, {"text": "他这次考试的错误更快了。", "explanation": "这里应该用〈更少〉。错误的变化要用“多、少”，不能说快慢。"}, {"text": "他这个月的工资更快了。", "explanation": "这里应该用〈更高〉。工资的变化说多少、高低，不说快慢，“更快”用错了对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跑了更快了。", "corrected_sentence": "他跑得更快了。", "error_description": "“得”引出补语“更快了”，不能用“了”代替，应说“跑得更快了”，不能说“跑了更快了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的网速很更快了。", "corrected_sentence": "我的网速更快了。", "error_description": "“更”本身表示程度，不能再加“很”，应说“网速更快了”，不能说“很更快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20224, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "退步", "is_correct": true, "explanation": "正确。“退步”与“进步”是反义词，指比以前变差。"}, {"text": "学习", "is_correct": false, "explanation": "“学习”是获取知识的活动，与“进步”没有反义关系。"}, {"text": "休息", "is_correct": false, "explanation": "“休息”指停下来放松，与“进步”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”指出外游览，与“进步”没有反义关系。"}], "correct_answer": "退步", "explanations": {"退步": "正确。“退步”与“进步”是反义词，指比以前变差。", "学习": "“学习”是获取知识的活动，与“进步”没有反义关系。", "休息": "“休息”指停下来放松，与“进步”没有反义关系。", "旅行": "“旅行”指出外游览，与“进步”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20224, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "退步", "is_correct": true, "explanation": "正确。“退步”与“进步”是反义词，指比以前变差。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指用声音表演歌曲，与“进步”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”指在水中活动，与“进步”没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "“吃饭”指进食，与“进步”没有反义关系。"}], "correct_answer": "退步", "explanations": {"退步": "正确。“退步”与“进步”是反义词，指比以前变差。", "唱歌": "“唱歌”指用声音表演歌曲，与“进步”没有反义关系。", "游泳": "“游泳”指在水中活动，与“进步”没有反义关系。", "吃饭": "“吃饭”指进食，与“进步”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20224, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比以前好。", "primary_collocate": null, "pronunciation": "jìn bù", "ipa": "tɕin⁵¹ pu⁵¹", "syllable_count": 2, "sentences": [{"text": "你的汉语进步了很多。", "target_word": "进步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学习很努力，进步很快。", "target_word": "进步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子每天都在进步。", "target_word": "进步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的字进步了。", "target_word": "进步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想让我的中文进步。", "target_word": "进步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起上个月，你进步了不少。", "target_word": "进步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的英语进步得很快。", "target_word": "进步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天读书，你一定会进步。", "target_word": "进步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的成绩进步了。", "target_word": "进步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说他进步了。", "target_word": "进步", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进步了", "label": "体标"}, {"form": "进步得", "label": "复合"}, {"form": "進步", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比以前变好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f67254c-2b72-48f7-a62f-6cc95d11eae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20224, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进步", "is_correct": true, "explanation": "正确。“进步”表示比以前变好。"}, {"text": "进补", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是滋补身体，不是进步。"}, {"text": "信步", "is_correct": false, "explanation": "xìn 与 jìn 声母不同（x 与 j），意思是随意散步，不是进步。"}, {"text": "进度", "is_correct": false, "explanation": "jìndù 与 jìnbù 只差一个声母（d 与 b），意思是工作或学习的快慢程度，不是进步。"}, {"text": "急步", "is_correct": false, "explanation": "jíbù 与 jìnbù 韵母和声调不同（i 与 in），意思是快步走，不是进步。"}], "explanations": {"进步": "正确。“进步”表示比以前变好。", "进补": "bǔ（第三声）与 bù（第四声）声调不同，意思是滋补身体，不是进步。", "信步": "xìn 与 jìn 声母不同（x 与 j），意思是随意散步，不是进步。", "进度": "jìndù 与 jìnbù 只差一个声母（d 与 b），意思是工作或学习的快慢程度，不是进步。", "急步": "jíbù 与 jìnbù 韵母和声调不同（i 与 in），意思是快步走，不是进步。"}, "sentence_index": null, "correct_answer": "进步"}, "level_3": {"options": [{"text": "进步", "is_correct": true, "explanation": "正确。“进步”表示比以前变好，与“汉语”和“了很多”搭配，表示水平提高。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求人作主语、食物作宾语，“你的汉语”不能做“吃”的对象。"}, {"text": "消失", "is_correct": false, "explanation": "语义：“消失”表示不见了，与句子说汉语变好的意思相反。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”的主语应是人，“汉语”不能作为“唱”的主语来说“唱了很多”。"}], "explanations": {"进步": "正确。“进步”表示比以前变好，与“汉语”和“了很多”搭配，表示水平提高。", "吃": "配价：“吃”要求人作主语、食物作宾语，“你的汉语”不能做“吃”的对象。", "消失": "语义：“消失”表示不见了，与句子说汉语变好的意思相反。", "唱": "配价：“唱”的主语应是人，“汉语”不能作为“唱”的主语来说“唱了很多”。"}, "sentence_index": 0, "correct_answer": "进步"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议进步了两个小时。", "explanation": "这里应该用〈延长〉。“进步”表示变好，时间的增加要用“延长”，不能说“进步了两个小时”。"}, {"text": "去年班里的人数进步了五个。", "explanation": "这里应该用〈增加〉。“进步”指质量、水平变好，人数这类数量的变化要用“增加”。"}, {"text": "今年的菜价进步了不少。", "explanation": "这里应该用〈上涨〉。“进步”指人的能力或水平变好，物价的升高要用“上涨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进步", "is_correct": true, "explanation": "正确。“进步”表示比以前变好，与“英语”和“得很快”搭配，表示英语水平提高很快。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指闭眼休息，与“英语”无关，不能说“英语睡得很快”。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指身体或物品落下，与“英语”的能力变化无关。"}, {"text": "游", "is_correct": false, "explanation": "配价：“游”的主语应是能游动的人或动物，“他的英语”不能作“游”的主语。"}], "explanations": {"进步": "正确。“进步”表示比以前变好，与“英语”和“得很快”搭配，表示英语水平提高很快。", "睡": "语义：“睡”指闭眼休息，与“英语”无关，不能说“英语睡得很快”。", "摔": "语义：“摔”指身体或物品落下，与“英语”的能力变化无关。", "游": "配价：“游”的主语应是能游动的人或动物，“他的英语”不能作“游”的主语。"}, "sentence_index": 6, "correct_answer": "进步"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的油量进步了很多。", "explanation": "这里应该用〈增加〉。“进步”表示变好，油量这类数量的变化要用“增加”。"}, {"text": "天气进步了，我们可以出去玩了。", "explanation": "这里应该用〈好转〉。“进步”指人的能力或水平变好，天气这类情况变好要用“好转”。"}, {"text": "他的工资进步了，他很开心。", "explanation": "这里应该用〈提高〉。“进步”指水平变好，工资这类数额的变化要用“提高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个学生进步地很快。", "corrected_sentence": "这个学生进步得很快。", "error_description": "“进步”后的补语标记应用“得”，不用“地”。“地”用在动词前修饰动词，“进步得很快”中的“得”引出程度补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的口语进步了得很快。", "corrected_sentence": "她的口语进步得很快。", "error_description": "“了”不能放在动词和补语标记“得”之间。正确说法是“进步得很快”，“了”不放在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
