INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20226, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们用来写和看的符号。", "primary_collocate": null, "pronunciation": "wén zì", "ipa": "wən˧˥ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "汉字是中国人用的文字。", "target_word": "文字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种文字我一个字也看不懂。", "target_word": "文字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们最早用图画记事，后来才有了文字。", "target_word": "文字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的注释是用古代文字写的，很难懂。", "target_word": "文字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学过阿拉伯文字，能看懂路牌。", "target_word": "文字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了文字，人们才能把历史记下来。", "target_word": "文字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上刻着一些古老的文字。", "target_word": "文字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学会了这种文字，能读懂古书。", "target_word": "文字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种文字的笔画很复杂，爷爷学起来很吃力。", "target_word": "文字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的国家有不同的语言和文字。", "target_word": "文字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种文字", "label": "量词（种）"}, {"form": "一段文字", "label": "量词（段）"}, {"form": "文字学", "label": "复合"}], "register": "中性", "sense_fingerprint": "记录语言、供人书写和阅读的符号系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4848e3-df86-4870-9771-0c70385a07a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20226, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "文字", "is_correct": true, "explanation": "正确：文字（wén zì）指记录语言的书写符号。"}, {"text": "蚊子", "is_correct": false, "explanation": "wénzi 与 wén zì 第二音节声调不同（轻声），意思是蚊子。"}, {"text": "闻知", "is_correct": false, "explanation": "wénzhī 与 wénzì 第二音节声母（zh/z）和声调不同，意思是听到而知道。"}, {"text": "纹饰", "is_correct": false, "explanation": "wén shì 与 wén zì 第二音节声母不同，意思是花纹装饰。"}], "explanations": {"文字": "正确：文字（wén zì）指记录语言的书写符号。", "蚊子": "wénzi 与 wén zì 第二音节声调不同（轻声），意思是蚊子。", "闻知": "wénzhī 与 wénzì 第二音节声母（zh/z）和声调不同，意思是听到而知道。", "纹饰": "wén shì 与 wén zì 第二音节声母不同，意思是花纹装饰。"}, "sentence_index": null, "correct_answer": "文字"}, "level_3": {"options": [{"text": "文字", "is_correct": true, "explanation": "正确：“文字”指记录语言的符号，汉字属于此类。"}, {"text": "图片", "is_correct": false, "explanation": "语义：图片不是记录语言的符号，与“汉字是……用的”句意不符。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“用”后一般接文字、工具，“用声音”不能指代书写符号。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：汉字不是乐器，句意矛盾。"}], "explanations": {"文字": "正确：“文字”指记录语言的符号，汉字属于此类。", "图片": "语义：图片不是记录语言的符号，与“汉字是……用的”句意不符。", "声音": "搭配：“用”后一般接文字、工具，“用声音”不能指代书写符号。", "乐器": "语义：汉字不是乐器，句意矛盾。"}, "sentence_index": 0, "correct_answer": "文字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本文字很长，我读了一个下午。", "explanation": "这里应该用〈段〉。量词“本”用于书，文字是书写符号，一段文字要说段。"}, {"text": "中国人每天说文字，交流很方便。", "explanation": "这里应该用〈语言〉。说的是口头语言，文字指书写符号，不能用来“说”。"}, {"text": "这道菜的文字很香，大家都爱吃。", "explanation": "这里应该用〈味道〉。文字指书写符号，菜闻起来、吃起来的感觉要说味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文字", "is_correct": true, "explanation": "正确：“刻着……文字”指墙上刻有古代的字，与句意相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：墙上刻的是符号，不能刻“味道”，句意矛盾。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“刻”的对象一般是字、图案，不能与“颜色”搭配。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”不能被“刻”在墙上，与“刻着”搭配不当。"}], "explanations": {"文字": "正确：“刻着……文字”指墙上刻有古代的字，与句意相符。", "味道": "语义：墙上刻的是符号，不能刻“味道”，句意矛盾。", "颜色": "搭配：“刻”的对象一般是字、图案，不能与“颜色”搭配。", "脚步": "搭配：“脚步”不能被“刻”在墙上，与“刻着”搭配不当。"}, "sentence_index": 6, "correct_answer": "文字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天给孩子唱文字，唱到夜里。", "explanation": "这里应该用〈歌词〉。文字指书写符号，唱的内容要说歌词，文字不能被唱。"}, {"text": "英语单词要用文字拼写，不能写错。", "explanation": "这里应该用〈字母〉。英语用字母拼写单词，文字指整套书写符号。"}, {"text": "他每天听文字，听了很多遍。", "explanation": "这里应该用〈读〉。文字是书写符号，阅读要说读，不能说听文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些文字们都很古老。", "corrected_sentence": "这些文字都很古老。", "error_description": "“文字们”错误：“们”只能加在指人的名词后，“文字”不能加“们”，应说“这些文字”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在博物馆看到一个古老的文字。", "corrected_sentence": "我在博物馆看到一种古老的文字。", "error_description": "“一个文字”应为“一种文字”：“文字”指一套书写符号系统，量词要用“种”，不能用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
