INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20228, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "木板是木头做成的扁平的块。", "primary_collocate": null, "pronunciation": "mù bǎn", "ipa": "mu˥˩ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "爸爸用木板做了一张小桌子。", "target_word": "木板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上放着一块木板。", "target_word": "木板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在墙上钉了一块木板。", "target_word": "木板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木板太重了，我搬不动。", "target_word": "木板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我两块木板。", "target_word": "木板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把木板锯成了两半。", "target_word": "木板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥上的木板坏了，不能走。", "target_word": "木板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用木板搭了一个小房子。", "target_word": "木板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木板很薄，一用力就断了。", "target_word": "木板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一块木板做书架。", "target_word": "木板", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "张", "label": "量词"}], "register": "中性", "sense_fingerprint": "木头做成的扁平板材", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09aebaf0-be95-4ef2-b319-0da839c40a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20228, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "木板", "is_correct": true, "explanation": "木板：扁平的木头板材，可以用来做桌子，符合句意。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是书写工具，不能用来做桌子。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子细长，不是扁平的板，做不成桌面。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能用来做桌子。"}], "explanations": {"木板": "木板：扁平的木头板材，可以用来做桌子，符合句意。", "钢笔": "语义：钢笔是书写工具，不能用来做桌子。", "绳子": "语义：绳子细长，不是扁平的板，做不成桌面。", "面包": "语义：面包是食物，不能用来做桌子。"}, "sentence_index": 0, "correct_answer": "木板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只木板。", "explanation": "这里应该用〈块〉。木板是扁平的块状物，量词用“块”或“张”，“只”通常用于动物。"}, {"text": "他把书放进了木板里。", "explanation": "这里应该用〈木盒〉。木板是平的薄片，不能用来装东西，装东西要用木盒。"}, {"text": "木板可以装满水。", "explanation": "这里应该用〈木桶〉。木板是平的，不能装水，能装满水的是木桶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20228, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木板", "is_correct": true, "explanation": "木板：扁平的木板，能做桥面，符合句意。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不能构成桥面，“坏了不能走”说的是桥面结构。"}, {"text": "面条", "is_correct": false, "explanation": "语义：面条是食物，不能铺在桥上供人行走。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸薄而软，承受不了人的重量，不能当作桥面。"}], "explanations": {"木板": "木板：扁平的木板，能做桥面，符合句意。", "花": "语义：花不能构成桥面，“坏了不能走”说的是桥面结构。", "面条": "语义：面条是食物，不能铺在桥上供人行走。", "纸": "语义：纸薄而软，承受不了人的重量，不能当作桥面。"}, "sentence_index": 6, "correct_answer": "木板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们看了一场木板表演。", "explanation": "这里应该用〈木偶〉。木偶戏是木偶表演，木板是平的木片，不能表演。"}, {"text": "这块木板很透明，能看见外面。", "explanation": "这里应该用〈玻璃〉。木板不透明，形容透明的东西要用玻璃。"}, {"text": "我想买一位木板做书架。", "explanation": "这里应该用〈块〉。“位”用于人，木板是块状物，要用“块”或“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用两只木板做了一个架子。", "corrected_sentence": "他用两块木板做了一个架子。", "error_description": "“两只木板”错误，“只”用于动物等，木板要用“块”或“张”，应改为“两块木板”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把这些木板们搬到了院子里。", "corrected_sentence": "我们把这些木板搬到了院子里。", "error_description": "“木板们”错误，“们”只加在指人的名词后，“木板”不能加“们”，应为“这些木板”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
