INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20232, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "指事情在之前已经发生了。", "primary_collocate": null, "pronunciation": "zǎo jiù", "ipa": "tsɑʊ˨˩ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他早就知道这件事了。", "target_word": "早就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你来得太晚了，电影早就开始了。", "target_word": "早就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早就吃过饭了，不饿。", "target_word": "早就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈早就起床了，在做早饭。", "target_word": "早就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我早就看完了。", "target_word": "早就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们早就是好朋友了。", "target_word": "早就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报早就说今天会下雨。", "target_word": "早就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早就想去北京玩了。", "target_word": "早就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别等了，他早就走了。", "target_word": "早就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不用告诉我，我早就听说了。", "target_word": "早就", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事情在说话之前很久就已经发生，常和了连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b8f789-626d-40d7-a308-633398a91259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早就", "is_correct": true, "explanation": "正确：“早就”表示很久以前已经发生，与“知道……了”相合。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作正在进行，不能与“知道”这类状态动词搭配。"}, {"text": "还没", "is_correct": false, "explanation": "语义：“还没”表示尚未发生，与句中“了”所表示的完成相矛盾。"}, {"text": "常常", "is_correct": false, "explanation": "语义：“常常”表示反复发生的习惯，不能修饰这一次已经完成的“知道”。"}], "explanations": {"早就": "正确：“早就”表示很久以前已经发生，与“知道……了”相合。", "正在": "搭配：“正在”表示动作正在进行，不能与“知道”这类状态动词搭配。", "还没": "语义：“还没”表示尚未发生，与句中“了”所表示的完成相矛盾。", "常常": "语义：“常常”表示反复发生的习惯，不能修饰这一次已经完成的“知道”。"}, "sentence_index": 0, "correct_answer": "早就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早就在图书馆学习。", "explanation": "这里应该用〈总是〉。“早就”指某件事在之前已经发生，表示习惯要用〈总是〉。"}, {"text": "我们明天早就一起去爬山吧。", "explanation": "这里应该用〈打算〉。“早就”指之前已经发生的事，表示明天的计划要用〈打算〉。"}, {"text": "他明年早就毕业。", "explanation": "这里应该用〈会〉。“早就”指之前已经发生，说明年的事要用〈会〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早就", "is_correct": true, "explanation": "正确：“早就”表示天气预报在很久以前已经说过，与句意相合。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”要求施事是人，“天气预报”不能亲自说话。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意为之，与天气预报的性质不符。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：“连忙”表示急切地行动，与“说”这种一般性的陈述不相合。"}], "explanations": {"早就": "正确：“早就”表示天气预报在很久以前已经说过，与句意相合。", "亲自": "搭配：“亲自”要求施事是人，“天气预报”不能亲自说话。", "故意": "语义：“故意”表示有意为之，与天气预报的性质不符。", "连忙": "语义：“连忙”表示急切地行动，与“说”这种一般性的陈述不相合。"}, "sentence_index": 6, "correct_answer": "早就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我现在早就在看书。", "explanation": "这里应该用〈正在〉。“早就”指过去很早已经发生，不能与“现在”正在进行的动作连用。"}, {"text": "请你早就告诉我这件事。", "explanation": "这里应该用〈早点〉。“早就”指之前已经发生的事，请人以后去做要用〈早点〉。"}, {"text": "他早就刚到。", "explanation": "这里“早就”表示很久以前已经发生，与“刚发生”的意思矛盾，应去掉〈早就〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我会早就明白了他的意思。", "corrected_sentence": "我早就明白了他的意思。", "error_description": "错误：能愿动词“会”放在了“早就”之前。副词“早就”应直接修饰动词，去掉“会”，正确为“我早就明白了他的意思”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事我早就就告诉过你了。", "corrected_sentence": "这件事我早就告诉过你了。", "error_description": "错误：“早就”后面多加了一个“就”，副词重复。去掉多余的“就”，正确为“这件事我早就告诉过你了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
