INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20234, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变成不一样的样子。", "primary_collocate": null, "pronunciation": "biàn de", "ipa": "pjɛn⁵¹ tə", "syllable_count": 2, "sentences": [{"text": "天黑以后，风变得很大。", "target_word": "变得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近变得很忙。", "target_word": "变得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，山变得很绿。", "target_word": "变得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明长大后变得很高。", "target_word": "变得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，路变得很滑。", "target_word": "变得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药，他的脸色变得好看了。", "target_word": "变得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，她变得更开心了。", "target_word": "变得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了晚上，街上变得很安静。", "target_word": "变得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市变得越来越漂亮。", "target_word": "变得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的汉语变得比以前好多了。", "target_word": "变得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "變得", "label": "繁体"}], "register": "中性", "sense_fingerprint": "后接形容词，表示变成与以前不同的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fde7ad18-0ff2-44e3-844c-df7b9ce4ca9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "觉得", "is_correct": false, "explanation": "语义：风不能“觉得”，“风觉得很大”主体不对，句子不通。"}, {"text": "变得", "is_correct": true, "explanation": "正确：“变得”表示变成某种状态，风由小变大，与句意相符。"}, {"text": "变成", "is_correct": false, "explanation": "配价：“变成”后面要接名词，不能直接接“很大”。"}, {"text": "发生", "is_correct": false, "explanation": "搭配：“发生”指事件出现，不说风“发生很大”。"}], "explanations": {"觉得": "语义：风不能“觉得”，“风觉得很大”主体不对，句子不通。", "变得": "正确：“变得”表示变成某种状态，风由小变大，与句意相符。", "变成": "配价：“变成”后面要接名词，不能直接接“很大”。", "发生": "搭配：“发生”指事件出现，不说风“发生很大”。"}, "sentence_index": 0, "correct_answer": "变得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地球变得很圆。", "explanation": "这里不用“变得”。“变得”表示由原来的状态改变，地球一直是圆的，应该说“地球是圆的”。"}, {"text": "这个三角形的边数变得很多。", "explanation": "这里不用“变得”。三角形的边数是固定的，不会增加，应直接说明它有几条边，例如“三角形有三条边”。"}, {"text": "圆周率变得很大。", "explanation": "这里不用“变得”。圆周率是固定的数值，不会改变，“变得”暗示数值发生了变化，应说“圆周率是一个固定的数”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进行", "is_correct": false, "explanation": "搭配：“进行”后接的是活动，“她进行更开心了”搭配不通。"}, {"text": "变得", "is_correct": true, "explanation": "正确：“变得”表示她的状态由以前改变为更开心，与“搬家以后”相符。"}, {"text": "出现", "is_correct": false, "explanation": "语义：“出现”指事物显露出来，不表示状态改变，“出现更开心了”句意不通。"}, {"text": "宣布", "is_correct": false, "explanation": "搭配：“宣布”后接的是消息或决定，不能接“更开心了”。"}], "explanations": {"进行": "搭配：“进行”后接的是活动，“她进行更开心了”搭配不通。", "变得": "正确：“变得”表示她的状态由以前改变为更开心，与“搬家以后”相符。", "出现": "语义：“出现”指事物显露出来，不表示状态改变，“出现更开心了”句意不通。", "宣布": "搭配：“宣布”后接的是消息或决定，不能接“更开心了”。"}, "sentence_index": 6, "correct_answer": "变得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的历史变得很短。", "explanation": "这里不用“变得”。城市的历史长短已经固定，不会改变，“变得”表示状态发生变化，应说“这个城市的历史很短”。"}, {"text": "他的年龄变得很小。", "explanation": "这里不用“变得”。一个人的年龄只会增长，不会变小，“变得”表示状态改变，描述年龄应直接说明，如“他很年轻”。"}, {"text": "钻石变得很硬。", "explanation": "这里不用“变得”。钻石的硬度一直如此，“变得”暗示硬度发生了改变，应该说“钻石很硬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天到了，树叶变得了很绿。", "corrected_sentence": "春天到了，树叶变得很绿。", "error_description": "“了”用错位置：“变得”后面直接接形容词，表示变化后的状态，应说“变得很绿”，不能在“得”后面加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市变得了更加热闹了。", "corrected_sentence": "这个城市变得更加热闹了。", "error_description": "“了”用错位置：“变得”后面直接接形容词，不能在“得”后面加“了”，应说“变得更加热闹了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
