INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20236, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用可以移动的单个活字排版，涂上墨，再把纸压上去，就能印出许多一样的页面。", "primary_collocate": null, "pronunciation": "huó zì yìn shuā", "ipa": "xuɔ˧˥ tsɨ˥˩ in˥˩ ʂwa˥", "syllable_count": 4, "sentences": [{"text": "活字印刷是中国人发明的。", "target_word": "活字印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活字印刷让书变得便宜了。", "target_word": "活字印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活字印刷用木头或者泥做字。", "target_word": "活字印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天给我们讲了活字印刷。", "target_word": "活字印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了活字印刷，人们能印很多书。", "target_word": "活字印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕昇发明了活字印刷。", "target_word": "活字印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是用活字印刷印出来的。", "target_word": "活字印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活字印刷比抄书快得多。", "target_word": "活字印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在博物馆看到了活字印刷用的木字。", "target_word": "活字印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的活字印刷对世界很有影响。", "target_word": "活字印刷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "活字印刷术", "label": "复合"}], "register": "中性", "sense_fingerprint": "用可以移动的单个字块排版再印出许多相同页面的印刷技术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9421cf6-24de-499f-a0bb-a94d3893ac19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20236, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活字印刷", "is_correct": true, "explanation": "“活字印刷”是中国人发明的印刷技术，符合句意。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，不是可以被发明的事物，句子不成立。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“发明”多用于技术和工具，不能说“发明眼睛”。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是时间单位，不是可以被发明的技术，句子不成立。"}], "explanations": {"活字印刷": "“活字印刷”是中国人发明的印刷技术，符合句意。", "春天": "语义：“春天”是季节，不是可以被发明的事物，句子不成立。", "眼睛": "搭配：“发明”多用于技术和工具，不能说“发明眼睛”。", "星期": "语义：“星期”是时间单位，不是可以被发明的技术，句子不成立。"}, "sentence_index": 0, "correct_answer": "活字印刷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学习了一只活字印刷。", "explanation": "这里应该用〈项〉或〈种〉。“只”多用于动物和小件物品，“活字印刷”是技术，不能用“只”计量。"}, {"text": "这家工厂每天活字印刷一万份报纸。", "explanation": "这里应该用〈印刷〉。“活字印刷”是名词，指一种技术，不能直接作动词带宾语，表示印的动作要说〈印刷〉。"}, {"text": "我把这份材料活字印刷了三份。", "explanation": "这里应该用〈复印〉。“活字印刷”指印刷技术，不能用来表示复制文件的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活字印刷", "is_correct": true, "explanation": "“用活字印刷”表示用这种技术印书，符合句意。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话不能用来印刷文字，句子不成立。"}, {"text": "相机", "is_correct": false, "explanation": "搭配：相机用于拍照，不能说“用相机印出来”。"}, {"text": "收音机", "is_correct": false, "explanation": "语义：收音机用于播放声音，不能用来印出文字。"}], "explanations": {"活字印刷": "“用活字印刷”表示用这种技术印书，符合句意。", "电话": "语义：电话不能用来印刷文字，句子不成立。", "相机": "搭配：相机用于拍照，不能说“用相机印出来”。", "收音机": "语义：收音机用于播放声音，不能用来印出文字。"}, "sentence_index": 6, "correct_answer": "活字印刷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人正在电脑前活字印刷。", "explanation": "这里应该用〈排版〉。“活字印刷”指印刷技术，不能用来表示在电脑上编排版面。"}, {"text": "学生们每天活字印刷课文。", "explanation": "这里应该用〈抄写〉。“活字印刷”是技术，不能用来表示手工抄录的动作。"}, {"text": "工厂买了一台活字印刷。", "explanation": "这里应该用〈印刷机〉。“活字印刷”是一种技术，不是机器，不能用“台”计量，也不能买来放在工厂里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是活字印刷书。", "corrected_sentence": "这是活字印刷的书。", "error_description": "“活字印刷”修饰名词“书”时要加“的”，应说“活字印刷的书”，不能说“活字印刷书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套词典是把活字印刷印出来的。", "corrected_sentence": "这套词典是用活字印刷印出来的。", "error_description": "“把”用错：“把”字句要求后面是被处置的对象，“活字印刷”是工具，应用介词“用”引出，说“用活字印刷印出来的”；“把活字印刷印出来的”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
