INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20238, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "学会就是通过学习和练习，让自己会做一件事。", "primary_collocate": null, "pronunciation": "xué huì", "ipa": "ɕɥe˧˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我想学会游泳。", "target_word": "学会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我要学会说汉语。", "target_word": "学会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他学会开车了。", "target_word": "学会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你学会做饭了吗？", "target_word": "学会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很快就学会了骑自行车。", "target_word": "学会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子学会走路了。", "target_word": "学会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我还没学会用这个手机。", "target_word": "学会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他学了三年，才学会写汉字。", "target_word": "学会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一个月的练习，我学会了做饺子。", "target_word": "学会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教我，我学会了做中国菜。", "target_word": "学会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "学会了", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：经过学习和练习掌握一种技能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9421cf6-24de-499f-a0bb-a94d3893ac19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学会", "is_correct": true, "explanation": "正确：学会表示通过学习和练习掌握游泳这项技能。"}, {"text": "赢", "is_correct": false, "explanation": "搭配：“赢”要接比赛或对手，不能说赢游泳。"}, {"text": "获得", "is_correct": false, "explanation": "搭配：“获得”多接奖励、资格、经验等，不能说获得游泳。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造出从前没有的事物，游泳是现成的活动，不能发明。"}], "explanations": {"学会": "正确：学会表示通过学习和练习掌握游泳这项技能。", "赢": "搭配：“赢”要接比赛或对手，不能说赢游泳。", "获得": "搭配：“获得”多接奖励、资格、经验等，不能说获得游泳。", "发明": "语义：“发明”指创造出从前没有的事物，游泳是现成的活动，不能发明。"}, "sentence_index": 0, "correct_answer": "学会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天学会一个小时英语。", "explanation": "这里应该用〈学习〉。学会强调掌握的结果，不能用来说持续学习了多长时间。"}, {"text": "我在北京学会了很多朋友。", "explanation": "这里应该用〈认识〉。学会表示掌握技能，不能用来说结识人，本句要表达的是认识了很多朋友。"}, {"text": "我昨天学会了一个好消息。", "explanation": "这里应该用〈听到〉。学会表示掌握技能，消息是听到的，不能说学会消息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学会", "is_correct": true, "explanation": "正确：学会表示通过学习和练习掌握用这个手机的方法。"}, {"text": "学成", "is_correct": false, "explanation": "语义：“学成”指学业完成，句中说的是还不会用手机这样的操作技能，不能用“学成”。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”后面接所买的东西，不能与“用这个手机”组成动作。"}, {"text": "玩", "is_correct": false, "explanation": "配价：“玩”的宾语是玩的对象，不能接“用这个手机”这样的动作。"}], "explanations": {"学会": "正确：学会表示通过学习和练习掌握用这个手机的方法。", "学成": "语义：“学成”指学业完成，句中说的是还不会用手机这样的操作技能，不能用“学成”。", "买": "搭配：“买”后面接所买的东西，不能与“用这个手机”组成动作。", "玩": "配价：“玩”的宾语是玩的对象，不能接“用这个手机”这样的动作。"}, "sentence_index": 6, "correct_answer": "学会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天学会写字。", "explanation": "这里应该用〈练习〉。学会表示一次性掌握的结果，不能用来说每天反复进行的活动。"}, {"text": "我这次学会了一个好成绩。", "explanation": "这里应该用〈取得〉。学会表示掌握技能，好成绩是取得的结果，不能说学会。"}, {"text": "他学会了这份说明书。", "explanation": "这里应该用〈看懂〉。学会用于掌握技能，不能用于理解文字内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹很快就学会着画画。", "corrected_sentence": "妹妹很快就学会了画画。", "error_description": "体标错误：“学会”表示动作已完成并有结果，不能用“着”（“着”表示持续的状态），应说“学会了画画”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天不学会游泳。", "corrected_sentence": "我昨天没学会游泳。", "error_description": "否定词错误：“学会”表示有了结果，否定过去的结果要用“没”，不能用“不”，应说“没学会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
