INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20244, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "金属是像铁、金、铜那样的东西，可以用来做很多东西。", "primary_collocate": null, "pronunciation": "jīn shǔ", "ipa": "tɕin˥ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "铁是一种金属。", "target_word": "金属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "金属摸起来很凉。", "target_word": "金属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这把勺子是金属做的。", "target_word": "金属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "金属可以用来做桌子和椅子。", "target_word": "金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电线里面有金属，能让电通过。", "target_word": "金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "铜和铝都是常见的金属。", "target_word": "金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "金属在火里会变软。", "target_word": "金属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "坐飞机前，要把身上的金属东西拿出来。", "target_word": "金属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子不是塑料的，是金属的。", "target_word": "金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把金属放进火里，让它变热。", "target_word": "金属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "重金属", "label": "复合词"}, {"form": "金属材料", "label": "复合词"}, {"form": "金屬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：铁、金、铜等坚硬、导电、可加工的材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75b6c6b-1a83-43ea-bf8d-cebf12c05e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "金属", "is_correct": true, "explanation": "“铁是一种金属”说铁属于金属材料，符合句意。"}, {"text": "植物", "is_correct": false, "explanation": "语义：铁不是植物，这里不能用。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“一种性格”用于人，铁不能是性格。"}, {"text": "动物", "is_correct": false, "explanation": "语义：铁不是动物，这里不能用。"}], "explanations": {"金属": "“铁是一种金属”说铁属于金属材料，符合句意。", "植物": "语义：铁不是植物，这里不能用。", "性格": "搭配：“一种性格”用于人，铁不能是性格。", "动物": "语义：铁不是动物，这里不能用。"}, "sentence_index": 0, "correct_answer": "金属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我口渴了，想喝一杯金属。", "explanation": "这里应该用〈水〉。金属是铁、铜等材料，不能喝；口渴要喝水。"}, {"text": "妈妈的金属唱歌很好听。", "explanation": "这里应该用〈嗓子〉。金属是材料，不会唱歌；唱歌要用人的嗓子。"}, {"text": "这块金属很甜，孩子们都爱吃。", "explanation": "这里应该用〈糖〉。金属指铁、金、铜等材料，不能指甜的食物，这里要用“糖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金属", "is_correct": true, "explanation": "“金属在火里会变软”说金属遇热变软，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头在火里不会变软，这里不能用。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰遇火会融化，不会变软，这里不能用。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述人或动物的体形，不能在火里变软。"}], "explanations": {"金属": "“金属在火里会变软”说金属遇热变软，符合句意。", "石头": "语义：石头在火里不会变软，这里不能用。", "冰": "语义：冰遇火会融化，不会变软，这里不能用。", "身材": "体貌：身材描述人或动物的体形，不能在火里变软。"}, "sentence_index": 6, "correct_answer": "金属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的金属很精彩，观众都很激动。", "explanation": "这里应该用〈表演〉。金属是材料，不能用来指比赛或演出，这里要用“表演”。"}, {"text": "今天的金属很好，我们去公园玩吧。", "explanation": "这里应该用〈天气〉。金属是材料，不能说今天好不好；要用“天气”。"}, {"text": "我每天早上吃一碗金属。", "explanation": "这里应该用〈米饭〉。金属是铁、铜等材料，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了三只金属。", "corrected_sentence": "我买了三块金属。", "error_description": "错误：“三只金属”，量词“只”用于动物，金属要用“块”。正确：“三块金属”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把把金属搬进了仓库。", "corrected_sentence": "工人把金属搬进了仓库。", "error_description": "错误：“把把金属”，“把”字句中“把”只用一次，重复的“把”是多余的。正确：“工人把金属搬进了仓库”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
