INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20246, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "字母是拼音文字的符号，比如a、b、c。", "primary_collocate": null, "pronunciation": "zì mǔ", "ipa": "tsɨ˥˩ mu˨˩˦", "syllable_count": 2, "sentences": [{"text": "英语有二十六个字母。", "target_word": "字母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请写出这个字母的大写。", "target_word": "字母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他还不认识所有的字母。", "target_word": "字母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字母怎么读？", "target_word": "字母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在纸上写了三个字母。", "target_word": "字母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语拼音也用英文字母。", "target_word": "字母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的名字第一个字母是什么？", "target_word": "字母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小写字母和大写字母不一样。", "target_word": "字母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写着一个字母。", "target_word": "字母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先学字母，再学单词。", "target_word": "字母", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大写字母", "label": "复合词"}, {"form": "小写字母", "label": "复合词"}], "register": "中性", "sense_fingerprint": "拼音文字中表示声音的书写符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b8f789-626d-40d7-a308-633398a91259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "笔画", "is_correct": false, "explanation": "搭配：“笔画”用于计算汉字的书写笔数，不能用来数英语的符号。"}, {"text": "字母", "is_correct": true, "explanation": "字母是拼音文字的符号，英语的二十六个符号正是字母。"}, {"text": "偏旁", "is_correct": false, "explanation": "语义：偏旁是汉字的组成部件，英语的二十六个符号不是偏旁。"}, {"text": "汉字", "is_correct": false, "explanation": "语义：汉字是汉语的书写单位，英语没有汉字，“英语有二十六个汉字”与事实不符。"}], "explanations": {"笔画": "搭配：“笔画”用于计算汉字的书写笔数，不能用来数英语的符号。", "字母": "字母是拼音文字的符号，英语的二十六个符号正是字母。", "偏旁": "语义：偏旁是汉字的组成部件，英语的二十六个符号不是偏旁。", "汉字": "语义：汉字是汉语的书写单位，英语没有汉字，“英语有二十六个汉字”与事实不符。"}, "sentence_index": 0, "correct_answer": "字母"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个汉字一共有七个字母。", "explanation": "这里应该用〈笔画〉。字母是拼音文字的符号，汉字的书写单位是笔画，不能用字母来数汉字。"}, {"text": "这个字的字母是氵。", "explanation": "这里应该用〈偏旁〉。字母指拼音文字中的字符，“氵”是汉字的偏旁，不是字母。"}, {"text": "这个交通标志是一种字母。", "explanation": "这里应该用〈符号〉。字母是拼音文字中的字符，交通标志属于图形符号，不能叫字母。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数字", "is_correct": false, "explanation": "语义：名字的第一个不会是数字，“你的名字第一个数字是什么”语义不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：名字不是颜色，“第一个颜色”与“名字”的语义矛盾。"}, {"text": "字母", "is_correct": true, "explanation": "字母是拼音文字的符号，名字的第一个字母即首字母。"}, {"text": "音符", "is_correct": false, "explanation": "搭配：“音符”搭配的是乐谱和音乐，不能说名字的音符。"}], "explanations": {"数字": "语义：名字的第一个不会是数字，“你的名字第一个数字是什么”语义不通。", "颜色": "语义：名字不是颜色，“第一个颜色”与“名字”的语义矛盾。", "字母": "字母是拼音文字的符号，名字的第一个字母即首字母。", "音符": "搭配：“音符”搭配的是乐谱和音乐，不能说名字的音符。"}, "sentence_index": 6, "correct_answer": "字母"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用一个字母来形容天气。", "explanation": "这里应该用〈词语〉。字母是拼音文字的符号，不能表达意思，形容天气要用词语。"}, {"text": "他能背下三千个字母。", "explanation": "这里应该用〈单词〉。字母只有二十六个，能背下的是单词，三千个字母不符合字母的含义。"}, {"text": "这个字母很热心，经常帮助别人。", "explanation": "这里应该用〈人〉。字母只是拼音文字的符号，不会热心地帮助别人，应说“这个人很热心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他能写出二十六只字母。", "corrected_sentence": "他能写出二十六个字母。", "error_description": "量词错误：字母应搭配量词“个”，“只”用于动物等，不能用于字母。正确说法是“二十六个字母”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹已经认识了五张字母。", "corrected_sentence": "我妹妹已经认识了五个字母。", "error_description": "量词错误：字母应搭配量词“个”，“张”用于纸张、桌子等平面的东西。正确说法是“五个字母”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
