INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20248, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有钱的人。", "primary_collocate": null, "pronunciation": "fù rén", "ipa": "fu˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "这个城市里住着很多富人。", "target_word": "富人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "富人的房子又大又漂亮。", "target_word": "富人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候家里穷，现在已经是富人了。", "target_word": "富人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "富人也应该帮助穷人。", "target_word": "富人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些富人喜欢开很贵的汽车。", "target_word": "富人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山上的别墅都是富人买的。", "target_word": "富人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位富人给学校捐了一百万。", "target_word": "富人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "富人的生活不一定比我们快乐。", "target_word": "富人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的客人大多是富人。", "target_word": "富人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他希望有一天成为富人。", "target_word": "富人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位富人", "label": "量词"}, {"form": "一个富人", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，很有钱的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c13fba2-698e-4727-b25b-42f4c360e701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20248, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "富人", "is_correct": true, "explanation": "正确答案：富人（fù rén），指有钱的人。"}, {"text": "夫人", "is_correct": false, "explanation": "fū（第一声）与 fù（第四声）声调不同，夫人指妻子或对女性的尊称。"}, {"text": "赴任", "is_correct": false, "explanation": "第二个音节 rèn（第四声）与 rén（第二声）声调不同，赴任指到新岗位就职。"}, {"text": "路人", "is_correct": false, "explanation": "lù 与 fù 声母不同（l 与 f），路人指路上的行人。"}, {"text": "故人", "is_correct": false, "explanation": "gù 与 fù 声母不同（g 与 f），故人指老朋友。"}], "explanations": {"富人": "正确答案：富人（fù rén），指有钱的人。", "夫人": "fū（第一声）与 fù（第四声）声调不同，夫人指妻子或对女性的尊称。", "赴任": "第二个音节 rèn（第四声）与 rén（第二声）声调不同，赴任指到新岗位就职。", "路人": "lù 与 fù 声母不同（l 与 f），路人指路上的行人。", "故人": "gù 与 fù 声母不同（g 与 f），故人指老朋友。"}, "sentence_index": null, "correct_answer": "富人"}, "level_3": {"options": [{"text": "富人", "is_correct": true, "explanation": "正确：富人指有钱的人，“住着”的主语是人，句子成立。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“住着”的主语须是人或动物，石头不能住在城市里。"}, {"text": "财富", "is_correct": false, "explanation": "配价：“住着”的对象须是人或动物，财富不能住在城市里，句子不通。"}, {"text": "树木", "is_correct": false, "explanation": "语义：“住着”只用于人或动物，树木不能说“住着很多”。"}], "explanations": {"富人": "正确：富人指有钱的人，“住着”的主语是人，句子成立。", "石头": "语义：“住着”的主语须是人或动物，石头不能住在城市里。", "财富": "配价：“住着”的对象须是人或动物，财富不能住在城市里，句子不通。", "树木": "语义：“住着”只用于人或动物，树木不能说“住着很多”。"}, "sentence_index": 0, "correct_answer": "富人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的老板很富人。", "explanation": "这里应该用〈有钱〉。“富人”是名词，指有钱的人，不能放在“很”后面作形容词用。"}, {"text": "日本是一个富人。", "explanation": "这里应该用〈富国〉。富人指有钱的人，说国家富有要用〈富国〉。"}, {"text": "他是一个知识富人。", "explanation": "富人只指有钱的人，不能比喻学识丰富，这里的意思不能用“富人”表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "富人", "is_correct": true, "explanation": "正确：富人指有钱的人，可以捐钱给学校，句子成立。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐没有钱，不能捐出一百万。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能捐钱，且“那位”用于指人，不能指石头。"}, {"text": "穷人", "is_correct": false, "explanation": "语义：穷人收入少，不能捐出一百万，与句意矛盾。"}], "explanations": {"富人": "正确：富人指有钱的人，可以捐钱给学校，句子成立。", "乞丐": "语义：乞丐没有钱，不能捐出一百万。", "石头": "语义：石头不能捐钱，且“那位”用于指人，不能指石头。", "穷人": "语义：穷人收入少，不能捐出一百万，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "富人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家现在很富人了。", "explanation": "这里应该用〈富有〉。“富人”是名词，指有钱的人，不能受“很”修饰来描述家庭的状况。"}, {"text": "这些富人都是他一生积累的。", "explanation": "这里应该用〈财富〉。积累的是钱财，富人指人，不能作为被积累的对象。"}, {"text": "这本书的内容很富人。", "explanation": "这里应该用〈丰富〉。“富人”只指有钱的人，不能形容内容多。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只富人住在山上的别墅里。", "corrected_sentence": "那位富人住在山上的别墅里。", "error_description": "量词错误：指人的“富人”应用〈位〉，不能用动物量词〈只〉。错误形式“那只富人”，正确形式“那位富人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的叔叔是一位富人们。", "corrected_sentence": "我的叔叔是一位富人。", "error_description": "错误在于“富人”后多加了复数词尾“们”。“一位”已表示数量，名词后不能再加“们”，应说“一位富人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
