INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20250, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西再用一次。", "primary_collocate": null, "pronunciation": "chóng fù shǐ yòng", "ipa": "ʈʂʰʊŋ˧˥ fu˥˩ ʂɨ˨˩ jʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这个杯子可以重复使用。", "target_word": "重复使用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料袋洗干净后能重复使用。", "target_word": "重复使用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了环保，我们要重复使用旧东西。", "target_word": "重复使用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种筷子不能重复使用，用完就扔。", "target_word": "重复使用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把用过的旧纸重复使用了，拿来写草稿。", "target_word": "重复使用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重复使用旧瓶子，可以少扔很多垃圾。", "target_word": "重复使用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些布袋我重复使用过很多次。", "target_word": "重复使用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重复使用水杯比买一次性杯子省钱。", "target_word": "重复使用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，旧信封可以重复使用。", "target_word": "重复使用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的购物袋你可以重复使用。", "target_word": "重复使用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重复使用了", "label": "体标"}, {"form": "重复使用过", "label": "体标"}], "register": "中性", "sense_fingerprint": "同一样东西用完后再用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60fb9430-b8df-4950-a53e-fc0e3676837a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重复使用", "is_correct": true, "explanation": "重复使用：把东西再次使用，与句中“杯子”的用途相符。"}, {"text": "食用", "is_correct": false, "explanation": "语义：“食用”只用于食物，杯子不能被吃。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：杯子不能被驾驶，与句子的语境不合。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”搭配音乐、视频，不搭配杯子。"}], "explanations": {"重复使用": "重复使用：把东西再次使用，与句中“杯子”的用途相符。", "食用": "语义：“食用”只用于食物，杯子不能被吃。", "驾驶": "语义：杯子不能被驾驶，与句子的语境不合。", "播放": "搭配：“播放”搭配音乐、视频，不搭配杯子。"}, "sentence_index": 0, "correct_answer": "重复使用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把过期的牛奶重复使用了。", "explanation": "这里应该用〈扔掉〉。“重复使用”指把东西再次利用；过期的食品不能再吃，应当扔掉。"}, {"text": "他每天重复使用这个动作。", "explanation": "这里应该用〈重复〉。动作是做的，不是物品，说“重复这个动作”；“重复使用”指把物品再次利用。"}, {"text": "我昨天重复使用了那部电影，看了三遍。", "explanation": "这里应该用〈重看〉。“重复使用”只用于把物品再次利用，看电影、看书这类再次欣赏要用“重看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重复使用", "is_correct": true, "explanation": "重复使用：把布袋再次使用，符合“用过很多次”的语境。"}, {"text": "完成", "is_correct": false, "explanation": "语义：“完成”的对象是任务、工作，布袋不能作为它的宾语。"}, {"text": "报名", "is_correct": false, "explanation": "搭配：“报名”的对象是活动、比赛，不搭配布袋。"}, {"text": "注册", "is_correct": false, "explanation": "语义：“注册”用于账号、公司等，布袋不能注册。"}], "explanations": {"重复使用": "重复使用：把布袋再次使用，符合“用过很多次”的语境。", "完成": "语义：“完成”的对象是任务、工作，布袋不能作为它的宾语。", "报名": "搭配：“报名”的对象是活动、比赛，不搭配布袋。", "注册": "语义：“注册”用于账号、公司等，布袋不能注册。"}, "sentence_index": 6, "correct_answer": "重复使用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要充分重复使用课余时间。", "explanation": "这里应该用〈利用〉。时间不是物品，不能“重复使用”；利用可用于时间、资源。"}, {"text": "我每天重复使用午饭。", "explanation": "这里应该用〈吃〉。“重复使用”只用于把物品再次利用，午饭吃过就没有了，不能重复使用。"}, {"text": "我每天重复使用课文。", "explanation": "这里应该用〈复习〉。把学过的课文再学一遍用“复习”，“重复使用”只用于物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个旧瓶子洗干净后，我就能了重复使用。", "corrected_sentence": "这个旧瓶子洗干净后，我就能重复使用。", "error_description": "“了”位置错误：“了”插在“能”和“重复使用”之间是错误的，应删去，说“就能重复使用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些旧布袋洗干净以后，就把重复使用。", "corrected_sentence": "这些旧布袋洗干净以后，就把它们重复使用。", "error_description": "“把”字句漏了宾语：“把”后面要有被处置的宾语，应说“把它们重复使用”，不能说“把重复使用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
