INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20252, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情的方式。", "primary_collocate": null, "pronunciation": "fāng fǎ", "ipa": "faŋ˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "学汉语有什么好方法？", "target_word": "方法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个方法很简单，你也可以试试。", "target_word": "方法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要想一个新方法。", "target_word": "方法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师教了我一种记生词的方法。", "target_word": "方法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用这个方法做出了蛋糕。", "target_word": "方法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人学习的方法不一样。", "target_word": "方法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有没有提高口语的好方法？", "target_word": "方法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种方法太慢了，我们换一个吧。", "target_word": "方法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把你的方法告诉大家。", "target_word": "方法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "解决问题的方法不止一个。", "target_word": "方法", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "学习方法", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事情、解决问题所用的方式和办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98e58837-c3d8-404d-95dd-38296864162d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方法", "is_correct": true, "explanation": "正确答案：“好方法”指做事情的好办法，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：学汉语和颜色无关，这里需要表示做事方式的词。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“好房子”可以说，但“学汉语有什么好房子”不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：学汉语和天气无关，句子问的是做事的办法。"}], "explanations": {"方法": "正确答案：“好方法”指做事情的好办法，符合句意。", "颜色": "语义：学汉语和颜色无关，这里需要表示做事方式的词。", "房子": "搭配：“好房子”可以说，但“学汉语有什么好房子”不成立。", "天气": "语义：学汉语和天气无关，句子问的是做事的办法。"}, "sentence_index": 0, "correct_answer": "方法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方法太重了，我抬不动。", "explanation": "这里应该用〈箱子〉。“重”形容有重量的具体物品，“方法”是抽象的，不能用重量来形容。"}, {"text": "老师教了我一本记生词的方法。", "explanation": "这里应该用〈种〉或〈个〉。“方法”不能用量词“本”，“本”通常用于书籍。"}, {"text": "我们还要办一些方法才能进去。", "explanation": "这里应该用〈手续〉。“办手续”是固定搭配，“办方法”不这么说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方法", "is_correct": true, "explanation": "正确答案：“提高口语的好方法”指提高口语的好办法，符合句意。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：提高口语和饮料无关，句子问的是提高口语的途径。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“提高口语”不需要书包，这里问的是方式。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“好房间”可以说，但“提高口语的好房间”不搭配。"}], "explanations": {"方法": "正确答案：“提高口语的好方法”指提高口语的好办法，符合句意。", "饮料": "语义：提高口语和饮料无关，句子问的是提高口语的途径。", "书包": "语义：“提高口语”不需要书包，这里问的是方式。", "房间": "搭配：“好房间”可以说，但“提高口语的好房间”不搭配。"}, "sentence_index": 6, "correct_answer": "方法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把方法放在桌子上了。", "explanation": "这里应该用〈书〉。“方法”是抽象的做事方式，不是具体物品，不能放在桌子上。"}, {"text": "这个方法吃起来很好吃。", "explanation": "“方法”不是食物，不能用来吃，这里把抽象概念当成了具体对象。"}, {"text": "他的口语方法跑得很快。", "explanation": "这里应该用〈进步〉。“跑”形容人或车的移动，抽象的“方法”不能跑；应说“他的口语进步得很快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们可以试一本方法。", "corrected_sentence": "我们可以试一种方法。", "error_description": "量词错误：“方法”不能用书籍的量词“本”，应为“一种方法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些方法们都很好。", "corrected_sentence": "这些方法都很好。", "error_description": "“方法们”错误：“们”只用于指人，“方法”后面不能加“们”，应为“这些方法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
