INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20258, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把书上的字念出来。", "primary_collocate": null, "pronunciation": "dú", "ipa": "tu˧˥", "syllable_count": 1, "sentences": [{"text": "老师请小明读这个句子。", "target_word": "读", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你大声读一遍课文。", "target_word": "读", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上大声读英语。", "target_word": "读", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子正在给妈妈读故事。", "target_word": "读", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字我不会读。", "target_word": "读", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读得很慢，但是很清楚。", "target_word": "读", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起读一下这首诗吧。", "target_word": "读", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们跟着他读。", "target_word": "读", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶眼睛不好，我给她读报纸。", "target_word": "读", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能大声读一下这段话吗？", "target_word": "读", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "读了", "label": "体标"}, {"form": "读过", "label": "体标"}, {"form": "读着", "label": "体标"}, {"form": "读读", "label": "重叠"}, {"form": "讀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "读：把书上的文字念出声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09aebaf0-be95-4ef2-b319-0da839c40a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20258, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "读", "is_correct": true, "explanation": "读：把书上的字念出声音，是本题的正确答案。"}, {"text": "度", "is_correct": false, "explanation": "dù（第四声）与 dú（第二声）声调不同，意思是度量、程度。"}, {"text": "堵", "is_correct": false, "explanation": "dǔ（第三声）与 dú（第二声）声调不同，意思是阻挡。"}, {"text": "图", "is_correct": false, "explanation": "tú 与 dú 声母 t 与 d 不同，意思是图画。"}], "explanations": {"读": "读：把书上的字念出声音，是本题的正确答案。", "度": "dù（第四声）与 dú（第二声）声调不同，意思是度量、程度。", "堵": "dǔ（第三声）与 dú（第二声）声调不同，意思是阻挡。", "图": "tú 与 dú 声母 t 与 d 不同，意思是图画。"}, "sentence_index": null, "correct_answer": "读"}, "level_3": {"options": [{"text": "读", "is_correct": true, "explanation": "读：把书上的字念出声音，符合“请小明……这个句子”的句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：句子是文字，不能吃。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”一般搭配饮料，不能和“句子”搭配。"}, {"text": "踢", "is_correct": false, "explanation": "语义：句子是文字，不能用脚去踢。"}], "explanations": {"读": "读：把书上的字念出声音，符合“请小明……这个句子”的句意。", "吃": "语义：句子是文字，不能吃。", "喝": "搭配：“喝”一般搭配饮料，不能和“句子”搭配。", "踢": "语义：句子是文字，不能用脚去踢。"}, "sentence_index": 0, "correct_answer": "读"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子正在给妈妈读歌。", "explanation": "这里应该用〈唱〉。读用于文字，唱歌要用唱。"}, {"text": "他在纸上读了一只猫。", "explanation": "这里应该用〈画〉。读的对象是文字，画猫要用画。"}, {"text": "我昨晚读了一部电影。", "explanation": "这里应该用〈看〉。读用于文字，看电影要用看，“读电影”不这么说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20258, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "读", "is_correct": true, "explanation": "读：把书上的字念出声音，是本题的正确答案。"}, {"text": "赌", "is_correct": false, "explanation": "dǔ（第三声）与 dú（第二声）声调不同，意思是打赌。"}, {"text": "途", "is_correct": false, "explanation": "tú 与 dú 只差声母（t 与 d），意思是道路，不是念出声音。"}, {"text": "渡", "is_correct": false, "explanation": "dù（第四声）与 dú（第二声）声调不同，意思是过河、渡过。"}], "explanations": {"读": "读：把书上的字念出声音，是本题的正确答案。", "赌": "dǔ（第三声）与 dú（第二声）声调不同，意思是打赌。", "途": "tú 与 dú 只差声母（t 与 d），意思是道路，不是念出声音。", "渡": "dù（第四声）与 dú（第二声）声调不同，意思是过河、渡过。"}, "sentence_index": null, "correct_answer": "读"}, "level_3": {"options": [{"text": "读", "is_correct": true, "explanation": "读：把书上的字念出声音，符合“我们一起……一下这首诗”的句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：诗是文字，不能拿来煮。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”一般搭配衣服，不说“穿诗”。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”是用脚踏，与“这首诗”的动作不相符。"}], "explanations": {"读": "读：把书上的字念出声音，符合“我们一起……一下这首诗”的句意。", "煮": "语义：诗是文字，不能拿来煮。", "穿": "搭配：“穿”一般搭配衣服，不说“穿诗”。", "踩": "语义：“踩”是用脚踏，与“这首诗”的动作不相符。"}, "sentence_index": 6, "correct_answer": "读"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他读了一张照片。", "explanation": "这里应该用〈拍〉。读的对象是文字，照片要用拍。"}, {"text": "我们在读音乐。", "explanation": "这里应该用〈听〉。读用于文字，音乐要用听。"}, {"text": "他读了一杯茶。", "explanation": "这里应该用〈喝〉。读用于文字，茶要用喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
