INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20260, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "卖", "is_correct": true, "explanation": "正确答案：“卖”与“买”相反，指把东西换成钱交给别人。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”指把食物咽下，与“买”没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "“看”指用眼睛观察，与“买”没有反义关系。"}, {"text": "说", "is_correct": false, "explanation": "“说”指用语言表达，与“买”没有反义关系。"}], "correct_answer": "卖", "explanations": {"卖": "正确答案：“卖”与“买”相反，指把东西换成钱交给别人。", "吃": "“吃”指把食物咽下，与“买”没有反义关系。", "看": "“看”指用眼睛观察，与“买”没有反义关系。", "说": "“说”指用语言表达，与“买”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
