INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20260, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "买", "is_correct": true, "explanation": "正确答案：买，表示付钱得到东西。"}, {"text": "卖", "is_correct": false, "explanation": "mài（第四声）与 mǎi（第三声）声调不同，意思是卖出。"}, {"text": "美", "is_correct": false, "explanation": "měi 与 mǎi 的韵母不同（ei 与 ai），意思是美丽。"}, {"text": "奶", "is_correct": false, "explanation": "nǎi 与 mǎi 的声母不同（n 与 m），意思是牛奶。"}, {"text": "埋", "is_correct": false, "explanation": "mái（第二声）与 mǎi（第三声）声调不同，意思是埋藏。"}], "explanations": {"买": "正确答案：买，表示付钱得到东西。", "卖": "mài（第四声）与 mǎi（第三声）声调不同，意思是卖出。", "美": "měi 与 mǎi 的韵母不同（ei 与 ai），意思是美丽。", "奶": "nǎi 与 mǎi 的声母不同（n 与 m），意思是牛奶。", "埋": "mái（第二声）与 mǎi（第三声）声调不同，意思是埋藏。"}, "sentence_index": null, "correct_answer": "买"}, "level_3": {"options": [{"text": "买", "is_correct": true, "explanation": "正确答案：“买”表示付钱得到，与“我想去商店”和“一件新衣服”搭配自然。"}, {"text": "修", "is_correct": false, "explanation": "语义：新衣服没有坏，不需要修理。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能以“衣服”为对象。"}, {"text": "站", "is_correct": false, "explanation": "配价：“站”是不及物动词，后面不能带“新衣服”作宾语。"}], "explanations": {"买": "正确答案：“买”表示付钱得到，与“我想去商店”和“一件新衣服”搭配自然。", "修": "语义：新衣服没有坏，不需要修理。", "唱": "搭配：“唱”的对象是歌曲，不能以“衣服”为对象。", "站": "配价：“站”是不及物动词，后面不能带“新衣服”作宾语。"}, "sentence_index": 0, "correct_answer": "买"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向朋友买了五块钱。", "explanation": "这里应该用〈借〉。向别人借钱要说借，不能说买。"}, {"text": "他用一本书买了一瓶水。", "explanation": "这里应该用〈换〉。用物品交换要说换，买需要付钱。"}, {"text": "他买了我一个问题。", "explanation": "这里应该用〈问〉。问题是提出或问的，不能用“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20260, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "买", "is_correct": true, "explanation": "正确答案：买，表示付钱得到东西。"}, {"text": "摆", "is_correct": false, "explanation": "bǎi 与 mǎi 的声母不同（b 与 m），意思是摆放。"}, {"text": "没", "is_correct": false, "explanation": "méi（第二声）与 mǎi 的韵母和声调都不同，意思是没有。"}, {"text": "麦", "is_correct": false, "explanation": "mài（第四声）与 mǎi（第三声）声调不同，意思是小麦。"}, {"text": "白", "is_correct": false, "explanation": "bái（第二声）与 mǎi 的声母不同（b 与 m）且声调不同，意思是白色。"}], "explanations": {"买": "正确答案：买，表示付钱得到东西。", "摆": "bǎi 与 mǎi 的声母不同（b 与 m），意思是摆放。", "没": "méi（第二声）与 mǎi 的韵母和声调都不同，意思是没有。", "麦": "mài（第四声）与 mǎi（第三声）声调不同，意思是小麦。", "白": "bái（第二声）与 mǎi 的声母不同（b 与 m）且声调不同，意思是白色。"}, "sentence_index": null, "correct_answer": "买"}, "level_3": {"options": [{"text": "买", "is_correct": true, "explanation": "正确答案：“买过”表示有过买的经历，与“哥哥给我”和“蛋糕”搭配自然。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”的对象是书报，不能说读蛋糕。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说写蛋糕。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，后面不能带“蛋糕”作宾语。"}], "explanations": {"买": "正确答案：“买过”表示有过买的经历，与“哥哥给我”和“蛋糕”搭配自然。", "读": "搭配：“读”的对象是书报，不能说读蛋糕。", "写": "搭配：“写”的对象是文字，不能说写蛋糕。", "跑": "配价：“跑”是不及物动词，后面不能带“蛋糕”作宾语。"}, "sentence_index": 6, "correct_answer": "买"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一封朋友的来信。", "explanation": "这里应该用〈收〉。来信是收到的，不能用“买”。"}, {"text": "他买了一句谎话。", "explanation": "这里应该用〈说〉。谎话是说出来的，不能用“买”。"}, {"text": "她买了一个笑话。", "explanation": "这里应该用〈讲〉。笑话是讲的，不能用“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了到一本词典。", "corrected_sentence": "我昨天买到了一本词典。", "error_description": "结果补语“到”应紧跟在“买”后面，“了”要放在“到”之后，不能插在“买”和“到”之间。正确是“买到了一本词典”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐给我买了过一件很好的衣服。", "corrected_sentence": "姐姐给我买过一件很好的衣服。", "error_description": "“了”和“过”不能同时用在动词后面，表示经历只用“过”。正确是“买过一件很好的衣服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
